export const DEPARTMENT_NOTES={"arizona-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and analysis & PDE at Arizona State University. The faculty examples below describe research in those areas.","Jonathan Montaño’s listed work concerns commutative algebra, symbolic powers, determinantal varieties and blowup algebras. Nancy Childress’s listed work concerns algebraic number theory and p-adic analysis; institutional publication listing is old, so recent activity needs direct confirmation.","John Jones’s listed work concerns computational algebraic number theory, number fields and p-adic fields; earlier work on Iwasawa theory and Artin representations. Julien Paupert’s listed work concerns complex hyperbolic geometry, arithmetic lattices, cusps and reflection groups; geometric rather than primarily algebraic geometry fit. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty","url":"https://math.asu.edu/faculty/all","checked":"2026-11-05"},{"label":"Current faculty affiliation and research","url":"https://search.asu.edu/profile/49694","checked":"2026-11-05"},{"label":"ASU research portal: Montaño","url":"https://asu.elsevierpure.com/en/persons/jonathan-monta%C3%B1o/","checked":"2026-11-05"},{"label":"ASU research portal: Childress","url":"https://asu.elsevierpure.com/en/persons/nancy-childress/","checked":"2026-11-05"},{"label":"Arizona Regents research portal: Paupert","url":"https://experts.azregents.edu/en/persons/julien-paupert/","checked":"2026-11-05"},{"label":"John Jones research / publication evidence","url":"https://hobbes.la.asu.edu/papers.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":128,"facultyNames":["Jonathan Montaño","Nancy Childress","John Jones","Julien Paupert"]},"auburn-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, probability, and algebraic geometry at Auburn University. The faculty examples below describe research in those areas.","Henry (Hal) Schenck’s listed work concerns toric varieties, arrangements, syzygies, Gorenstein rings and computational geometry; applications to physics and dynamics. Luke Oeding’s listed work concerns tensor geometry, invariant/representation theory, secant varieties and quantum information.","Michael K. Brown’s listed work concerns derived categories, toric varieties, sheaf cohomology, matrix factorizations and homological mirror symmetry. Douglas Leonard’s listed work concerns desingularization of function fields, integral closures, algebraic-geometric codes and algebraic combinatorics. Official personal page latest dated 2019; recent activity and supervision need confirmation. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current research faculty","url":"https://cosam.auburn.edu/math/research-areas/","checked":"2026-11-05"},{"label":"Michael Brown research and papers","url":"https://webhome.auburn.edu/~mkb0096/","checked":"2026-11-05"},{"label":"Luke Oeding publications","url":"https://webhome.auburn.edu/~lao0004/papers.html","checked":"2026-11-05"},{"label":"Hal Schenck research and papers","url":"https://webhome.auburn.edu/~hks0015/","checked":"2026-11-05"},{"label":"Douglas Leonard official research page","url":"https://webhome.auburn.edu/~leonada/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":135,"facultyNames":["Henry (Hal) Schenck","Luke Oeding","Michael K. Brown","Douglas Leonard"]},"baylor-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, combinatorics, geometry, and topology at Baylor University. The faculty examples below describe research in those areas.","Arik Wilbert’s listed work concerns Springer varieties, geometric and combinatorial representation theory, categorification, and connections to low-dimensional topology.","Markus Hunziker’s listed work concerns Lie-group representations, invariant theory and covariants, highest-weight modules, and associated algebraic geometry and combinatorics. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current graduate faculty","url":"https://math.artsandsciences.baylor.edu/graduate-program/graduate-faculty","checked":"2026-11-05"},{"label":"Hunziker profile and recent publications","url":"https://math.artsandsciences.baylor.edu/person/markus-hunziker-phd","checked":"2026-11-05"},{"label":"Wilbert current appointment","url":"https://math.artsandsciences.baylor.edu/person/arik-wilbert-phd","checked":"2026-11-05"},{"label":"Wilbert: Two-row Delta Springer varieties","url":"https://alco.centre-mersenne.org/articles/10.5802/alco.435/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":142,"facultyNames":["Arik Wilbert","Markus Hunziker"]},"binghamton-university-suny":{"paragraphs":["The supplied dossier emphasizes geometry, algebra & representation theory, and number theory at Binghamton University, SUNY. The faculty examples below describe research in those areas.","Pratik Misra’s listed work concerns algebraic statistics and graphical models: an applied-algebraic-geometry fit rather than classical/arithmetic geometry. Alexander Borisov’s listed work concerns birational/toric geometry, polynomial morphisms and arithmetic questions.","Adrian Vasiu’s listed work concerns Shimura varieties, abelian/group schemes, Galois representations and arithmetic differential geometry. Marcin Mazur’s listed work concerns group schemes, integral group rings, Galois modules and Galois representations. Recent paper not verified on the official profile/homepage. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Faculty directory","url":"https://www.binghamton.edu/math/faculty.html","checked":"2026-11-05"},{"label":"Borisov papers","url":"https://people.math.binghamton.edu/borisov/research.html","checked":"2026-11-05"},{"label":"Vasiu papers","url":"https://people.math.binghamton.edu/adrian/","checked":"2026-11-05"},{"label":"Mazur research","url":"https://www.binghamton.edu/apps/directory/person/profile/mmazur","checked":"2026-11-05"},{"label":"Misra research","url":"https://www.binghamton.edu/apps/directory/person/profile/pmisra","checked":"2026-11-05"},{"label":"Misra SUNY publications","url":"https://researchconnect.suny.edu/en/persons/pratik-misra/","checked":"2026-11-05"},{"label":"Mazur personal page","url":"https://people.math.binghamton.edu/mazur/","checked":"2026-11-05"},{"label":"Marcin Mazur publication verification","url":"https://people.math.binghamton.edu/mazur/papers/pub12.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":148,"facultyNames":["Pratik Misra","Alexander Borisov","Adrian Vasiu","Marcin Mazur"]},"boston-college":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and dynamical systems at Boston College. The faculty examples below describe research in those areas.","Benjamin Howard’s listed work concerns arithmetic geometry, cycles on unitary Rapoport-Zink spaces, arithmetic intersection formulas, local Whittaker functions and Hecke correspondences. David Treumann’s listed work concerns sheaves, mirror symmetry and geometric representation theory.","Dubi Kelmer’s listed work concerns analytic number theory and homogeneous dynamics, quadratic forms, quantitative Diophantine approximation and rational points. Dawei Chen’s listed work concerns moduli of curves/differentials, with connections to Teichmüller dynamics. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics PhD program","url":"https://www.bc.edu/bc-web/schools/morrissey/departments/math/graduate/phd-program.html","checked":"2026-11-05"},{"label":"David Treumann faculty","url":"https://www.bc.edu/bc-web/schools/morrissey/departments/math/people/faculty-directory/david-treumann.html","checked":"2026-11-05"},{"label":"Faculty affiliation and research","url":"https://www.bc.edu/bc-web/schools/morrissey/departments/math/people/faculty-directory/dubi-kelmer.html","checked":"2026-11-05"},{"label":"Dawei Chen research","url":"https://sites.google.com/bc.edu/dawei-chen","checked":"2026-11-05"},{"label":"Benjamin Howard faculty","url":"https://www.bc.edu/bc-web/schools/morrissey/departments/math/people/faculty-directory/benjamin-howard.html","checked":"2026-11-05"},{"label":"Benjamin Howard research","url":"https://sites.google.com/bc.edu/benjamin-howard/research","checked":"2026-11-05"},{"label":"Jin-Treumann paper publication","url":"https://londmathsoc.onlinelibrary.wiley.com/doi/abs/10.1112/topo.12325","checked":"2026-11-05"},{"label":"Arithmetic Siegel-Weil for the spherical Hecke algebra","url":"https://arxiv.org/abs/2609.13435","checked":"2026-11-05"},{"label":"Dubi Kelmer paper evidence","url":"https://www.aimsciences.org/article/doi/10.3934/jmd.2025012","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":155,"facultyNames":["Benjamin Howard","David Treumann","Dubi Kelmer","Dawei Chen"]},"boston-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and mathematical physics at Boston University. The faculty examples below describe research in those areas.","Jared Weinstein’s listed work concerns p-adic geometry, local shtukas, Langlands correspondences and modularity; connections to chromatic homotopy. Brian Williams’s listed work concerns holomorphic field theory, higher/homotopical algebra, vertex and factorization algebras and supergeometry.","Takashi Kimura’s listed work concerns orbifold and inertial K-theory, characteristic classes and power operations, Gromov-Witten theory and mirror symmetry. Siu-Cheong Lau’s listed work concerns mirror symmetry, complex algebraic and symplectic geometry, quiver varieties and Fukaya categories. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jared Weinstein official research/profile","url":"https://sites.google.com/view/jared-weinstein/research","checked":"2026-11-05"},{"label":"Brian Williams official research/profile","url":"https://brianrwilliams.github.io/","checked":"2026-11-05"},{"label":"Kimura original publisher PDF","url":"https://msp.org/akt/2017/2-1/akt-v2-n1-p04-s.pdf","checked":"2026-11-05"},{"label":"Siu-Cheong Lau official research/profile","url":"https://math.bu.edu/people/lau/Lau/My_geometry_life.html","checked":"2026-11-05"},{"label":"Jared Weinstein official appointment","url":"https://sites.google.com/view/jared-weinstein/home","checked":"2026-11-05"},{"label":"Takashi Kimura official appointment","url":"https://www.bu.edu/math/people/faculty/","checked":"2026-11-05"},{"label":"Brian Williams official appointment","url":"https://www.bu.edu/math/profile/brian-williams/","checked":"2026-11-05"},{"label":"Kimura current BU profile","url":"https://www.bu.edu/math/profile/takashi-kimura/","checked":"2026-11-05"},{"label":"Kimura author-submitted record","url":"https://arxiv.org/abs/1209.2064","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":164,"facultyNames":["Jared Weinstein","Brian Williams","Takashi Kimura","Siu-Cheong Lau"]},"brandeis-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, dynamical systems, and mathematical physics at Brandeis University. The faculty examples below describe research in those areas.","Justin Campbell’s listed work concerns geometric Langlands, geometric Eisenstein series, semi-infinite flags and parabolic induction. An Huang’s listed work concerns D-modules, periods, Hodge theory, mirror symmetry and zeta/L-functions; also p-adic mathematical physics and graph theory.","Kiyoshi Igusa’s listed work concerns quiver and cluster representations, stability conditions, exceptional sequences and connections to topology. Dmitry Kleinbock’s listed work concerns metric Diophantine approximation through homogeneous dynamics, Lie groups and lattices. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Justin Campbell official research/profile","url":"https://sites.google.com/view/justincampbell/research","checked":"2026-11-05"},{"label":"An Huang official research/profile","url":"https://scholarworks.brandeis.edu/esploro/profile/an_huang/output/publication?institution=01BRAND_INST","checked":"2026-11-05"},{"label":"Kiyoshi Igusa official research/profile","url":"https://scholarworks.brandeis.edu/esploro/outputs/journalArticle/Continuous-Stability-Conditions-of-Type-A/9924716942401921?institution=01BRAND_INST","checked":"2026-11-05"},{"label":"Dmitry Kleinbock official research/profile","url":"https://sites.google.com/brandeis.edu/dkhome","checked":"2026-11-05"},{"label":"Dmitry Kleinbock official appointment","url":"https://www.brandeis.edu/mathematics/people/index.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":175,"facultyNames":["Justin Campbell","An Huang","Kiyoshi Igusa","Dmitry Kleinbock"]},"brigham-young-university":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and applied mathematics at Brigham Young University. The faculty examples below describe research in those areas.","Jennifer Brooks’s listed work concerns several complex variables, CR geometry, Hermitian sums of squares, and harmonic mappings. Xian Jin Li’s listed work concerns zeta functions, explicit formulas and spectral/operator approaches to analytic number theory.","Nathan Priddis’s listed work concerns mirror symmetry, Landau-Ginzburg models and K3 surfaces. Pace Nielsen’s listed work concerns ring and module theory, cancellation and infinite summation; representation-adjacent algebra rather than a Lie-representation specialty. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jennifer Brooks profile","url":"https://math.byu.edu/directory/brooks-jennifer","checked":"2026-11-05"},{"label":"Xian Jin Li profile","url":"https://math.byu.edu/directory/li-xian-jin","checked":"2026-11-05"},{"label":"Nathan Priddis profile","url":"https://math.byu.edu/directory/priddis-nathan","checked":"2026-11-05"},{"label":"Pace Nielsen profile","url":"https://math.byu.edu/directory/nielsen-pace","checked":"2026-11-05"},{"label":"Priddis CV","url":"https://math.byu.edu/00000192-bb60-d2ff-a1df-bb7a3cb70001/priddiscvoct24-pdf","checked":"2026-11-05"},{"label":"Brooks 2026 paper, official publisher","url":"https://www.impan.pl/en/publishing-house/journals-and-series/annales-polonici-mathematici/all/136/3/116283/applying-the-argument-principle-to-count-zeros-of-harmonic-functions-with-poles","checked":"2026-11-05"},{"label":"Nielsen publications","url":"https://mathdept.byu.edu/~pace/research.html","checked":"2026-11-05"},{"label":"Li CV","url":"https://math.byu.edu/0000018b-b144-dec1-a9cf-b5fe68250001/licv-pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":183,"facultyNames":["Jennifer Brooks","Xian Jin Li","Nathan Priddis","Pace Nielsen"]},"brown-university":{"paragraphs":["The supplied dossier emphasizes number theory, dynamical systems, algebraic geometry, and analysis & PDE at Brown University. The faculty examples below describe research in those areas.","Joseph Silverman’s listed work concerns elliptic curves, Diophantine/arithmetic geometry and arithmetic dynamics. Melody Chan’s listed work concerns tropical geometry, moduli-space topology, toric and matroid geometry.","Georgios Daskalopoulos’s listed work concerns harmonic maps, Teichmüller holomorphic rigidity and geometric analysis. Brendan Hassett’s listed work concerns birational geometry, rationality, K3 surfaces and arithmetic geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra faculty","url":"https://mathematics.brown.edu/research/algebra","checked":"2026-11-05"},{"label":"Geometry faculty","url":"https://mathematics.brown.edu/research/geometry-and-topology","checked":"2026-11-05"},{"label":"Brendan Hassett official/primary paper","url":"https://www.math.brown.edu/bhassett/papers.html","checked":"2026-11-05"},{"label":"Melody Chan official/primary paper","url":"https://londmathsoc.onlinelibrary.wiley.com/doi/10.1112/jlms.70434","checked":"2026-11-05"},{"label":"Joseph Silverman official/primary paper","url":"https://www.degruyterbrill.com/document/doi/10.1515/crelle-2025-0055/html","checked":"2026-11-05"},{"label":"Georgios Daskalopoulos official/primary paper","url":"https://epubs.siam.org/doi/10.1137/25M1807630","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":192,"facultyNames":["Joseph Silverman","Melody Chan","Georgios Daskalopoulos","Brendan Hassett"]},"california-institute-of-technology":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, mathematical physics, and algebraic geometry at California Institute of Technology. The faculty examples below describe research in those areas.","David Conlon’s listed work concerns additive combinatorics, arithmetic progressions and combinatorial number theory; adjacent to arithmetic geometry. Sergei Gukov’s listed work concerns geometric Langlands, categorification, vertex/Kac-Moody algebra and mathematical physics.","Matilde Marcolli’s listed work concerns motives, Grothendieck rings and noncommutative/arithmetic geometry. Tony Yue Yu’s listed work concerns non-Archimedean and derived geometry, enumerative geometry and mirror symmetry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current math people","url":"https://mathematics.caltech.edu/people","checked":"2026-11-05"},{"label":"Tony Yue Yu research paper","url":"https://academic.oup.com/imrn/article-abstract/2025/20/rnaf310/8285358","checked":"2026-11-05"},{"label":"David Conlon research paper","url":"https://www.its.caltech.edu/~dconlon/","checked":"2026-11-05"},{"label":"Matilde Marcolli research paper","url":"https://feeds.library.caltech.edu/people/Marcolli-M/article.html","checked":"2026-11-05"},{"label":"Sergei Gukov research paper","url":"https://feeds.library.caltech.edu/people/Gukov-S/combined.html","checked":"2026-11-05"},{"label":"Yu official research","url":"https://www.pma.caltech.edu/people/tony-yue-yu","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":202,"facultyNames":["David Conlon","Sergei Gukov","Matilde Marcolli","Tony Yue Yu"]},"carnegie-mellon-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, analysis & PDE, and combinatorics at Carnegie Mellon University. The faculty examples below describe research in those areas.","Christopher (Chris) Eur’s listed work concerns combinatorial algebraic geometry, matroids, Chow rings, positivity and tropical geometry.","Theresa C. Anderson’s listed work concerns arithmetic statistics and harmonic analysis; Galois-group distribution and polynomial/number-field counting. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Chris Eur research","url":"https://www.math.cmu.edu/users/math/ceur/research.html","checked":"2026-11-05"},{"label":"Theresa Anderson research","url":"https://faculty.math.cmu.edu/anderson/research/","checked":"2026-11-05"},{"label":"Chris Eur current appointment","url":"https://www.cmu.edu/math/people/faculty/eur.html","checked":"2026-11-05"},{"label":"Theresa Anderson current appointment","url":"https://www.cmu.edu/math/people/faculty/anderson.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":211,"facultyNames":["Christopher (Chris) Eur","Theresa C. Anderson"]},"case-western-reserve-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, topology, algebraic geometry, and logic at Case Western Reserve University. The faculty examples below describe research in those areas.","Eva Belmont’s listed work concerns adjacent fit: motivic/equivariant stable homotopy and homological algebra, not classical algebraic geometry. Gabriel Angelini-Knoll’s listed work concerns adjacent fit: motivic homotopy, algebraic K-theory and syntomic cohomology with arithmetic applications.","Nick Gurski’s listed work concerns adjacent categorical algebra: higher categories, monoidal structures, stable homotopy and TQFT. Recent papers beyond the official 2017 list not established. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Belmont institutional profile","url":"https://mathstats.case.edu/faculty/eva-belmont/","checked":"2026-11-05"},{"label":"Angelini-Knoll institutional profile","url":"https://artscidirectory.case.edu/faculty/gabriel-angelini-knoll/","checked":"2026-11-05"},{"label":"Gurski institutional profile","url":"https://mathstats.case.edu/faculty/nick-gurski/","checked":"2026-11-05"},{"label":"Angelini-Knoll official-linked research page","url":"https://www.gangeliniknoll.com/research/","checked":"2026-11-05"},{"label":"Belmont institutional personal site","url":"https://sites.google.com/case.edu/ebelmont","checked":"2026-11-05"},{"label":"Gurski publication list","url":"https://casfaculty.case.edu/nick-gurski/publications/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":216,"facultyNames":["Eva Belmont","Gabriel Angelini-Knoll","Nick Gurski"]},"clemson-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, combinatorics, number theory, and algebraic geometry at Clemson University. The faculty examples below describe research in those areas.","Michael Burr’s listed work concerns computational algebraic geometry, certified numerical/subdivision algorithms and geometric approximation of algebraic varieties. Neil J. Calkin’s listed work concerns combinatorial and probabilistic number theory; recent algebraic computation investigates eigenvalue spreads through polynomial resultants.","Shuhong Gao (directory: Xuhong Gao)’s listed work concerns computational algebra and number theory, finite fields, polynomial systems and cryptography. More applied than the central arithmetic-geometry interests. Jim Coykendall’s listed work concerns commutative algebra and algebraic number theory; factorization in integral domains and monoids. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra/number theory research","url":"https://www.clemson.edu/science/academics/departments/mathstat/research/algebra.html","checked":"2026-11-05"},{"label":"Faculty affiliation and research","url":"https://www.math.clemson.edu/~calkin/","checked":"2026-11-05"},{"label":"Faculty affiliation and research","url":"https://www.clemson.edu/science/academics/departments/mathstat/about/profiles/sgao","checked":"2026-11-05"},{"label":"Coykendall current doctoral supervision","url":"https://www.clemson.edu/graduate/academics/graduation-program/may-2026-commencement-program.pdf","checked":"2026-11-05"},{"label":"On the axioms for a unique factorisation domain","url":"https://www.cambridge.org/core/search?eventCode=SE-AU&filters%5BauthorTerms%5D=JIM+COYKENDALL","checked":"2026-11-05"},{"label":"Certified simultaneous isotopic approximation of algebraic curves via subdivision","url":"https://www.sciencedirect.com/science/article/abs/pii/S0747717125000173","checked":"2026-11-05"},{"label":"Neil J. Calkin paper evidence","url":"https://arxiv.org/abs/2510.15919","checked":"2026-11-05"},{"label":"Shuhong Gao (directory: Xuhong Gao) paper evidence","url":"https://arxiv.org/abs/2512.08172","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":222,"facultyNames":["Michael Burr","Neil J. Calkin","Shuhong Gao (directory: Xuhong Gao)","Jim Coykendall"]},"colorado-state-university":{"paragraphs":["Colorado State has a useful mix of arithmetic geometry, combinatorics, and computational algebra. Achter and Pries are listed in arithmetic geometry; Juul studies arithmetic dynamics and Galois actions under iteration. Gillespie works where combinatorics meets algebraic geometry and representation theory. This gives you several fairly specific starting points beyond the broad “algebra and number theory” heading.","Computation is part of the mathematical research here, not simply a service for applications. Hulpke works on computational group theory and is a co-author of GAP; Wilson lists groups, algebras, and computation. Patel’s work joins topology with applied and computational questions. If you like explicit examples, algorithms, or software alongside structural mathematics, these are groups to examine.","The department also lists work in imaging, data science, biological processes, geosciences, and mathematics education. Those subjects sit alongside its foundational research. The useful comparison is the particular combination of theory and applications that you want, rather than treating CSU as exclusively pure or applied."],"sources":[{"label":"Colorado State — algebra, combinatorics, and number theory","url":"https://mathematics.colostate.edu/research/research-area-algebra-combinatorics-number-theory/"},{"label":"Colorado State — research overview","url":"https://mathematics.colostate.edu/research/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":230,"facultyNames":["Jamie Juul","Mark Shoemaker","Maria Monks Gillespie","Jeffrey Achter"]},"columbia-university":{"paragraphs":["Columbia's number theory description emphasizes the meeting of analytic, geometric and p-adic methods. Galois representations, automorphic forms, L-functions and arithmetic geometry are central examples, rather than a single narrowly defined kind of number theory.","The graduate core gives a practical picture of the algebraic preparation: commutative algebra leads into a choice of algebraic geometry or algebraic number theory. The listed topics range from schemes and sheaf cohomology to local and global fields, ramification and class field theory.","For an applicant leaning toward arithmetic, that combination of research and foundational coursework is worth examining. The department also lists separate research groups in geometry and analysis, mathematical physics, probability and topology, so the arithmetic description should not be mistaken for the whole department."],"sources":[{"label":"Number theory research and neighboring groups","url":"https://www.math.columbia.edu/research/number-theory/"},{"label":"Graduate algebraic geometry and number theory core","url":"https://www.math.columbia.edu/courses-math/graduate-core-courses/algebraic-geometry-and-number-theory/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":238,"facultyNames":["Michael Thaddeus","Chao Li","Duong H. Phong","Lue Pan"]},"cornell-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and number theory at Cornell University. The faculty examples below describe research in those areas.","Inna Zakharevich’s listed work concerns algebraic K-theory, scissors congruence and Grothendieck rings of varieties; topology interface. Daniel Halpern-Leistner’s listed work concerns derived algebraic geometry, moduli stacks, categorical/Theta stratifications and enumerative geometry.","Yusheng Luo’s listed work concerns complex dynamics, rational-map moduli, Teichmüller and Berkovich dynamics. Allen Knutson’s listed work concerns Schubert calculus, equivariant K-theory, quiver varieties and quantum integrability. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty","url":"https://math.cornell.edu/faculty","checked":"2026-11-05"},{"label":"Daniel Halpern-Leistner primary paper evidence","url":"https://danielhl.github.io/","checked":"2026-11-05"},{"label":"Allen Knutson primary paper evidence","url":"https://arxiv.org/abs/2306.13855","checked":"2026-11-05"},{"label":"Yusheng Luo primary paper evidence","url":"https://arxiv.org/abs/2610.21945","checked":"2026-11-05"},{"label":"Inna Zakharevich primary paper evidence","url":"https://experts.umn.edu/en/publications/a-combinatorial-construction-of-homology-via-acgw-categories/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":249,"facultyNames":["Inna Zakharevich","Daniel Halpern-Leistner","Yusheng Luo","Allen Knutson"]},"cuny-graduate-center":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory and geometry at CUNY Graduate Center. The faculty examples below describe research in those areas.","Andrew Obus’s listed work concerns arithmetic/non-Archimedean geometry, ramification and Galois covers, and regular models of curves.","Karol Kozioł’s listed work concerns mod-p representations of p-adic groups, derived Satake theory, and Hecke/Ext algebras. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Andrew Obus official research/profile","url":"https://baruch.cuny.edu/profiles/faculty/Andrew-Scott-Obus","checked":"2026-11-05"},{"label":"Karol Kozioł official research/profile","url":"https://baruch.cuny.edu/profiles/faculty/Karol-Koziol","checked":"2026-11-05"},{"label":"Andrew Obus official appointment","url":"https://www.gc.cuny.edu/people/andrew-obus","checked":"2026-11-05"},{"label":"Karol Kozioł official appointment","url":"https://www.gc.cuny.edu/mathematics/faculty","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":261,"facultyNames":["Andrew Obus","Karol Kozioł"]},"dartmouth-college":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and combinatorics at Dartmouth College. The faculty examples below describe research in those areas.","Juliette Bruce’s listed work concerns algebraic geometry and commutative algebra via syzygies, positivity, tropical geometry, and arithmetic varieties. Rosa C. Orellana’s listed work concerns combinatorial representation theory, symmetric-group characters, symmetric functions, plethysm and diagram/partition algebras.","Asher Auel’s listed work concerns Brauer groups and rationality, arithmetic of K3 surfaces/cubic fourfolds, and Brill-Noether geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Juliette Bruce official research/profile","url":"https://www.juliettebruce.xyz/","checked":"2026-11-05"},{"label":"Rosa C. Orellana official research/profile","url":"https://math.dartmouth.edu/~orellana/research.html","checked":"2026-11-05"},{"label":"Asher Auel official research/profile","url":"https://math.dartmouth.edu/~auel/papers/","checked":"2026-11-05"},{"label":"Asher Auel official appointment","url":"https://math.dartmouth.edu/~auel/cv/","checked":"2026-11-05"},{"label":"Juliette Bruce official appointment","url":"https://faculty-directory.dartmouth.edu/juliette-bruce","checked":"2026-11-05"},{"label":"Rosa C. Orellana official appointment","url":"https://faculty-directory.dartmouth.edu/rosa-c-orellana","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":267,"facultyNames":["Juliette Bruce","Rosa C. Orellana","Asher Auel"]},"drexel-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, combinatorics, algebraic geometry, and analysis & PDE at Drexel University. The faculty examples below describe research in those areas.","Darij Grinberg’s listed work concerns algebraic combinatorics and algebra; recent work includes matrix identities and constructive algebra. James Eldred Pascoe’s listed work concerns complex analysis and noncommutative algebra; recent work on stable polynomials, rational functions and boundary singularities in complex balls.","Jonah Blasiak’s listed work concerns algebraic combinatorics: symmetric functions, LLT polynomials, elliptic Hall algebra and Demazure crystals. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics research","url":"https://drexel.edu/coas/academics/departments-centers/mathematics/research/","checked":"2026-11-05"},{"label":"James Pascoe institutional profile","url":"https://researchdiscovery.drexel.edu/esploro/profile/james_pascoe","checked":"2026-11-05"},{"label":"Jonah Blasiak publications","url":"https://www.math.drexel.edu/~jblasiak/","checked":"2026-11-05"},{"label":"Darij Grinberg institutional research record","url":"https://researchdiscovery.drexel.edu/esploro/profile/darij_grinberg/output/postedContent?institution=01DRXU_INST","checked":"2026-11-05"},{"label":"Pascoe CV","url":"https://drexel.edu/~/media/Files/coas2/math/cv/drexel-pascoe-james-cv.ashx?la=en","checked":"2026-11-05"},{"label":"Stable polynomials and bounded rational functions in the unit ball","url":"https://researchdiscovery.drexel.edu/esploro/outputs/preprint/Stable-polynomials-and-bounded-rational-functions/991022163437304721","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":273,"facultyNames":["Darij Grinberg","James Eldred Pascoe","Jonah Blasiak"]},"duke-university":{"paragraphs":["Duke's number theory group covers analytic methods, the Langlands program, arithmetic geometry, algebraic cycles and locally symmetric spaces. The published roster gives several possible directions within that umbrella, including the work of Samit Dasgupta, Jayce Getz, Lillian Pierce, Joseph Rabinoff and Kirsten Wickelgren.","The wider department also includes differential and algebraic geometry, topology, analysis, probability, PDE and dynamics, alongside computational mathematics and biological or physical modeling. Its doctoral program describes collaborations with the medical school and other Duke departments.","The useful comparison is therefore between particular research groups and their neighboring fields. If your interests combine arithmetic with geometry, or analysis with modeling, there are several routes to investigate without assuming that the same adviser or curriculum serves all of them."],"sources":[{"label":"Number theory specialties and faculty","url":"https://math.duke.edu/research/number-theory"},{"label":"Research areas","url":"https://math.duke.edu/research-areas"},{"label":"Doctoral research environment","url":"https://math.duke.edu/graduate/prospective-students"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":279,"facultyNames":["M. Ronen Plesser","Ezra Miller","Kirsten Wickelgren","Mark Stern"]},"emory-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, combinatorics, algebraic geometry, and analysis & PDE at Emory University. The faculty examples below describe research in those areas.","Robert Silversmith’s listed work concerns moduli spaces, tropical intersection theory, combinatorial algebraic geometry and Gromov-Witten themes. Shanshuang Yang’s listed work concerns complex analysis and conformal/quasiconformal geometry; closer to geometric function theory than complex algebraic geometry.","Rohini Ramadas’s listed work concerns combinatorial/tropical geometry of moduli spaces and complex dynamics of rational maps. Suresh Venapally’s listed work concerns quadratic forms, Galois cohomology, algebraic groups and local-global principles over arithmetic function fields. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty","url":"https://mathematics.emory.edu/people/faculty-math.html","checked":"2026-11-05"},{"label":"Algebra group","url":"https://mathematics.emory.edu/research/algebra.html","checked":"2026-11-05"},{"label":"Rohini Ramadas papers","url":"https://sites.google.com/view/rohini-ramadas/home","checked":"2026-11-05"},{"label":"Rob Silversmith homepage","url":"https://sites.google.com/view/rob-silversmith/home","checked":"2026-11-05"},{"label":"Ramadas/Silversmith 2026 paper","url":"https://arxiv.org/abs/2604.15511","checked":"2026-11-05"},{"label":"Suresh research","url":"https://www.math.emory.edu/~suresh/suresh.html","checked":"2026-11-05"},{"label":"Parimala research","url":"https://www.math.emory.edu/~parimala/preprints.html","checked":"2026-11-05"},{"label":"Parimala-Suresh recent paper","url":"https://arxiv.org/abs/2410.15598","checked":"2026-11-05"},{"label":"Yang 2026 paper","url":"https://arxiv.org/abs/2509.01528","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":291,"facultyNames":["Robert Silversmith","Shanshuang Yang","Rohini Ramadas","Suresh Venapally"]},"florida-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and topology at Florida State University. The faculty examples below describe research in those areas.","Oishee Banerjee’s listed work concerns topology/cohomology of algebraic moduli spaces, stability, and arithmetic consequences. Amod Agashe’s listed work concerns modular forms and Hecke algebras, elliptic curves and modular abelian varieties, rational torsion and the Birch-Swinnerton-Dyer conjecture.","Paolo Aluffi’s listed work concerns intersection theory, characteristic classes of singular varieties, and stringy/Mather classes. Jeremy Usatine’s listed work concerns motivic integration, Artin stacks, crepant resolutions, and stringy invariants. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Oishee Banerjee official research/profile","url":"https://www.math.fsu.edu/~banerjee/OisheeCV.pdf","checked":"2026-11-05"},{"label":"Agashe official research page","url":"https://www.math.fsu.edu/~agashe/math.html","checked":"2026-11-05"},{"label":"Paolo Aluffi official research/profile","url":"https://www.math.fsu.edu/~aluffi/","checked":"2026-11-05"},{"label":"Jeremy Usatine official research/profile","url":"https://www.math.fsu.edu/~usatine/papers.html","checked":"2026-11-05"},{"label":"Jeremy Usatine official appointment","url":"https://www.math.fsu.edu/~usatine/","checked":"2026-11-05"},{"label":"Amod Agashe official appointment","url":"https://mathematics.fsu.edu/people?field_graduate_program_area_target_id=All&field_position_type_value=All&field_research_area_tags_target_id=4&keys=","checked":"2026-11-05"},{"label":"Agashe 2026 modular-abelian-variety paper","url":"https://mathjournals.org/jrms/2026-041-003/2026-041-003-005.html","checked":"2026-11-05"},{"label":"Agashe 2026 Hecke-algebra paper","url":"https://mathjournals.org/jrms/2026-041-003/2026-041-003-008.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":300,"facultyNames":["Oishee Banerjee","Amod Agashe","Paolo Aluffi","Jeremy Usatine"]},"george-mason-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, dynamical systems, and mathematical physics at George Mason University. The faculty examples below describe research in those areas.","David Carchedi’s listed work concerns higher stacks, derived differential geometry and étale homotopy; links to algebraic geometry and mathematical physics. Yiannis Loizides’s listed work concerns geometric quantization, loop groups, moduli spaces and index theory; a geometric representation-theory connection rather than arithmetic number theory.","Sean Lawton’s listed work concerns character varieties, moduli of group representations, mixed Hodge structures and dynamics. Neil Epstein’s listed work concerns commutative algebra: closure operations, characteristic-p techniques, singularities and reciprocal complements. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"David Carchedi current institutional profile","url":"https://science.gmu.edu/directory/david-carchedi","checked":"2026-11-05"},{"label":"Yiannis Loizides faculty homepage","url":"https://math.gmu.edu/~yloizide/","checked":"2026-11-05"},{"label":"Sean Lawton profile","url":"https://science.gmu.edu/directory/sean-lawton","checked":"2026-11-05"},{"label":"Neil Epstein current profile","url":"https://science.gmu.edu/directory/neil-epstein","checked":"2026-11-05"},{"label":"Epstein research and paper list","url":"https://math.gmu.edu/~nepstei2/research.html","checked":"2026-11-05"},{"label":"Lawton CV May 2026","url":"https://science.gmu.edu/media/cv-lawton-may2026pdf","checked":"2026-11-05"},{"label":"David Carchedi faculty homepage linked by Mason","url":"https://davidcarchedi.com/","checked":"2026-11-05"},{"label":"Yiannis Loizides current institutional profile","url":"https://science.gmu.edu/directory/yiannis-loizides","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":306,"facultyNames":["David Carchedi","Yiannis Loizides","Sean Lawton","Neil Epstein"]},"george-washington-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and logic at George Washington University. The faculty examples below describe research in those areas.","Robert Won’s listed work concerns noncommutative algebra, quantum symmetries, weak Hopf algebras and homological methods.","Joel B. Lewis’s listed work concerns algebraic combinatorics of reflection groups and factorizations, with representation-adjacent enumerative questions. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Core mathematics faculty","url":"https://math.columbian.gwu.edu/core-faculty","checked":"2026-11-05"},{"label":"Robert Won current profile","url":"https://math.columbian.gwu.edu/robert-won","checked":"2026-11-05"},{"label":"Won official research list","url":"https://blogs.gwu.edu/robertwon/research/","checked":"2026-11-05"},{"label":"Won official homepage","url":"https://blogs.gwu.edu/robertwon/","checked":"2026-11-05"},{"label":"Joel Lewis current profile","url":"https://math.columbian.gwu.edu/joel-lewis","checked":"2026-11-05"},{"label":"Lewis official research list","url":"https://blogs.gwu.edu/jblewis/research/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":314,"facultyNames":["Robert Won","Joel B. Lewis"]},"georgia-institute-of-technology":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and combinatorics at Georgia Institute of Technology. The faculty examples below describe research in those areas.","Matt Baker’s listed work concerns number theory, algebraic geometry, complex dynamics and combinatorics; particularly Berkovich spaces, tropical geometry and matroids. Current papers connect modular curves and matroid realization spaces. Anton Zeitlin’s listed work concerns quantum groups, q-Langlands, integrable systems and enumerative geometry.","Josephine Yu’s listed work concerns tropical and real algebraic geometry, polyhedral and algebraic combinatorics; tropicalizations of determinantal loci and principal minors, positivity and Ehrhart theory. Alexander Dunn’s listed work concerns analytic number theory, automorphic forms and L-functions. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Faculty research interests","url":"https://math.gatech.edu/faculty-research-interests","checked":"2026-11-05"},{"label":"Author website","url":"https://sites.google.com/view/mattbakermath/home","checked":"2026-11-05"},{"label":"Anton Zeitlin research and papers","url":"https://zeitlin.math.gatech.edu/","checked":"2026-11-05"},{"label":"Alexander Dunn and Harold Blum research award","url":"https://math.gatech.edu/hg/item/690383","checked":"2026-11-05"},{"label":"Georgia Tech faculty profile","url":"https://math.gatech.edu/people/josephine-yu","checked":"2026-11-05"},{"label":"Georgia Tech faculty profile","url":"https://math.gatech.edu/people/matt-baker","checked":"2026-11-05"},{"label":"Author publication list","url":"https://sites.google.com/view/mattbakermath/publications","checked":"2026-11-05"},{"label":"Elliptic matroids preprint","url":"https://arxiv.org/abs/2608.05299","checked":"2026-11-05"},{"label":"Tutte preprint","url":"https://arxiv.org/abs/2601.02582","checked":"2026-11-05"},{"label":"Georgia Tech author research bibliography","url":"https://sites.gatech.edu/josephineyu/sample-page/","checked":"2026-11-05"},{"label":"Tropicalizing principal minors","url":"https://arxiv.org/abs/2410.11220","checked":"2026-11-05"},{"label":"Links-Gould preprint","url":"https://arxiv.org/abs/2605.30754","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":322,"facultyNames":["Matt Baker","Anton Zeitlin","Josephine Yu","Alexander Dunn"]},"harvard-university":{"paragraphs":["Harvard's faculty interests show a dense set of connections among number theory, arithmetic and algebraic geometry, topology and geometry. Other distinct directions include dynamics, probability, combinatorics and logic; the department cannot be reduced to just its arithmetic reputation.","Some useful examples of those intersections are Noam Elkies's number theory and computation, Laura DeMarco's arithmetic dynamics, and the interaction of geometry and topology with physics in Dan Freed's work. The faculty page also lists graduate advisees, which helps identify actual research activity rather than relying only on famous names.","The Center of Mathematical Sciences and Applications is another source of seminars and mathematical contacts. Compare the research group and its current students with your interests; a broad faculty directory is not a promise that every listed person is taking a new student."],"sources":[{"label":"Senior faculty interests, advisees and CMSA resources","url":"https://www.math.harvard.edu/graduate/senior-faculty-research-interests/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":329,"facultyNames":["Noam Elkies","Tomer Schlank","Laura DeMarco","Curtis McMullen"]},"indiana-university-bloomington":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, number theory, and topology at Indiana University Bloomington. The faculty examples below describe research in those areas.","Michael Larsen’s listed work concerns algebraic number theory, algebraic groups and geometry, finite-group character bounds and Weil representations; also additive number theory. Noah Snyder’s listed work concerns tensor and fusion categories, subfactors, topological quantum field theory, conformal embeddings and diagrammatic representation theory.","Matvei Libine’s listed work concerns quaternionic analysis, conformal/symplectic representation theory and invariant forms. Ajay Ramadoss’s listed work concerns noncommutative geometry, representation homology and connections to Lie-group topology and algebraic geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty directory","url":"https://math.indiana.edu/about/faculty/index.html?research_areas=Algebra","checked":"2026-11-05"},{"label":"Ramadoss author-submitted paper","url":"https://arxiv.org/abs/2602.18682","checked":"2026-11-05"},{"label":"Libine author-submitted paper","url":"https://arxiv.org/abs/2605.29094","checked":"2026-11-05"},{"label":"Snyder university homepage","url":"https://nsnyder1.pages.iu.edu/","checked":"2026-11-05"},{"label":"Larsen current Indiana profile","url":"https://math.indiana.edu/about/faculty/larsen-michael.html","checked":"2026-11-05"},{"label":"Larsen 2026 primary preprint","url":"https://arxiv.org/abs/2601.18507","checked":"2026-11-05"},{"label":"Larsen representation-theory preprint","url":"https://arxiv.org/abs/2407.12713","checked":"2026-11-05"},{"label":"Snyder current Indiana profile","url":"https://math.indiana.edu/about/faculty/snyder-noah.html","checked":"2026-11-05"},{"label":"Snyder 2026 revised primary preprint","url":"https://arxiv.org/abs/2503.13641","checked":"2026-11-05"},{"label":"Snyder Simons leave notice","url":"https://math.indiana.edu/news-events/news/snyder-noah-simons.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":339,"facultyNames":["Michael Larsen","Noah Snyder","Matvei Libine","Ajay Ramadoss"]},"iowa-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and mathematical physics at Iowa State University. The faculty examples below describe research in those areas.","Jason McCullough’s listed work concerns commutative/computational algebra, graded resolutions, Koszul algebras, and algebraic geometry.","Shlomo Gelaki’s listed work concerns Hopf algebras, quantum groups, tensor categories, and representations of twisted algebraic groups. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jason McCullough official research/profile","url":"https://faculty.sites.iastate.edu/jmccullo/research","checked":"2026-11-05"},{"label":"Shlomo Gelaki official research/profile","url":"https://eprints.gla.ac.uk/353770/","checked":"2026-11-05"},{"label":"Jason McCullough official appointment","url":"https://faculty.sites.iastate.edu/jmccullo/","checked":"2026-11-05"},{"label":"Shlomo Gelaki official appointment","url":"https://math.iastate.edu/profiles/shlomo-gelaki/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":348,"facultyNames":["Jason McCullough","Shlomo Gelaki"]},"johns-hopkins-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and topology at Johns Hopkins University. The faculty examples below describe research in those areas.","Zhiren Wang’s listed work concerns homogeneous dynamics, quantitative equidistribution and Diophantine/number-theoretic applications; less directly arithmetic geometry. Kayla Wright’s listed work concerns cluster algebras, Grassmannian webs/dimers and categorical models from nonorientable surfaces.","Emily Riehl’s listed work concerns higher category theory, homotopy type theory and formalization rather than a direct traditional representation-theory specialization. Mikhail Khovanov’s listed work concerns categorification, quantum groups, diagrammatic algebras, Soergel bimodules and link homology. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Zhiren Wang current homepage and papers","url":"https://sites.google.com/view/zhiren-wang/","checked":"2026-11-05"},{"label":"Wright 2026 paper metadata","url":"https://arxiv.org/abs/2507.15211","checked":"2026-11-05"},{"label":"Riehl papers","url":"https://emilyriehl.github.io/papers/","checked":"2026-11-05"},{"label":"Khovanov publications","url":"https://sites.google.com/view/mkhovanov/research","checked":"2026-11-05"},{"label":"Khovanov current homepage","url":"https://sites.google.com/view/mkhovanov/","checked":"2026-11-05"},{"label":"Riehl current homepage","url":"https://emilyriehl.github.io/","checked":"2026-11-05"},{"label":"Haihan Wu current Virginia appointment","url":"https://sites.google.com/ucdavis.edu/haihanwu","checked":"2026-11-05"},{"label":"Kayla Wright current appointment","url":"https://sites.google.com/view/kayla-wright","checked":"2026-11-05"},{"label":"Wright papers","url":"https://sites.google.com/view/kayla-wright/research/current-work","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":353,"facultyNames":["Zhiren Wang","Kayla Wright","Emily Riehl","Mikhail Khovanov"]},"kansas-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, geometry, and number theory at Kansas State University. The faculty examples below describe research in those areas.","Gabriel Kerr’s listed work concerns tropical and symplectic geometry, homological mirror symmetry. Zongzhu Lin’s listed work concerns algebraic groups, quantum groups and differential graded/vertex algebras.","Mikhail Mazin’s listed work concerns geometric representation theory and algebraic combinatorics, flag-variety K-theory. Gerald Höhn’s listed work concerns vertex operator algebras, modular forms, lattices and finite groups. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra group","url":"https://www.math.ksu.edu/research/groups/algebra/members.html","checked":"2026-11-05"},{"label":"Algebra publications","url":"https://www.math.ksu.edu/research/groups/algebra/publications.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":369,"facultyNames":["Gabriel Kerr","Zongzhu Lin","Mikhail Mazin","Gerald Höhn"]},"lehigh-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, geometry, mathematical physics, and analysis & PDE at Lehigh University. The faculty examples below describe research in those areas.","Andrew Harder’s listed work concerns Hodge theory, Calabi-Yau varieties, mirror symmetry, holomorphic symplectic geometry and periods. Huai-Dong Cao’s listed work concerns geometric analysis and Ricci solitons; adjacent Kähler-Ricci/Fano interests, with recent curvature-classification research.","Angela Hicks’s listed work concerns algebraic combinatorics and noncommutative symmetric functions. Joe Kramer-Miller’s listed work concerns arithmetic differential equations, algebraic power series and periods; joint recent work studies diagonal/Hadamard grades of hypergeometric functions. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty","url":"https://math.cas.lehigh.edu/faculty-staff","checked":"2026-11-05"},{"label":"Harder profile","url":"https://math.cas.lehigh.edu/faculty-staff/andrew-harder","checked":"2026-11-05"},{"label":"Harder and Kramer-Miller 2026 paper","url":"https://academic.oup.com/imrn/article/2026/8/rnag040/8658368","checked":"2026-11-05"},{"label":"Official coauthor publication list","url":"https://bimsa.net/people/YingyingZhang/","checked":"2026-11-05"},{"label":"Cao 2025 paper","url":"https://www.sciencedirect.com/science/article/abs/pii/S0021782425000303","checked":"2026-11-05"},{"label":"Hicks 2025 paper","url":"https://www.combinatorics.org/ojs/index.php/eljc/article/view/v32i1p53","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":376,"facultyNames":["Andrew Harder","Huai-Dong Cao","Angela Hicks","Joe Kramer-Miller"]},"louisiana-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and mathematical physics at Louisiana State University. The faculty examples below describe research in those areas.","Jerome W. Hoffman’s listed work concerns arithmetic algebraic geometry and modular forms; recent collaboration relates Hecke traces to hypergeometric character sums. Siu-Hung (Richard) Ng’s listed work concerns Hopf algebras, tensor and modular categories, quantum groups; recent work on orbifolds and modular extensions.","Christin Bibby’s listed work concerns arrangements of complex subvarieties, configuration spaces, matroids, and representation stability; recent work computes cohomological information for tropical-curve moduli. Gene S. Kopp’s listed work concerns explicit class field theory, Stark conjectures, analytic formulas for arithmetic objects, and connections to quantum information. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jerome W. Hoffman official research/profile","url":"https://www.math.lsu.edu/~llong/","checked":"2026-11-05"},{"label":"Siu-Hung (Richard) Ng official research/profile","url":"https://www.math.lsu.edu/~rng/Publications.html","checked":"2026-11-05"},{"label":"Christin Bibby official research/profile","url":"https://www.math.lsu.edu/~bibby/publications.html","checked":"2026-11-05"},{"label":"Gene S. Kopp official research/profile","url":"https://gskopp.com/papers/","checked":"2026-11-05"},{"label":"Christin Bibby official appointment","url":"https://www.math.lsu.edu/~bibby/","checked":"2026-11-05"},{"label":"Siu-Hung (Richard) Ng official appointment","url":"https://www.math.lsu.edu/people/professors","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":383,"facultyNames":["Jerome W. Hoffman","Siu-Hung (Richard) Ng","Christin Bibby","Gene S. Kopp"]},"massachusetts-institute-of-technology":{"paragraphs":["MIT houses substantial pure and applied mathematics communities in the same department. The pure side includes algebraic geometry, topology, analysis and PDE, geometry, logic, number theory, probability and representation theory.","The applied side is broader than numerical analysis: the department also places combinatorics, theoretical computer science, computational biology, physical applied mathematics and mathematics of data there. That administrative label should not make a combinatorialist assume the work is all modeling or computation.","For someone whose interests cross mathematical theory and algorithms or scientific questions, the useful feature is the range of groups to compare within one department. Start with their actual research descriptions and seminar activity rather than choosing between the words pure and applied alone."],"sources":[{"label":"MIT mathematics research groups","url":"https://math.mit.edu/research/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":391,"facultyNames":["Bjorn Poonen","Zhiwei Yun","Pavel Etingof","Wei Zhang"]},"michigan-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and combinatorics at Michigan State University. The faculty examples below describe research in those areas.","Laure Flapan’s listed work concerns Hodge theory, algebraic cycles, K3 and hyperkähler moduli, abelian varieties. Michael Shapiro’s listed work concerns cluster structures, Poisson-Lie geometry and noncommutative/integrable systems.","François Greer’s listed work concerns moduli of K3/elliptic varieties, special cycles, modularity and Shimura varieties. Linhui Shen’s listed work concerns cluster and quantum groups, local-system moduli, canonical bases and braid varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"AG and number theory faculty","url":"https://math.msu.edu/Research/research-groups/algebraic-geometry-number-theory.aspx","checked":"2026-11-05"},{"label":"Michael Shapiro official directory","url":"https://directory.natsci.msu.edu/Directory/Profiles/Person/101632?org=60","checked":"2026-11-05"},{"label":"Linhui Shen directory","url":"https://directory.natsci.msu.edu/directory/Profiles/Person/101575","checked":"2026-11-05"},{"label":"Laure Flapan research","url":"https://sites.google.com/view/laureflapan/research","checked":"2026-11-05"},{"label":"François Greer research","url":"https://sites.google.com/msu.edu/francoisgreer/research","checked":"2026-11-05"},{"label":"Linhui Shen research","url":"https://sites.google.com/site/linhuishenmath/customization","checked":"2026-11-05"},{"label":"Shapiro coauthored primary preprint","url":"https://arxiv.org/abs/2603.12496","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":398,"facultyNames":["Laure Flapan","Michael Shapiro","François Greer","Linhui Shen"]},"new-york-university-courant-institute":{"paragraphs":["At Courant, analysis, PDE, scientific computing and physical applications are closely connected. The research descriptions make that concrete through fluid mechanics, variational problems, numerical algorithms and mathematical modeling, rather than drawing a clean boundary between pure and applied work.","There is also substantial geometry, probability and dynamics, and an algebraic geometry group working on questions such as rational points, rationality and group actions. An applicant interested in pure mathematics should look at those groups directly instead of assuming that Courant is only an applied program.","For a student who wants theory to interact with computation or scientific problems, the range of shared questions is a useful feature. The institute's research page links subject seminars, which are a better guide to a prospective day-to-day mathematical community than the institute name alone."],"sources":[{"label":"Courant mathematics research groups and seminars","url":"https://math.cims.nyu.edu/dynamic/research/research-areas/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":410,"facultyNames":["Alena Pirutka","Yuri Tschinkel","Valentino Tosatti"]},"north-carolina-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, combinatorics, and algebraic geometry at North Carolina State University. The faculty examples below describe research in those areas.","Andrew Manion’s listed work concerns higher representations, Heegaard Floer theory, categoryO and geometric/topological categorification. Bojko Bakalov’s listed work concerns Lie/vertex-algebra and quantum methods; current papers emphasize quantum computation and spin-system symmetry.","Louis Esser’s listed work concerns birational algebraic geometry, Fano varieties, singularity invariants and group actions. Nathan Reading’s listed work concerns Coxeter/cluster structures, scattering diagrams and lattice methods with representation-theoretic connections. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Andrew Manion profile","url":"https://math.sciences.ncsu.edu/people/ajmanion/","checked":"2026-11-05"},{"label":"Bojko Bakalov profile/papers","url":"https://math.sciences.ncsu.edu/people/bnbakalo/","checked":"2026-11-05"},{"label":"Louis Esser profile","url":"https://math.sciences.ncsu.edu/people/lfesser/","checked":"2026-11-05"},{"label":"Nathan Reading profile/papers","url":"https://math.sciences.ncsu.edu/people/nreadin/","checked":"2026-11-05"},{"label":"Louis Esser institutional publication record","url":"https://collaborate.princeton.edu/en/publications/exceptional-fano-varieties-with-small-minimal-log-discrepancy/","checked":"2026-11-05"},{"label":"Andrew Manion papers","url":"https://sites.google.com/ncsu.edu/manion/research","checked":"2026-11-05"},{"label":"Esser new faculty announcement","url":"https://sciences.ncsu.edu/news/meet-our-newest-faculty-6/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":418,"facultyNames":["Andrew Manion","Bojko Bakalov","Louis Esser","Nathan Reading"]},"northeastern-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, algebraic geometry, and logic at Northeastern University. The faculty examples below describe research in those areas.","Jonathan Mboyo Esole’s listed work concerns algebraic geometry and mathematical physics, including elliptic-fibration/F-theory geometry, Lie-group embeddings, Dynkin indices and representation-theoretic structures. Iva Halacheva’s listed work concerns geometric/combinatorial representation theory, crystals, quantum groups and categorical braid actions.","Milen Yakimov’s listed work concerns quantum/cluster algebras, noncommutative algebra and Poisson geometry. Jonathan Weitsman’s listed work concerns symplectic/geometric quantization and Calabi-Yau geometry; adjacent to core complex-AG interests. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jonathan Mboyo Esole faculty profile","url":"https://cos.northeastern.edu/people/jonathan-esole/","checked":"2026-11-05"},{"label":"Mathematics RTG faculty","url":"https://sites.google.com/view/rtg-northeastern/people/faculty","checked":"2026-11-05"},{"label":"Mathematics RTG recent publications","url":"https://sites.google.com/view/rtg-northeastern/publications","checked":"2026-11-05"},{"label":"Iva Halacheva faculty homepage","url":"https://sites.google.com/site/ivahalacheva3/","checked":"2026-11-05"},{"label":"Yakimov paper","url":"https://arxiv.org/abs/2603.14376","checked":"2026-11-05"},{"label":"Weitsman paper","url":"https://arxiv.org/abs/2601.02176","checked":"2026-11-05"},{"label":"The topological life of Dynkin indices: universal scaling and matter selection","url":"https://arxiv.org/abs/2512.23041","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":430,"facultyNames":["Jonathan Mboyo Esole","Iva Halacheva","Milen Yakimov","Jonathan Weitsman"]},"northwestern-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, topology, and algebraic geometry at Northwestern University. The faculty examples below describe research in those areas.","Ezra Getzler’s listed work concerns adjacent homological-algebra fit: Koszul duality, dg Lie and L-infinity algebras, quantization and geometry/topology in field theory. Benjamin Antieau’s listed work concerns Brauer groups, derived algebraic geometry, algebraic K-theory and arithmetic splitting problems.","Allen Yuan’s listed work concerns adjacent arithmetic/homotopy fit: algebraic K-theory, higher Frobenius, chromatic and cyclotomic structures. Ben Weinkove’s listed work concerns nonlinear PDE in Kähler/Hermitian geometry, Kähler-Ricci and Chern-Ricci flow, complex Monge-Ampère equations. Recent work also pursues mathematical AI; the newest verified paper is adjacent rather than complex geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current tenure-line faculty","url":"https://www.math.northwestern.edu/people/faculty/tenure-line-faculty.html","checked":"2026-11-05"},{"label":"Antieau research papers","url":"https://antieau.github.io/research/","checked":"2026-11-05"},{"label":"Antieau current leave","url":"https://antieau.github.io/","checked":"2026-11-05"},{"label":"Weinkove research fields","url":"https://sites.google.com/view/benweinkove/research","checked":"2026-11-05"},{"label":"Weinkove current primary manuscript","url":"https://arxiv.org/abs/2610.20229","checked":"2026-11-05"},{"label":"Getzler official recent publication","url":"https://ems.press/journals/lem/articles/14299153","checked":"2026-11-05"},{"label":"Allen Yuan official-linked homepage","url":"https://allenyuan.me/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":437,"facultyNames":["Ezra Getzler","Benjamin Antieau","Allen Yuan","Ben Weinkove"]},"ohio-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and mathematical physics at Ohio State University. The faculty examples below describe research in those areas.","Maria Angelica Cueto’s listed work concerns combinatorial algebraic geometry, tropical and nonarchimedean geometry; tropical lifts of tritangents, real algebraic curves, surface singularities and moduli. Jennifer Park’s listed work concerns arithmetic geometry, points/counting and algebraic curves.","Sachin Gautam’s listed work concerns representation theory and quantum groups; Yangians, quantum loop algebras, braid groups, flat connections, difference equations and integrable systems; links to equivariant K-theory of quiver varieties. David Anderson’s listed work concerns algebraic geometry and algebraic combinatorics; Schubert calculus, flag varieties, degeneracy loci, equivariant cohomology and K-theory. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"OSU RTG research profile","url":"https://people.math.osu.edu/cueto.5/RTG/RTG-OSU23-28people.html","checked":"2026-11-05"},{"label":"Jennifer Park research profile","url":"https://math.osu.edu/people/park.2720","checked":"2026-11-05"},{"label":"OSU author homepage","url":"https://people.math.osu.edu/gautam.42/","checked":"2026-11-05"},{"label":"Jennifer Park paper, institutional repository","url":"https://research-portal.uu.nl/en/publications/on-rational-points-onclassifying-stacks-andmalles-conjecture/","checked":"2026-11-05"},{"label":"OSU profile","url":"https://math.osu.edu/people/anderson.2804","checked":"2026-11-05"},{"label":"OSU author papers","url":"https://people.math.osu.edu/anderson.2804/papers.html","checked":"2026-11-05"},{"label":"Čech paper","url":"https://arxiv.org/abs/2506.16487","checked":"2026-11-05"},{"label":"Infinite flags publisher","url":"https://www.cambridge.org/core/journals/forum-of-mathematics-sigma/article/infinite-flags-and-schubert-polynomials/B804ACFBD1F101AA849E726C90D99EB3","checked":"2026-11-05"},{"label":"Official November 2026 publication list","url":"https://people.math.osu.edu/gautam.42/publications.pdf","checked":"2026-11-05"},{"label":"Yangians paper","url":"https://arxiv.org/abs/2506.21904","checked":"2026-11-05"},{"label":"Quantum Weyl paper","url":"https://arxiv.org/abs/2501.02365","checked":"2026-11-05"},{"label":"OSU author research","url":"https://people.math.osu.edu/cueto.5/research.html","checked":"2026-11-05"},{"label":"OSU September 2026 AG seminar","url":"https://math.osu.edu/events/algebraic-geometry-seminar-maria-angelica-cueto-0","checked":"2026-11-05"},{"label":"Lifting partition preprint","url":"https://arxiv.org/abs/2605.19905","checked":"2026-11-05"},{"label":"Real sextics preprint","url":"https://arxiv.org/abs/2512.24277","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":451,"facultyNames":["Maria Angelica Cueto","Jennifer Park","Sachin Gautam","David Anderson"]},"oklahoma-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at Oklahoma State University. The faculty examples below describe research in those areas.","Paul Fili’s listed work concerns small heights, adelic potential theory, unlikely intersections and equidistribution. Edward Richmond’s listed work concerns flag/Schubert varieties, Coxeter groups and algebraic combinatorics.","Lisa Mantini’s listed work concerns Lie-group representations, integral transforms and cohomological constructions; current departmental interests also include finite symmetry and mathematics education. Dami Lee’s listed work concerns Riemann and translation surfaces, explicit geometric models, monodromy and minimal surfaces; a geometric rather than arithmetic emphasis. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Faculty directory","url":"https://cas.okstate.edu/mathematics/faculty_research_interests","checked":"2026-11-05"},{"label":"Current faculty affiliation and research","url":"https://cas.okstate.edu/mathematics/faculty","checked":"2026-11-05"},{"label":"Edward Richmond papers","url":"https://math.okstate.edu/people/erichmond/research.html","checked":"2026-11-05"},{"label":"Paul Fili currenthomepage","url":"https://math.okstate.edu/people/fili/","checked":"2026-11-05"},{"label":"Dami Lee research / publication evidence","url":"https://damileemath.wordpress.com/research/","checked":"2026-11-05"},{"label":"Lisa Mantini research / publication evidence","url":"https://math.okstate.edu/people/mantini/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":459,"facultyNames":["Paul Fili","Edward Richmond","Lisa Mantini","Dami Lee"]},"oregon-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, dynamical systems, and geometry at Oregon State University. The faculty examples below describe research in those areas.","Holly Swisher’s listed work concerns modular/mock modular forms, partitions, hypergeometric series, and supercongruences. Clayton Petsche’s listed work concerns arithmetic dynamics, arboreal Galois representations, heights, and non-Archimedean dynamics.","Jonathan Kujawa’s listed work concerns Lie superalgebras, categorical representation theory, Schur-Weyl duality, and web categories. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Holly Swisher official research/profile","url":"https://sites.google.com/view/hollyswisher/research","checked":"2026-11-05"},{"label":"Clayton Petsche official research/profile","url":"https://math.oregonstate.edu/directory/clayton-petsche","checked":"2026-11-05"},{"label":"Jonathan Kujawa official research/profile","url":"https://jonkujawa.github.io/","checked":"2026-11-05"},{"label":"Holly Swisher official appointment","url":"https://math.oregonstate.edu/directory/holly-m-swisher","checked":"2026-11-05"},{"label":"Jonathan Kujawa official appointment","url":"https://math.oregonstate.edu/directory/jonathan-kujawa","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":471,"facultyNames":["Holly Swisher","Clayton Petsche","Jonathan Kujawa"]},"pennsylvania-state-university-university-park":{"paragraphs":["Penn State's faculty research list shows a substantial cluster in dynamical systems and ergodic theory. The topics connect dynamics to geometry, number theory, statistical physics and symbolic systems, so this is a useful department to examine if dynamics is a central interest.","Other visible intersections include algebra and higher structures, algebraic geometry, K-theory and representation theory. Applied work includes materials, homogenization and models of physical systems. These are specific mathematical communities rather than a single department-wide style.","The faculty-area page is a starting map, and includes people at different career stages. Follow the individual profiles to distinguish active advisers, emeriti and current projects before relying on any particular name."],"sources":[{"label":"Penn State faculty research areas","url":"https://science.psu.edu/math/research/research-areas"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":476,"facultyNames":["Kirsten Eisenträger","John Lesieutre","Jack Huizenga","Mihran Papikian"]},"princeton-university":{"paragraphs":["Princeton explicitly puts independent research early in its graduate program. Its general examination combines broad foundations with two advanced topics, so the practical question is whether you want to start choosing a research direction relatively quickly.","Fine Hall also sits in a wider mathematical community with the nearby Institute for Advanced Study. Joint arithmetic geometry and number theory seminars are concrete examples of that connection; students can encounter visiting mathematicians beyond the university faculty.","There are several student-facing entry points into research: the Graduate Student Seminar, introductory colloquium lunches and What's Happening in Fine Hall talks. These are useful details when comparing the program's relatively independent structure with departments organized around a longer common course sequence."],"sources":[{"label":"Graduate program structure and student seminars","url":"https://www.math.princeton.edu/graduate"},{"label":"Department and joint IAS seminars","url":"https://www.math.princeton.edu/events/seminars"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":483,"facultyNames":["Bhargav Bhatt","June Huh","János Kollár","Shou-Wu Zhang"]},"purdue-university-west-lafayette":{"paragraphs":["Purdue's seminar list gives a useful picture of its breadth. Algebraic geometry, commutative algebra, automorphic forms and representation theory each have a visible place, alongside analysis and PDE, probability, topology, geometry and operator algebras.","There are also seminars in computational and applied mathematics, inverse problems, mathematical physics, and analytic number theory with harmonic analysis. Student-run seminars in several of these areas provide a different entry point from a research talk aimed at specialists.","For an algebra-oriented applicant, the separate algebraic geometry and commutative algebra activities are worth comparing with the actual faculty roster. For applied interests, inspect the computational group directly rather than assuming the general Mathematics PhD has one uniform emphasis."],"sources":[{"label":"Purdue research and student seminar communities","url":"https://www.math.purdue.edu/calendar/seminars/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":491,"facultyNames":["Deepam Patel","Shubhodip Mondal","Zhilin Luo","Donu Arapura"]},"rensselaer-polytechnic-institute":{"paragraphs":["RPI is a clear example of why a mathematics department's research character matters more than the degree title. Its published research is strongly oriented toward modelling, numerical methods and scientific problems: fluids and acoustics, electromagnetism, environmental modelling, mathematical biology and stochastic simulation all appear prominently.","The computational side includes high-performance algorithms, optimization and data science, and quantum-computing-related mathematics. If your aim is a traditional algebraic-geometry or number-theory PhD, the source dossier did not identify a clear primary adviser in that direction. For applied mathematics, numerical PDE or modelling, however, the same department is much more directly relevant."],"sources":[{"label":"RPI mathematical sciences research areas","url":"https://math.rpi.edu/research"},{"label":"RPI mathematics doctoral program","url":"https://math.rpi.edu/programs/phd-mathematics"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":499,"facultyNames":[]},"rice-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and mathematical physics at Rice University. The faculty examples below describe research in those areas.","David Urbanik’s listed work concerns algebraic and arithmetic geometry; families of varieties, Hodge theory, periods, special moduli and unlikely intersections. Chelsea Walton’s listed work concerns noncommutative and quantum algebra; quantum symmetries, Hopf algebras, braided module and monoidal categories, representation theory.","Brandon Levin’s listed work concerns p-adic Hodge theory, Galois deformations, local models and Langlands. Anthony Várilly-Alvarado’s listed work concerns arithmetic of K3/del Pezzo surfaces, Brauer groups, rationality. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Rice algebra and AG group","url":"https://mathweb.rice.edu/research/faculty-research/algebra","checked":"2026-11-05"},{"label":"Anthony Várilly-Alvarado papers","url":"https://math.rice.edu//~av15/","checked":"2026-11-05"},{"label":"Brandon Levin research","url":"https://math.rice.edu/~bl70/","checked":"2026-11-05"},{"label":"Chelsea Walton homepage","url":"https://math.rice.edu/~notlaw/","checked":"2026-11-05"},{"label":"Rice author research page","url":"https://math.rice.edu/~notlaw/research.html","checked":"2026-11-05"},{"label":"Morita invariants paper","url":"https://arxiv.org/abs/2508.19845","checked":"2026-11-05"},{"label":"Division algebras paper","url":"https://arxiv.org/abs/2502.02532","checked":"2026-11-05"},{"label":"Rice 2026 new faculty","url":"https://naturalsciences.rice.edu/new-faculty-2026","checked":"2026-11-05"},{"label":"Springer 2026 paper","url":"https://link.springer.com/article/10.1007/s00208-026-03364-1","checked":"2026-11-05"},{"label":"Duke/ProjectEuclid 2025 paper","url":"https://doi.org/10.1215/00127094-2024-0079","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":504,"facultyNames":["David Urbanik","Chelsea Walton","Brandon Levin","Anthony Várilly-Alvarado"]},"rutgers-university-new-brunswick":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, number theory, and algebraic geometry at Rutgers University-New Brunswick. The faculty examples below describe research in those areas.","Christopher Woodward’s listed work concerns symplectic and algebraic geometry, Lie theory, moduli spaces, quantum K-theory, tropical geometry and Fukaya categories. Alex Kontorovich’s listed work concerns analytic number theory, automorphic representations, arithmetic and thin groups, hyperbolic geometry and spectral/homogeneous dynamics.","Vladimir Retakh’s listed work concerns noncommutative algebra, cluster structures, marked surfaces and homological/algebraic methods. Konstantin Matveev’s listed work concerns symmetric functions, asymptotic representation theory, integrable probability and interacting particle systems. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current tenured and tenure-track faculty","url":"https://www.math.rutgers.edu/people/tenured-and-tenure-track-faculty","checked":"2026-11-05"},{"label":"Research areas and graduate faculty affiliations","url":"https://www.math.rutgers.edu/research/research-by-area","checked":"2026-11-05"},{"label":"Christopher Woodward - research/publication evidence","url":"https://sites.math.rutgers.edu/~ctw/papers.html","checked":"2026-11-05"},{"label":"Alex Kontorovich - research/publication evidence","url":"https://sites.math.rutgers.edu/~alexk/research.html","checked":"2026-11-05"},{"label":"Vladimir Retakh - research/publication evidence","url":"https://sites.math.rutgers.edu/~vretakh/publications.htm","checked":"2026-11-05"},{"label":"Konstantin Matveev - research/publication evidence","url":"https://www.researchwithrutgers.org/en/persons/konstantin-matveev/","checked":"2026-11-05"},{"label":"Alex Kontorovich - current appointment and chair term","url":"https://sites.math.rutgers.edu/~alexk/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":511,"facultyNames":["Christopher Woodward","Alex Kontorovich","Vladimir Retakh","Konstantin Matveev"]},"stanford-university":{"paragraphs":["Stanford's research directory presents several areas through their interactions. Number theory connects with dynamics and other parts of mathematics; probability includes statistical mechanics, random systems and financial questions; representation theory provides another route between algebra and applications.","Symplectic geometry is described at the intersection of low-dimensional topology, algebraic geometry, representation theory, Hamiltonian dynamics and mirror symmetry. If your interests sit between these subjects, compare the relevant people across several research headings rather than treating each heading as a separate department.","The directory is a useful map of mathematical possibilities, not a ranking of Stanford's groups. The next useful check is which current faculty, courses and seminars support the particular version of a subject you want to study."],"sources":[{"label":"Stanford research areas and their mathematical connections","url":"https://mathematics.stanford.edu/research/research-areas"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":524,"facultyNames":["Brian Conrad","Xinwen Zhu","Daniel Bump","Ravi Vakil"]},"stony-brook-university-suny":{"paragraphs":["Geometry is a good starting point for understanding Stony Brook. Differential and symplectic geometry, algebraic geometry, topology, complex analysis and dynamics are prominent in the department's own research description. The Institute for Mathematical Sciences adds a particular concentration in real and complex dynamical systems.","The neighboring Simons Center for Geometry and Physics matters here: shared faculty, seminars and visitors connect the department with mathematical physics. That gives a student interested in geometry a mathematical environment extending beyond a single research group.","Number theory is represented too, including Robert Hough's work in probability and analytic number theory. The sources reviewed support these specific interests, but do not establish computational algebraic number theory as a department-wide specialty. Computational applied mathematics also has a separate home in Applied Mathematics and Statistics; check which department offers the work you want."],"sources":[{"label":"Mathematics department and Institute for Mathematical Sciences","url":"https://math.stonybrook.edu/"},{"label":"Active research areas","url":"https://math.stonybrook.edu/active-areas-mathematics-research-stony-brook"},{"label":"Robert Hough: research interests","url":"https://www.math.stonybrook.edu/~rdhough/"},{"label":"Separate computational applied mathematics program","url":"https://www.stonybrook.edu/ams/academics/graduate/computational-applied-mathematics.html"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":534,"facultyNames":["Mark de Cataldo","Radu Laza","Christian Schnell","Jason Starr"]},"syracuse-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and logic at Syracuse University. The faculty examples below describe research in those areas.","Claudia Miller’s listed work concerns commutative and homological algebra, differential operators on singularities, matrix factorizations and algebraic geometry. Steven P. Diaz’s listed work concerns algebraic geometry of families of curves; an older institutional paper also concerns preprojective algebras and multiplication maps. A recent dated paper was not established.","Josh Pollitz’s listed work concerns homological commutative algebra, support theories and resolutions, with links to triangulated categories and representation theory. Dan Coman’s listed work concerns complex geometry and pluripotential theory; asymptotics of holomorphic bundles, Chern forms, and random degeneracy sets on compact Kähler manifolds. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics research areas","url":"https://artsandsciences.syracuse.edu/mathematics/math-research/","checked":"2026-11-05"},{"label":"Current faculty affiliation and research","url":"https://artsandsciences.syracuse.edu/people/faculty/josh-pollitz/","checked":"2026-11-05"},{"label":"Dan Coman official profile","url":"https://artsandsciences.syracuse.edu/people/faculty/coman-dan/","checked":"2026-11-05"},{"label":"Steven Diaz official profile","url":"https://artsandsciences.syracuse.edu/people/faculty/diaz-steven-p/","checked":"2026-11-05"},{"label":"Claudia Miller official profile","url":"https://artsandsciences.syracuse.edu/people/faculty/miller-claudia/","checked":"2026-11-05"},{"label":"Asymptotic expansion of induced Grassmannian Chern forms and distribution of random degeneracy sets","url":"https://arxiv.org/abs/2607.11489","checked":"2026-11-05"},{"label":"Almost Split Morphisms, Preprojective Algebras and Multiplication Maps of Maximal Rank","url":"https://surface.syr.edu/mat/75/","checked":"2026-11-05"},{"label":"Resolutions of Differential Operators of Low Order for an Isolated Hypersurface Singularity","url":"https://digitalcommons.oberlin.edu/faculty_schol/5182/","checked":"2026-11-05"},{"label":"Josh Pollitz research / publication evidence","url":"https://www.joshpollitz.com/research","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":540,"facultyNames":["Claudia Miller","Steven P. Diaz","Josh Pollitz","Dan Coman"]},"temple-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, and algebraic geometry at Temple University. The faculty examples below describe research in those areas.","Jaclyn Lang’s listed work concerns p-adic modular forms, Galois representations, Eisenstein ideals and arithmetic geometry. Vasily Dolgushev’s listed work concerns Grothendieck-Teichmueller theory, operads and Galois actions; an algebra/geometry connection rather than a conventional automorphic-representation specialization.","Ari Shnidman’s listed work concerns arithmetic statistics, rational points, abelian varieties, modular curves and L-values. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current mathematics faculty","url":"https://cst.temple.edu/department-mathematics/people/faculty","checked":"2026-11-05"},{"label":"Algebra and number theory group","url":"https://cst.temple.edu/department-mathematics/research/algebra-and-number-theory","checked":"2026-11-05"},{"label":"Jaclyn Lang faculty site","url":"https://sites.temple.edu/lang/","checked":"2026-11-05"},{"label":"Lang publications","url":"https://sites.temple.edu/lang/papers/","checked":"2026-11-05"},{"label":"Lang prospective students guidance","url":"https://sites.temple.edu/lang/prospective-students/","checked":"2026-11-05"},{"label":"Ari Shnidman institutional profile","url":"https://cst.temple.edu/directory/ari-shnidman","checked":"2026-11-05"},{"label":"Shnidman faculty site linked by Temple","url":"https://arishnidman.github.io/","checked":"2026-11-05"},{"label":"Shnidman 2026 paper primary record","url":"https://arxiv.org/abs/2609.00516","checked":"2026-11-05"},{"label":"Vasily Dolgushev faculty homepage","url":"https://sites.temple.edu/vald/","checked":"2026-11-05"},{"label":"Dolgushev official research list","url":"https://sites.temple.edu/vald/research/","checked":"2026-11-05"},{"label":"Dolgushev recent revision primary record","url":"https://arxiv.org/abs/2405.11725","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":547,"facultyNames":["Jaclyn Lang","Vasily Dolgushev","Ari Shnidman"]},"texas-a-m-university-college-station":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and number theory at Texas A&M University, College Station. The faculty examples below describe research in those areas.","Eric Rowell’s listed work concerns braided fusion categories, Yang-Baxter operators and quantum topology. J. Maurice Rojas’s listed work concerns algorithmic algebraic geometry, tropical and p-adic polynomial solving.","Paulo Lima-Filho’s listed work concerns algebraic geometry and algebraic topology; higher Chow groups, regulators and geometric currents, algebraic K-theory, and algebraic groups. Frank Sottile’s listed work concerns enumerative, real and computational algebraic geometry; Schubert calculus and Galois groups. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra faculty","url":"https://artsci.tamu.edu/mathematics/research/algebra-combinatorics/index.html","checked":"2026-11-05"},{"label":"Sottile papers","url":"https://franksottile.github.io/research/publications.html","checked":"2026-11-05"},{"label":"Rowell paper","url":"https://arxiv.org/abs/2609.38290","checked":"2026-11-05"},{"label":"Rojas papers","url":"https://rojas-mathcs.github.io/list.html","checked":"2026-11-05"},{"label":"TAMU profile","url":"https://artsci.tamu.edu/mathematics/contact/profiles/paulo-lima-filho.html","checked":"2026-11-05"},{"label":"Sottile prospective-student invitation","url":"https://franksottile.github.io/","checked":"2026-11-05"},{"label":"Springer regulator paper","url":"https://link.springer.com/article/10.1007/s00209-024-03645-y","checked":"2026-11-05"},{"label":"Regulator preprint","url":"https://arxiv.org/abs/2307.03991","checked":"2026-11-05"},{"label":"LULU publisher","url":"https://www.sciencedirect.com/science/article/abs/pii/S0022404925000192","checked":"2026-11-05"},{"label":"LULU author preprint","url":"https://arxiv.org/abs/2405.02701","checked":"2026-11-05"},{"label":"UNAM institutional coauthor publication record","url":"https://web.siia.unam.mx/siia-publico/c/busqueda_individual.php?id=125981","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":554,"facultyNames":["Eric Rowell","J. Maurice Rojas","Paulo Lima-Filho","Frank Sottile"]},"texas-tech-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, geometry, number theory, and analysis & PDE at Texas Tech University. The faculty examples below describe research in those areas.","Chris Monico’s listed work concerns computational algebra and number theory, algebraic cryptography, semigroup actions, invariants and algorithms in the plactic monoid. Dermot McCarthy’s listed work concerns finite-field/p-adic hypergeometric functions, modular forms, point counts on hypersurfaces.","Lars Winther Christensen’s listed work concerns homological/homotopical methods in ring theory and singularity categories. Arne Ledet’s listed work concerns field theory, polynomials and associative algebras; recent paper not yet verified. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Chris Monico paper evidence","url":"https://www.math.ttu.edu/~cmonico/","checked":"2026-11-05"},{"label":"Faculty research directory","url":"https://www.depts.ttu.edu/math/about/directory/research.php","checked":"2026-11-05"},{"label":"McCarthy author publications","url":"https://dermotmccarthymath.github.io/publications","checked":"2026-11-05"},{"label":"Christensen January 2026 CV","url":"https://www.math.ttu.edu/~lchriste/download/lwc-cv.pdf","checked":"2026-11-05"},{"label":"Arne Ledet publication verification","url":"https://www.plenilunary.com/publications.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":565,"facultyNames":["Chris Monico","Dermot McCarthy","Lars Winther Christensen","Arne Ledet"]},"tufts-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, geometry, and analysis & PDE at Tufts University. The faculty examples below describe research in those areas.","David Smyth’s listed work concerns singular curves and modular compactifications. A verified 2026 publication instead concerns Boolean reducibility in philosophy; obtain an updated algebraic-geometry project list before assessing current fit. Fulton Gonzalez’s listed work concerns Lie-group harmonic analysis, symmetric spaces and integral geometry; recent work on wave-equation reconstruction including noncompact symmetric spaces.","Montserrat Teixidor i Bigas’s listed work concerns algebraic curves, vector bundles and moduli, Brill-Noether theory and limit linear series. George McNinch’s listed work concerns linear algebraic groups and their representations, Levi factors, nilpotent orbits and local-global principles; also formalization in Lean. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"David Smyth official research/profile","url":"https://onlinelibrary.wiley.com/doi/10.1111/phpr.70118","checked":"2026-11-05"},{"label":"Fulton Gonzalez official research/profile","url":"https://www.sciencedirect.com/science/article/pii/S0001870824001440","checked":"2026-11-05"},{"label":"Montserrat Teixidor i Bigas official research/profile","url":"https://link.springer.com/article/10.1007/s00209-026-03996-8","checked":"2026-11-05"},{"label":"George McNinch official research/profile","url":"https://gmcninch.math.tufts.edu/pages/manuscripts.html","checked":"2026-11-05"},{"label":"Montserrat Teixidor i Bigas official appointment","url":"https://math.tufts.edu/people/faculty/montserrat-teixidor-i-bigas","checked":"2026-11-05"},{"label":"David Smyth official appointment","url":"https://math.tufts.edu/people/faculty/david-smyth","checked":"2026-11-05"},{"label":"George McNinch official appointment","url":"https://gmcninch.math.tufts.edu/pages/about.html","checked":"2026-11-05"},{"label":"Fulton Gonzalez official appointment","url":"https://math.tufts.edu/people/faculty/fulton-gonzalez","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":572,"facultyNames":["David Smyth","Fulton Gonzalez","Montserrat Teixidor i Bigas","George McNinch"]},"tulane-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, mathematical physics, and number theory at Tulane University. The faculty examples below describe research in those areas.","Kalina Mincheva’s listed work concerns tropical algebraic geometry, semirings, toric vector bundles, and representation theory over semifields. Mahir Bilen Can’s listed work concerns algebraic groups and monoids, Schubert and Hessenberg varieties, representation theory, and algebraic coding theory.","Tài Huy Hà’s listed work concerns commutative and computational algebra with algebraic geometry: syzygies, ideal powers and containment, graded families, and Newton-Okounkov bodies. Olivia Beckwith’s listed work concerns modular and mock modular forms, Maass forms, and arithmetic of partitions; recent work concerns scarcity of partition congruences. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Kalina Mincheva official research/profile","url":"https://www.math.tulane.edu/~kmincheva/docs/CV.pdf","checked":"2026-11-05"},{"label":"Mahir Bilen Can official research/profile","url":"https://mahirbilencan.github.io/","checked":"2026-11-05"},{"label":"Tài Huy Hà official research/profile","url":"https://www.math.tulane.edu/~tai/cv.pdf","checked":"2026-11-05"},{"label":"Olivia Beckwith official research/profile","url":"https://experts.illinois.edu/en/publications/scarcity-of-partition-congruences-on-semiprime-progressions/","checked":"2026-11-05"},{"label":"Tài Huy Hà official appointment","url":"https://www.math.tulane.edu/~tai/","checked":"2026-11-05"},{"label":"Kalina Mincheva official appointment","url":"https://www.math.tulane.edu/~kmincheva/","checked":"2026-11-05"},{"label":"Olivia Beckwith official appointment","url":"https://sse.tulane.edu/olivia-beckwith","checked":"2026-11-05"},{"label":"Mahir Bilen Can official appointment","url":"https://www.math.tulane.edu/~mcan/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":579,"facultyNames":["Kalina Mincheva","Mahir Bilen Can","Tài Huy Hà","Olivia Beckwith"]},"university-at-buffalo-suny":{"paragraphs":["Buffalo's algebra group explicitly includes number theory, arithmetic geometry, automorphic forms, categorical algebra, cryptography, L-functions and representation theory. The analysis group overlaps some of those interests through analytic number theory and automorphic forms, as well as operator theory, dynamics and complex geometry.","Applied research includes nonlinear waves, networks, scientific computing and continuum models. Geometry and topology cover algebraic topology, complex and differential geometry, geometric group theory and geometric topology.","That mix makes Buffalo worth examining through several connected research headings. For an applicant interested in arithmetic or representation theory, the overlap between the algebra and analysis descriptions is more informative than treating those as disconnected boxes."],"sources":[{"label":"Buffalo faculty research groups","url":"https://www.buffalo.edu/cas/math/research.html"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":585,"facultyNames":["Hui June Zhu","Adam Sikora","Vijaylaxmi Trivedi","Thomas Cusick"]},"university-of-alabama-tuscaloosa":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and logic at University of Alabama - Tuscaloosa. The faculty examples below describe research in those areas.","Ulysses Alvarez’s listed work concerns tropical phased matroids, hyperfields and topological combinatorics, adjacent to tropical algebraic geometry. Kyungyong Lee’s listed work concerns cluster algebras, scattering diagrams, positivity, quiver representations and algebraic combinatorics; current KIAS research listing corroborates recent papers.","Prashanth Sridhar’s listed work concerns derived and homological methods in commutative algebra and algebraic geometry. Michael Perlman’s listed work concerns equivariant D-modules, local cohomology, determinantal/Schubert varieties and mixed Hodge structures. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Faculty research areas","url":"https://math.ua.edu/research-overview/","checked":"2026-11-05"},{"label":"Michael Perlman CV","url":"https://math.ua.edu/wp-content/uploads/2025/08/CV-1.pdf","checked":"2026-11-05"},{"label":"Coauthor Brown official publication list: Sridhar papers","url":"https://webhome.auburn.edu/~mkb0096/","checked":"2026-11-05"},{"label":"Algebra group","url":"https://math.ua.edu/research-overview/algebra-research-group/","checked":"2026-11-05"},{"label":"Broken lines and compatible pairs for rank 2 quantum cluster algebras","url":"https://kias.re.kr/kias/people/faculty/viewMember.do?memberId=82147&menuNo=401005&pageIndex=&trget=listScholars","checked":"2026-11-05"},{"label":"A topological space associated to corank 1 tropical phased matroids","url":"https://arxiv.org/abs/2302.11005","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":593,"facultyNames":["Ulysses Alvarez","Kyungyong Lee","Prashanth Sridhar","Michael Perlman"]},"university-of-arizona":{"paragraphs":["Arizona has a visible arithmetic-geometry community, and the Arizona Winter School is an important part of its mathematical setting. The school brings graduate students and researchers together for extended courses and project work; its preparatory online program also serves advanced undergraduates and beginning graduate students. Those events are useful evidence of research activity, although their visitors are not the same thing as the department’s advising roster.","The department also has a substantial analysis and mathematical-physics side. Its research descriptions include statistical mechanics, quantum field theory, random matrices, disordered systems, and geometric analysis. Computational group theory is another specific thread: the group describes using GAP in both research and graduate teaching.","The mathematics graduate program advertises an incoming-student integration workshop and early research training in the second PhD year. These are concrete features to compare with other programs. Arizona’s arithmetic and mathematical-physics communities give rather different reasons to apply, so use the relevant faculty and seminars to narrow down your fit."],"sources":[{"label":"Southwest Center — Arizona Winter School and preparatory program","url":"https://swc-math.github.io/"},{"label":"Arizona Winter School — project and working-group guide","url":"https://swc-math.github.io/notes/files/AWSGuide.pdf"},{"label":"Arizona — research areas","url":"https://www.math.arizona.edu/research/areas"},{"label":"Arizona — mathematics graduate program","url":"https://math.arizona.edu/academics/graduate"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":600,"facultyNames":["Douglas Ulmer","Douglas Pickrell","Sergey Cherkis","Anna Medvedovsky"]},"university-of-california-berkeley":{"paragraphs":["Berkeley is organized around overlapping groups in algebra, analysis, applied mathematics, geometry and topology, logic, and probability. Its algebra group explicitly includes number theory, algebraic geometry and combinatorics, so those labels cover quite a lot of different mathematics.","Geometry and topology concentrate on manifolds and their interactions with algebra and analysis, with low-dimensional topology a visible part of the department's description. There is also an integrated applied mathematics community: Berkeley does not treat pure and applied mathematics as separate departments.","That breadth makes it worth identifying a smaller cluster of people and seminars within the larger department. The research pages describe connections with other Berkeley departments and Lawrence Berkeley National Laboratory for students whose work reaches into computation or applications."],"sources":[{"label":"Research group organization","url":"https://math.berkeley.edu/research/areas"},{"label":"Descriptions of algebra, geometry/topology and applied mathematics","url":"https://math.berkeley.edu/departments"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":611,"facultyNames":["Constantin Teleman","Martin Olsson","Christian Gaetz","Edward Frenkel"]},"university-of-california-davis":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, geometry, mathematical physics, and number theory at University of California, Davis. The faculty examples below describe research in those areas.","Erik Carlsson’s listed work concerns geometric representation theory, Macdonald polynomials and Hilbert schemes; recent work also computational topology. Anne Schilling’s listed work concerns crystal bases, quantum algebras, algebraic combinatorics and symmetric/quasisymmetric functions.","Adam Jacob’s listed work concerns complex differential geometry, Hermitian-Yang-Mills equations, geometric flows and mirror symmetry. Elena Fuchs’s listed work concerns arithmetic thin groups, Apollonian packings, Markoff dynamics and cryptography. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Carlsson research","url":"https://www.math.ucdavis.edu/~ecarlsson/","checked":"2026-11-05"},{"label":"Schilling research","url":"https://www.math.ucdavis.edu/~anne/research.html","checked":"2026-11-05"},{"label":"Jacob CV","url":"https://www.math.ucdavis.edu/~ajacob/ajacobCV5.pdf","checked":"2026-11-05"},{"label":"Fuchs research","url":"https://www.math.ucdavis.edu/~efuchs/research.html","checked":"2026-11-05"},{"label":"Faculty roster","url":"https://www.math.ucdavis.edu/people/faculty","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":622,"facultyNames":["Erik Carlsson","Anne Schilling","Adam Jacob","Elena Fuchs"]},"university-of-california-irvine":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and analysis & PDE at University of California, Irvine. The faculty examples below describe research in those areas.","Jesse Wolfson’s listed work concerns essential and resolvent dimension, arithmetic topology, descent and K-theory. Vladimir Baranovsky’s listed work concerns bundles, deformation quantization, noncommutative and symplectic algebraic geometry.","Xiangwen Zhang’s listed work concerns nonlinear PDE on Kähler/Hermitian manifolds and geometric flows. Alexandra Florea’s listed work concerns analytic number theory, moments/nonvanishing of L-functions over number and function fields. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Geometry roster","url":"https://www.math.uci.edu/research/geometry-and-topology","checked":"2026-11-05"},{"label":"Algebra and number theory roster","url":"https://webapps.math.uci.edu/research/algebra-and-number-theory","checked":"2026-11-05"},{"label":"Baranovsky preprint","url":"https://arxiv.org/abs/2607.12910","checked":"2026-11-05"},{"label":"Florea publications","url":"https://sites.google.com/view/alexandraflorea/publications","checked":"2026-11-05"},{"label":"Zhang publisher paper","url":"https://www.aimsciences.org/article/doi/10.3934/cpaa.2026107","checked":"2026-11-05"},{"label":"Wolfson university profile","url":"https://scholarconnect.uci.edu/wolfson","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":629,"facultyNames":["Jesse Wolfson","Vladimir Baranovsky","Xiangwen Zhang","Alexandra Florea"]},"university-of-california-los-angeles":{"paragraphs":["Analysis and PDE are particularly visible parts of UCLA's research community. The analysis group describes work on harmonic analysis, dispersive and wave equations, microlocal analysis, fluid dynamics, free boundaries, optimal transport and related problems.","The department also has groups in algebra, number theory, combinatorics, geometry, topology, logic, probability and mathematical physics. Computational Applied Mathematics has its own group, so someone interested in analysis can compare both theoretical and computational directions.","The analysis community extends beyond campus through a joint seminar with Caltech and a Southern California conference involving UC San Diego and UC Irvine. These are concrete research connections; they are more useful for judging a possible mathematical home than an old overall ranking."],"sources":[{"label":"UCLA research groups","url":"https://ww3.math.ucla.edu/research-areas/"},{"label":"Analysis and regional seminars","url":"https://ww3.math.ucla.edu/research-areas/elementor-1671/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":638,"facultyNames":["Burt Totaro","Terence Tao","Robert Greene","Gurbir Dhillon"]},"university-of-california-riverside":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, algebraic geometry, and combinatorics at University of California, Riverside. The faculty examples below describe research in those areas.","Patricio Gallardo Candela’s listed work concerns moduli and compactifications, Hodge theory, singularities and combinatorial algebraic geometry. Tom Gannon’s listed work concerns geometric representation theory: Hamiltonian reduction, Coulomb branches, D-modules and connections to Langlands and mathematical physics.","Wee Liang Gan’s listed work concerns representation-theoretic and homological methods; recent work includes persistence modules. Earlier work includes symplectic reflection algebras and Hamiltonian reduction; confirm current preferred projects. Jacob Greenstein’s listed work concerns quantum groups, Hecke structures, algebraic combinatorics and Hall-algebra methods. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Patricio Gallardo Candela official research/profile","url":"https://math.ucr.edu/~joselg/research.html","checked":"2026-11-05"},{"label":"Tom Gannon official research/profile","url":"https://arxiv.org/abs/2608.25994","checked":"2026-11-05"},{"label":"Wee Liang Gan official research/profile","url":"https://arxiv.org/abs/2507.01303","checked":"2026-11-05"},{"label":"Jacob Greenstein official research/profile","url":"https://arxiv.org/abs/2605.09761","checked":"2026-11-05"},{"label":"Wee Liang Gan official appointment","url":"https://cs.ucr.edu/~cshelton/catalog/2026-27/sections/mathematics.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":648,"facultyNames":["Patricio Gallardo Candela","Tom Gannon","Wee Liang Gan","Jacob Greenstein"]},"university-of-california-san-diego":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at University of California, San Diego. The faculty examples below describe research in those areas.","Dragos Oprea’s listed work concerns moduli of sheaves and abelian varieties, intersection theory, tautological classes, Gromov-Witten theory and related enumerative geometry. Jonathan Novak’s listed work concerns matrix integrals and multivariate special functions using algebraic combinatorics and representation theory; connections with Hurwitz numbers, random matrices and quasimodular forms.","Alireza Salehi Golsefidy’s listed work concerns arithmetic and analytic properties of linear groups, expansion and random walks, homogeneous dynamics and representation/character varieties. Freddie Manners’s listed work concerns arithmetic/additive combinatorics, higher-order Fourier analysis, inverse Gowers-norm theory and small-doubling phenomena; an analytic/arithmetic-combinatorial rather than arithmetic-geometric fit. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current mathematics faculty catalog","url":"https://catalog.ucsd.edu/faculty/MATH.html","checked":"2026-11-05"},{"label":"Algebraic geometry group","url":"https://math.ucsd.edu/research/algebraic-geometry","checked":"2026-11-05"},{"label":"Number theory group","url":"https://www.math.ucsd.edu/research/number-theory","checked":"2026-11-05"},{"label":"Algebra group","url":"https://www.math.ucsd.edu/research/algebra","checked":"2026-11-05"},{"label":"Dragos Oprea official publication list","url":"https://mathweb.ucsd.edu/~doprea/publications.html","checked":"2026-11-05"},{"label":"Alireza Salehi Golsefidy research","url":"https://mathweb.ucsd.edu/~asalehig/research.html","checked":"2026-11-05"},{"label":"Golsefidy and Tamam coarse moduli manuscript","url":"https://mathweb.ucsd.edu/~asalehig/G_T_SchemePart.pdf","checked":"2026-11-05"},{"label":"Freddie Manners official research page","url":"https://mathweb.ucsd.edu/~fmanners/research.htm","checked":"2026-11-05"},{"label":"Manners and coauthors Marton conjecture article","url":"https://annals.math.princeton.edu/2025/201-2/p05","checked":"2026-11-05"},{"label":"Jonathan Novak current official profile","url":"https://www.math.ucsd.edu/people/profiles/jonathan-novak","checked":"2026-11-05"},{"label":"Novak 2025 Berezin-Karpelevich article","url":"https://link.springer.com/article/10.1007/s11005-025-01939-8","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":658,"facultyNames":["Dragos Oprea","Jonathan Novak","Alireza Salehi Golsefidy","Freddie Manners"]},"university-of-california-santa-barbara":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and mathematical physics at University of California, Santa Barbara. The faculty examples below describe research in those areas.","Amalendu Krishna’s listed work concerns algebraic cycles, K-theory, arithmetic geometry and Brauer groups over local fields. Zhenghan Wang’s listed work concerns quantum algebra, finite/modular tensor categories and their topological applications.","David R. Morrison’s listed work concerns algebraic/complex geometry of K3, Enriques and Calabi-Yau varieties, mirror symmetry and mathematical physics. Zijian Yao’s listed work concerns p-adic arithmetic geometry, prismatic cohomology, Galois representations and local systems. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty and emeriti","url":"https://www.math.ucsb.edu/people","checked":"2026-11-05"},{"label":"Zhenghan Wang current faculty","url":"https://www.math.ucsb.edu/people/zhenghan-wang","checked":"2026-11-05"},{"label":"Number theory group","url":"https://www.math.ucsb.edu/research/number-theory","checked":"2026-11-05"},{"label":"Amalendu Krishna current faculty","url":"https://math.ucsb.edu/people/amalendu-krishna","checked":"2026-11-05"},{"label":"Krishna: Brauer groups paper","url":"https://arxiv.org/abs/2601.15461","checked":"2026-11-05"},{"label":"David Morrison publications","url":"https://web.math.ucsb.edu/~drm/publications/","checked":"2026-11-05"},{"label":"Zijian Yao current faculty","url":"https://www.math.ucsb.edu/people/zijian-yao","checked":"2026-11-05"},{"label":"Yao: crystalline local systems","url":"https://arxiv.org/abs/2509.19813","checked":"2026-11-05"},{"label":"Wang publication list","url":"https://web.math.ucsb.edu/~zhenghwa/pub.php","checked":"2026-11-05"},{"label":"Wang: finite tensor categories","url":"https://arxiv.org/abs/2501.03987","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":676,"facultyNames":["Amalendu Krishna","Zhenghan Wang","David R. Morrison","Zijian Yao"]},"university-of-california-santa-cruz":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at University of California, Santa Cruz. The faculty examples below describe research in those areas.","Beren Sanders’s listed work concerns tensor triangular geometry, derived categories, modular representations and motivic/stable homotopy theory. Jesse Leo Kass’s listed work concerns moduli of sheaves and compactified Jacobians, abelian varieties, and arithmetic curve counts using motivic methods.","Laura Escobar’s listed work concerns Schubert varieties, torus actions, polytopes and combinatorial models of singularities; toric geometry and its generalizations. Junecue Suh’s listed work concerns Shimura varieties, Hodge theory, zeta functions and p-adic representations; current profile also emphasizes geometric methods for stable lattices. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Beren Sanders official research/profile","url":"https://people.ucsc.edu/~beren/","checked":"2026-11-05"},{"label":"Jesse Leo Kass official research/profile","url":"https://people.ucsc.edu/~jelkass/","checked":"2026-11-05"},{"label":"Laura Escobar official research/profile","url":"https://doi.org/10.1090/proc/17796","checked":"2026-11-05"},{"label":"Junecue Suh official research/profile","url":"https://arxiv.org/abs/2410.01182","checked":"2026-11-05"},{"label":"Laura Escobar official appointment","url":"https://directory.ucsc.edu/cd_detail?guid=G113926365","checked":"2026-11-05"},{"label":"Junecue Suh official appointment","url":"https://directory.ucsc.edu/cd_detail?guid=G040792820","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":688,"facultyNames":["Beren Sanders","Jesse Leo Kass","Laura Escobar","Junecue Suh"]},"university-of-chicago":{"paragraphs":["Chicago has a broad pure-mathematics community rather than one narrow specialty. Its published research description spans algebraic geometry, number theory, representation theory, geometry and topology, analysis, probability, dynamics, logic and combinatorics, alongside applied work.","A useful part of the department's structure is the substantial group of Dickson Instructors. The mathematical community therefore includes many early-career researchers as well as permanent faculty. Daily seminars, visiting speakers and recurring lecture series give several ways to explore a subject before narrowing a thesis direction.","For a Chicago undergraduate, the local names in the connections database are a starting point for discovering related groups elsewhere. Emeritus faculty and former postdocs can provide useful mathematical context, but a historical connection does not establish current advising availability."],"sources":[{"label":"Department research and seminar environment","url":"https://mathematics.uchicago.edu/about/"},{"label":"Current academic directory","url":"https://mathematics.uchicago.edu/people/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":699,"facultyNames":["Akhil Mathew","Simion Filip","Benson Farb","Kazuya Kato"]},"university-of-cincinnati":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, dynamical systems, and number theory at University of Cincinnati. The faculty examples below describe research in those areas.","Seungki Kim’s listed work concerns lattice problems, geometry of numbers, homogeneous dynamics and cryptography.","Tara L. Smith’s listed work concerns quadratic forms, division algebras, Galois groups, valuations and ordered fields; no recent paper list verified. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Applied mathematics research faculty","url":"https://www.artsci.uc.edu/natural-sciences/math/research/applied-math.html","checked":"2026-11-05"},{"label":"Tara L. Smith publication verification","url":"https://researchdirectory.uc.edu/p/smtl","checked":"2026-11-05"},{"label":"Seungki Kim research homepage","url":"https://sites.google.com/view/seungki/home","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":709,"facultyNames":["Seungki Kim","Tara L. Smith"]},"university-of-colorado-boulder":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at University of Colorado Boulder. The faculty examples below describe research in those areas.","David Grant’s listed work concerns arithmetic geometry, abelian varieties and algebraic-geometric coding theory. Su-ion Ih’s listed work concerns arithmetic dynamics and distribution/finiteness of integral and algebraic points.","Eric Stade’s listed work concerns automorphic forms, Whittaker functions and explicit harmonic analysis underlying higher-rank L-functions. Richard Green’s listed work concerns Coxeter/Weyl groups, Hecke algebras, diagram algebras, root-system combinatorics and minuscule representations. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics number theory faculty","url":"https://www.colorado.edu/math/research/number-theory","checked":"2026-11-05"},{"label":"Mathematics algebra faculty","url":"https://www.colorado.edu/math/research/algebra","checked":"2026-11-05"},{"label":"David Grant publications","url":"https://euclid.colorado.edu/~grant/publications/publications.html","checked":"2026-11-05"},{"label":"Su-ion Ih publications","url":"https://math.colorado.edu/~ih/publications.html","checked":"2026-11-05"},{"label":"Eric Stade CV","url":"https://vivo.colorado.edu/vitas/100456.pdf","checked":"2026-11-05"},{"label":"Richard Green official research page","url":"https://math.colorado.edu/~rmg/","checked":"2026-11-05"},{"label":"Green author repository linked from official page","url":"https://arxiv.org/search/math?query=Green,+R+M&searchtype=author","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":714,"facultyNames":["David Grant","Su-ion Ih","Eric Stade","Richard Green"]},"university-of-connecticut":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, geometry, number theory, and analysis & PDE at University of Connecticut. The faculty examples below describe research in those areas.","Ralf Schiffler’s listed work concerns quiver representations, cluster algebras, categorification, quantum affine algebras and geometric models for syzygies. Damin Wu’s listed work concerns Kähler-Einstein geometry, holomorphic curvature and positivity of canonical bundles, geometric PDE; also spaces of Riemannian metrics.","Álvaro Lozano-Robledo’s listed work concerns elliptic curves and abelian varieties, Mordell-Weil groups and Galois representations, especially complex multiplication and division fields. Kyu-Hwan Lee’s listed work concerns quantum and Kac-Moody algebras, cluster algebras, arithmetic statistics and AI-assisted number theory; recent publications connect quantum cluster structures with Grothendieck rings. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Ralf Schiffler official research/profile","url":"https://schiffler.math.uconn.edu/home/publications/","checked":"2026-11-05"},{"label":"Wu current official publication list","url":"https://dwu.math.uconn.edu/publications/","checked":"2026-11-05"},{"label":"Álvaro Lozano-Robledo official research/profile","url":"https://alozanoroble.github.io/books/","checked":"2026-11-05"},{"label":"Kyu-Hwan Lee official research/profile","url":"https://khlee-math.github.io/publications/index.html","checked":"2026-11-05"},{"label":"Álvaro Lozano-Robledo official appointment","url":"https://alozano.clas.uconn.edu/","checked":"2026-11-05"},{"label":"Damin Wu official appointment","url":"https://math.uconn.edu/person/damin-wu/","checked":"2026-11-05"},{"label":"Kyu-Hwan Lee official appointment","url":"https://www.kias.re.kr/kias/people/faculty/viewMember.do?memberId=87595&menuNo=401005&pageIndex=&trget=listScholars","checked":"2026-11-05"},{"label":"Ralf Schiffler official appointment","url":"https://math.uconn.edu/research-areas/algebra-and-number-theory/","checked":"2026-11-05"},{"label":"Wu primary preprint record","url":"https://arxiv.org/abs/1908.02475","checked":"2026-11-05"},{"label":"Wu 2025 award official notice","url":"https://math.uconn.edu/2025/02/24/paper-co-authored-by-professor-damin-wu-wins-2025-frontiers-of-science-award/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":724,"facultyNames":["Ralf Schiffler","Damin Wu","Álvaro Lozano-Robledo","Kyu-Hwan Lee"]},"university-of-delaware":{"paragraphs":["Delaware has a substantial applied and computational side. Its research groups cover numerical analysis, scientific computing, fluids and materials, inverse scattering, and mathematical medicine. The department describes projects involving tear films, bone imaging, acoustic and electromagnetic waves, and numerical methods for PDE. These are concrete examples of the modeling and computation available here.","Discrete mathematics and analysis are also part of the picture. Robert Coulter works on functions over finite fields and their connections to cryptography, projective geometry, and combinatorial designs. The department’s other listed topics include spectral graph theory, operator theory, harmonic analysis, and mathematical questions from quantum information. For an algebra applicant, the finite-field and discrete directions are more informative than a generic algebraic-geometry label.","The department publishes early research opportunities for graduate students, including a summer fellowship and the GEMS program pairing a graduate student, an undergraduate, and a faculty adviser. Those are specific ways to begin research before the thesis stage. Availability and selection for those programs should be checked for your entering cohort."],"sources":[{"label":"Delaware — research groups and early graduate research","url":"https://www.udel.edu/academics/colleges/cas/units/departments/mathematical-sciences/research-programs/"},{"label":"Robert Coulter — official profile and research interests","url":"https://www.udel.edu/academics/colleges/cas/units/departments/mathematical-sciences/our-people/robert-coulter/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":733,"facultyNames":["Robert Coulter"]},"university-of-florida":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, combinatorics, and algebraic geometry at University of Florida. The faculty examples below describe research in those areas.","Paul L. Robinson’s listed work concerns classical elliptic functions and related analytic structures; this is a more specialized adjacent fit than complex algebraic geometry. Peter Sin’s listed work concerns finite groups and representations, with applications to Cayley graphs and quantum state transfer.","Luca Fabrizio Di Cerbo’s listed work concerns Kähler manifolds, complex surfaces, curvature and fundamental groups. Kevin Keating’s listed work concerns local fields, ramification and Galois module structure. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current mathematics faculty","url":"https://math.ufl.edu/People/Faculty/","checked":"2026-11-05"},{"label":"Luca Di Cerbo publications","url":"https://people.clas.ufl.edu/ldicerbo/publications/","checked":"2026-11-05"},{"label":"Kevin Keating curriculum vitae and publications","url":"https://people.clas.ufl.edu/keating/files/cv.pdf","checked":"2026-11-05"},{"label":"Peter Sin official publications","url":"https://scholars.ufl.edu/sin/publications","checked":"2026-11-05"},{"label":"Paul Robinson recent elliptic function article","url":"https://www.cambridge.org/core/journals/bulletin-of-the-australian-mathematical-society/article/halphen-and-the-elliptic-functions-of-du-val/A3D7D00A67CD3768E2A1ED8E668D6408","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":739,"facultyNames":["Paul L. Robinson","Peter Sin","Luca Fabrizio Di Cerbo","Kevin Keating"]},"university-of-georgia":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at University of Georgia. The faculty examples below describe research in those areas.","William Graham’s listed work concerns equivariant K-theory/intersection theory, flag and Schubert varieties, and geometric representation theory. Daniel K. Nakano’s listed work concerns algebraic/quantum groups and Lie superalgebras; cohomology, support varieties, and tensor-triangular geometry.","Dino Lorenzini’s listed work concerns arithmetic geometry of curves and surfaces, wild quotient singularities, reduction, and arithmetic of number fields. Valery Alexeev’s listed work concerns moduli and compactification of algebraic surfaces, K3/Enriques surfaces, and log Calabi-Yau geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"William Graham official research/profile","url":"https://math.uga.edu/directory/people/william-graham","checked":"2026-11-05"},{"label":"Daniel K. Nakano official research/profile","url":"https://math.uga.edu/sites/default/files/CVs/DNakanoCV26.pdf","checked":"2026-11-05"},{"label":"Dino Lorenzini official research/profile","url":"https://dinolorenzini.franklinresearch.uga.edu/publications-and-preprints","checked":"2026-11-05"},{"label":"Valery Alexeev official research/profile","url":"https://www.math.uga.edu/directory/valery-alexeev","checked":"2026-11-05"},{"label":"Dino Lorenzini official appointment","url":"https://dinolorenzini.franklinresearch.uga.edu/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":750,"facultyNames":["William Graham","Daniel K. Nakano","Dino Lorenzini","Valery Alexeev"]},"university-of-houston":{"paragraphs":["The supplied dossier emphasizes number theory, algebraic geometry, and dynamical systems at University of Houston. The faculty examples below describe research in those areas.","Gordon Heier’s listed work concerns curvature/positivity, hyperbolicity, effective geometry, Diophantine approximation. Shanyu Ji’s listed work concerns several complex variables, CR geometry and rigidity of proper holomorphic mappings between balls. The reviewed official list stops at 2021, so a more recent dated paper remains unverified.","Min Ru’s listed work concerns Nevanlinna theory, hyperbolicity, Diophantine approximation and minimal surfaces. Alan Haynes’s listed work concerns Diophantine approximation, uniform distribution, geometry of numbers, and quasicrystals/cut-and-project sets. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Gordon Heier research","url":"https://www.math.uh.edu/~heier/research.html","checked":"2026-11-05"},{"label":"Complex geometry group","url":"https://www.uh.edu/nsm/math/research/research-groups/complex-geometry-n-complex-analysis/index.php","checked":"2026-11-05"},{"label":"Min Ru research","url":"https://www.math.uh.edu/~minru/","checked":"2026-11-05"},{"label":"Alan Haynes official profile","url":"https://www.math.uh.edu/~haynes/cv.html","checked":"2026-11-05"},{"label":"A map of degree 3 from n-ball into (3n-2)-ball is determined by its 3-jets","url":"https://www.math.uh.edu/~shanyuji/MyWeb/Publications_complete.html","checked":"2026-11-05"},{"label":"Gaps theorems for linear forms with cubic coefficients","url":"https://www.math.uh.edu/~haynes/publications.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":757,"facultyNames":["Gordon Heier","Shanyu Ji","Min Ru","Alan Haynes"]},"university-of-illinois-chicago":{"paragraphs":["UIC's department combines Mathematics, Statistics, and Computer Science. Its research groups include mathematical computer science and statistics as well as pure and applied mathematics, so the department's scope is wider than the word mathematics alone suggests.","The published groups include algebra and algebraic geometry, analysis and PDE, combinatorics and probability, dynamics, geometry and topology, logic, number theory and theoretical computer science. Applied computation and probability, statistics and data science are also explicit parts of the research map.","This structure can be useful if your interests lie between proof-based mathematics and theoretical computing or statistical questions. Check the particular degree route and research group, since sharing a department does not make the training requirements interchangeable."],"sources":[{"label":"UIC MSCS research groups","url":"https://mscs.uic.edu/research-groups/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":763,"facultyNames":["James Freitag","Emily Dumas","Jan Verschelde","Ramin Takloo-Bighash"]},"university-of-illinois-urbana-champaign":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, mathematical physics, and topology at University of Illinois Urbana-Champaign. The faculty examples below describe research in those areas.","Vesna Stojanoska’s listed work concerns chromatic and stable homotopy theory, Picard groups and arithmetic aspects of cohomology theories. Alexander Yong’s listed work concerns Schubert geometry, algebraic combinatorics, eigencones and representation multiplicities.","Jesse Thorner’s listed work concerns analytic and algebraic number theory, automorphic L-functions, Chebotarev estimates and arithmetic statistics. Kevin Ford’s listed work concerns analytic and probabilistic number theory, primes, divisors and sieve methods. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Vesna Stojanoska official profile and recent publications","url":"https://math.illinois.edu/directory/profile/vesna","checked":"2026-11-05"},{"label":"Alexander Yong official profile and recent publications","url":"https://math.illinois.edu/directory/profile/ayong","checked":"2026-11-05"},{"label":"Jesse Thorner official profile","url":"https://math.illinois.edu/directory/profile/jat9","checked":"2026-11-05"},{"label":"Kevin Ford official profile and recent publications","url":"https://math.illinois.edu/directory/profile/ford126","checked":"2026-11-05"},{"label":"Current mathematics faculty","url":"https://math.illinois.edu/directory/faculty","checked":"2026-11-05"},{"label":"Jesse Thorner institution-linked research list","url":"https://sites.google.com/view/jessethorner/research","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":776,"facultyNames":["Vesna Stojanoska","Alexander Yong","Jesse Thorner","Kevin Ford"]},"university-of-iowa":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, geometry, and logic at University of Iowa. The faculty examples below describe research in those areas.","Frauke Bleher’s listed work concerns arithmetic curves, Galois-module/representation theory, number fields, and cohomological arithmetic. Ryan Kinser’s listed work concerns quiver representations, orbit geometry, Hopf/tensor categories, and connections with equivariant geometry.","Yangbo Ye’s listed work concerns automorphic forms and L-functions, cusp-form Fourier coefficients, resonance sums and subconvexity; also medical imaging. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Frauke Bleher official research/profile","url":"https://www.fraukebleher.com/home/publications","checked":"2026-11-05"},{"label":"Ryan Kinser official research/profile","url":"https://homepage.math.uiowa.edu/~rkinser/research/publ.html","checked":"2026-11-05"},{"label":"Ye official profile","url":"https://math.uiowa.edu/people/yangbo-ye","checked":"2026-11-05"},{"label":"Frauke Bleher official appointment","url":"https://math.uiowa.edu/people/frauke-bleher","checked":"2026-11-05"},{"label":"Ryan Kinser official appointment","url":"https://math.uiowa.edu/people/faculty","checked":"2026-11-05"},{"label":"Ye 2023 original article","url":"https://link.springer.com/article/10.1007/s10114-023-1022-4","checked":"2026-11-05"},{"label":"Ye CV actual date","url":"https://math.uiowa.edu/sites/math.uiowa.edu/files/2024-03/Yangbo%20Ye%20CV.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":793,"facultyNames":["Frauke Bleher","Ryan Kinser","Yangbo Ye"]},"university-of-kansas":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory and algebraic geometry at University of Kansas. The faculty examples below describe research in those areas.","Hai Long (Hailong) Dao’s listed work concerns commutative algebra, local singularities, syzygies and categories of modules, with connections to algebraic geometry and K-theory. Emily E. Witt’s listed work concerns commutative algebra and singularity theory; Frobenius thresholds, local cohomology, differential operators, and computational algebra.","Ruijie Yang’s listed work concerns Hodge theory and D-modules, singularities, birational geometry, abelian varieties and theta divisors; also links to geometric representation theory. Daniel Hernández’s listed work concerns singularities in positive characteristic, Frobenius methods, local cohomology, differential operators and convex methods in birational geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Hai Long (Hailong) Dao official research/profile","url":"https://hailongdao.github.io/DaoCV.pdf","checked":"2026-11-05"},{"label":"Emily E. Witt official research/profile","url":"https://witt.ku.edu/research.html","checked":"2026-11-05"},{"label":"Ruijie Yang official research/profile","url":"https://sites.google.com/view/ruijie-yang/research","checked":"2026-11-05"},{"label":"Hernández coauthor publication date","url":"https://hernandez.ku.edu/research.html","checked":"2026-11-05"},{"label":"Ruijie Yang official appointment","url":"https://math.ku.edu/people/ruijie-yang","checked":"2026-11-05"},{"label":"Hai Long (Hailong) Dao official appointment","url":"https://mathematics.ku.edu/people/hai-long-dao","checked":"2026-11-05"},{"label":"Daniel Hernández official appointment","url":"https://mathematics.ku.edu/people/daniel-hernandez","checked":"2026-11-05"},{"label":"Emily E. Witt official appointment","url":"https://math.ku.edu/people/emily-witt","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":799,"facultyNames":["Hai Long (Hailong) Dao","Emily E. Witt","Ruijie Yang","Daniel Hernández"]},"university-of-kentucky":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and number theory at University of Kentucky. The faculty examples below describe research in those areas.","Xuancheng Shao’s listed work concerns analytic number theory and additive combinatorics, multiplicative functions, character sums and uniformity estimates. Alberto Corso’s listed work concerns commutative and computational algebra, integral dependence, blow-up algebras and homological methods.","Uwe Nagel’s listed work concerns graded rings, Stanley-Reisner ideals and combinatorial algebra. Benjamin Braun’s listed work concerns lattice polytopes, Ehrhart theory, graded algebras, resolutions and triangulations; connections to Gorenstein algebras. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Xuancheng Shao paper evidence","url":"https://scholars.uky.edu/en/persons/xuancheng-shao/","checked":"2026-11-05"},{"label":"Alberto Corso research / publication evidence","url":"https://scholars.uky.edu/en/persons/alberto-corso/","checked":"2026-11-05"},{"label":"Official faculty publications repository","url":"https://uknowledge.uky.edu/math_facpub/","checked":"2026-11-05"},{"label":"Benjamin Braun paper evidence","url":"https://scholars.uky.edu/en/persons/benjamin-braun/","checked":"2026-11-05"},{"label":"Uwe Nagel official homepage","url":"https://www.ms.uky.edu/~uwenagel/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":806,"facultyNames":["Xuancheng Shao","Alberto Corso","Uwe Nagel","Benjamin Braun"]},"university-of-maryland-college-park":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and dynamical systems at University of Maryland - College Park. The faculty examples below describe research in those areas.","Bogdan Zavyalov’s listed work concerns non-Archimedean and p-adic geometry, duality. Uri Bader’s listed work concerns arithmetic groups, rigidity, characters and dynamics.","Shiferaw Berhanu’s listed work concerns several complex variables, CR geometry and PDE; analytic emphasis. Richard Wentworth’s listed work concerns Higgs bundles, nonabelian Hodge theory and character varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty roster","url":"https://www-math.umd.edu/people/faculty.html","checked":"2026-11-05"},{"label":"Research interests","url":"https://www-math.umd.edu/research/faculty-research-interests.html","checked":"2026-11-05"},{"label":"Bogdan Zavyalov official research","url":"https://bogdanzavyalov.com/","checked":"2026-11-05"},{"label":"Richard Wentworth official research","url":"https://www.math.umd.edu/~raw/research.php","checked":"2026-11-05"},{"label":"Shiferaw Berhanu official research","url":"https://bpb-us-e1.wpmucdn.com/blog.umd.edu/dist/2/1123/files/2024/08/vitashif2024.pdf","checked":"2026-11-05"},{"label":"Uri Bader official research","url":"https://www.weizmann.ac.il/math/uribader/publications","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":814,"facultyNames":["Bogdan Zavyalov","Uri Bader","Shiferaw Berhanu","Richard Wentworth"]},"university-of-massachusetts-amherst":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, combinatorics, number theory, and mathematical physics at University of Massachusetts Amherst. The faculty examples below describe research in those areas.","Daoji Huang’s listed work concerns combinatorial algebraic geometry, Schubert/positroid varieties, Gröbner degenerations and representation-theoretic crystals. Paul Hacking’s listed work concerns moduli and birational geometry of surfaces, cluster varieties and mirror symmetry.","Eyal Markman’s listed work concerns hyperkähler geometry, moduli of sheaves, abelian varieties and algebraic/Hodge classes. Paul Gunnells’s listed work concerns arithmetic group cohomology, automorphic forms, Galois representations and computational/representation-theoretic methods. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebraic geometry faculty","url":"https://www.umass.edu/mathematics-statistics/research/algebraic-geometry","checked":"2026-11-05"},{"label":"Number theory faculty","url":"https://www.umass.edu/mathematics-statistics/research/number-theory","checked":"2026-11-05"},{"label":"Paul Hacking research","url":"https://paulhacking.github.io/","checked":"2026-11-05"},{"label":"Eyal Markman official-linked homepage","url":"https://eyalmarkman.github.io/Home-page/","checked":"2026-11-05"},{"label":"Markman author repository linked from homepage","url":"https://arxiv.org/search/?query=Eyal+Markman&searchtype=all&source=header","checked":"2026-11-05"},{"label":"Daoji Huang current homepage","url":"https://www.daojihuang.me/","checked":"2026-11-05"},{"label":"Huang 2026 paper institutional publication record","url":"https://scholars.uky.edu/en/publications/standard-monomials-for-positroid-varieties/","checked":"2026-11-05"},{"label":"Gunnells CV","url":"https://gunnells.github.io/cv.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":828,"facultyNames":["Daoji Huang","Paul Hacking","Eyal Markman","Paul Gunnells"]},"university-of-miami-florida":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and mathematical physics at University of Miami (Florida). The faculty examples below describe research in those areas.","Shulim Kaliman’s listed work concerns affine algebraic geometry, transformation groups, flexible varieties and complex analysis. Ludmil Katzarkov’s listed work concerns algebraic/symplectic geometry and mirror symmetry, including non-Kähler SYZ mirrors, torus fibrations and cohomology.","Michelle Wachs Galloway’s listed work concerns algebraic combinatorics, symmetric functions, Hessenberg varieties, Lie representations and Specht modules. Official repository uses Michelle L. Galloway; publication page uses Michelle Wachs. Drew Armstrong’s listed work concerns algebraic combinatorics, Coxeter groups and hyperplane arrangements. A recent research paper was not verified; the cited 2012 paper is older evidence only. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Kaliman institutional publications","url":"https://scholarship.miami.edu/esploro/profile/shulim_kaliman/output/publication?institution=01UOML_INST","checked":"2026-11-05"},{"label":"Mathematics faculty brochure","url":"https://mathematics.miami.edu/_assets/pdf/grad/brochure.pdf","checked":"2026-11-05"},{"label":"Wachs publications","url":"https://www.math.miami.edu/~wachs/eprints.html","checked":"2026-11-05"},{"label":"Katzarkov institutional research outputs","url":"https://scholarship.miami.edu/esploro/profile/ludmil_katzarkov/output/postedContent?institution=01UOML_INST","checked":"2026-11-05"},{"label":"Wachs Galloway institutional appointment","url":"https://scholarship.miami.edu/esploro/profile/michelle_galloway","checked":"2026-11-05"},{"label":"Armstrong institutional appointment","url":"https://scholarship.miami.edu/esploro/profile/drew_armstrong","checked":"2026-11-05"},{"label":"Armstrong research paper","url":"https://scholarship.miami.edu/esploro/outputs/journalArticle/The-Shi-arrangement-and-the-Ish/991031575926202976","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":838,"facultyNames":["Shulim Kaliman","Ludmil Katzarkov","Michelle Wachs Galloway","Drew Armstrong"]},"university-of-michigan-ann-arbor":{"paragraphs":["Michigan has a broad department with research communities spanning pure mathematics, applied mathematics, scientific computing, probability and mathematics education. Its published directory also distinguishes logic, combinatorics, mathematical physics and mathematical biology, which can otherwise get lost under broad area tags.","Number theory is especially varied in the department's own account: arithmetic geometry, automorphic and p-adic representation theory, Shimura varieties, Galois representations, analytic methods, and algorithmic or computational number theory all appear. This gives a more informative starting point than simply checking a number-theory box.","If your mathematical interests are still moving between nearby fields, look for a set of compatible groups and current seminars. The breadth of the directory helps you build that shortlist; it does not establish that every faculty member in it has room for new students."],"sources":[{"label":"Michigan research communities","url":"https://lsa.umich.edu/math/research.html"},{"label":"Number theory research directions","url":"https://lsa.umich.edu/math/research/number-theory.html"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":846,"facultyNames":["David Speyer","Charlotte Chan","Andrew Snowden","Mattias Jonsson"]},"university-of-minnesota-twin-cities":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and combinatorics at University of Minnesota - Twin Cities. The faculty examples below describe research in those areas.","Kai-Wen Lan’s listed work concerns Shimura varieties, compactifications, automorphic bundles and p-adic cohomology. Peter Webb’s listed work concerns finite-group representations, categories, Mackey/biset functors and homological algebra.","Anna Weigandt’s listed work concerns Schubert calculus, Gröbner geometry, bumpless pipe dreams and quivers. Greg Anderson’s listed work concerns earlier function-field number theory; current official profile emphasizes free probability and random matrices. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty roster","url":"https://cse.umn.edu/math/faculty","checked":"2026-11-05"},{"label":"Kai-Wen Lan official research/appointment","url":"https://www.kwlan.org/academic.html","checked":"2026-11-05"},{"label":"Greg Anderson official research/appointment","url":"https://cse.umn.edu/math/greg-anderson","checked":"2026-11-05"},{"label":"Peter Webb official research/appointment","url":"https://www-users.cse.umn.edu/~webb/Publications/index.html","checked":"2026-11-05"},{"label":"Anna Weigandt official research/appointment","url":"https://weigandt.math.umn.edu/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":860,"facultyNames":["Kai-Wen Lan","Peter Webb","Anna Weigandt","Greg Anderson"]},"university-of-missouri-columbia":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and combinatorics at University of Missouri-Columbia. The faculty examples below describe research in those areas.","Dan Edidin’s listed work concerns equivariant and invariant-theoretic algebraic geometry; recent work also applies group invariants to orbit/phase recovery and imaging. Calin Chindris’s listed work concerns quiver representations, semi-invariants and geometric invariant theory, including combinatorial and matrix-frame applications.","Zhenbo Qin’s listed work concerns Hilbert schemes, moduli of sheaves and maps, Gromov-Witten/Donaldson-Thomas invariants; equivariant cohomology and vertex-operator connections. Rankeya Datta’s listed work concerns positive-characteristic singularities, Frobenius methods and nonarchimedean affinoid algebras. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Dan Edidin official research/profile","url":"https://math.missouri.edu/sites/default/files/people-files/2025-10/vitaOctober25_0.pdf","checked":"2026-11-05"},{"label":"Calin Chindris official research/profile","url":"https://arxiv.org/abs/2603.25554","checked":"2026-11-05"},{"label":"Zhenbo Qin official research/profile","url":"https://arxiv.org/abs/2505.14626","checked":"2026-11-05"},{"label":"Rankeya Datta official research/profile","url":"https://arxiv.org/abs/2511.00753","checked":"2026-11-05"},{"label":"Rankeya Datta official appointment","url":"https://math.missouri.edu/people/faculty/datta","checked":"2026-11-05"},{"label":"Zhenbo Qin official appointment","url":"https://math.missouri.edu/people/faculty/qin","checked":"2026-11-05"},{"label":"Dan Edidin official appointment","url":"https://math.missouri.edu/people/faculty/edidin","checked":"2026-11-05"},{"label":"Calin Chindris official appointment","url":"https://math.missouri.edu/people/faculty/chindris","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":877,"facultyNames":["Dan Edidin","Calin Chindris","Zhenbo Qin","Rankeya Datta"]},"university-of-nebraska-lincoln":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and logic at University of Nebraska-Lincoln. The faculty examples below describe research in those areas.","Mark E. Walker’s listed work concerns algebraic K-theory, noncommutative algebraic geometry, matrix factorizations, singularity categories, and homological commutative algebra. Alexandra Seceleanu’s listed work concerns geometric and computational commutative algebra, syzygies, symbolic powers and asymptotic invariants of ideals with symmetry.","Eloísa Grifo’s listed work concerns symbolic powers, homological algebra, cohomological support varieties, and positive/mixed characteristic methods. Jack Jeffries’s listed work concerns invariant theory, differential operators, local cohomology, positive and mixed characteristic singularities, and symbolic powers. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mark E. Walker official research/profile","url":"https://mark-walker-22.github.io/MarkWalker-Public-CV-February-2025.pdf","checked":"2026-11-05"},{"label":"Alexandra Seceleanu official research/profile","url":"https://aseceleanu.github.io/publications/","checked":"2026-11-05"},{"label":"Eloísa Grifo official research/profile","url":"https://eloisagrifo.github.io/research.html","checked":"2026-11-05"},{"label":"Jack Jeffries official research/profile","url":"https://jack-jeffries.github.io/research.html","checked":"2026-11-05"},{"label":"Mark E. Walker official appointment","url":"https://math.unl.edu/person/mark-walker/","checked":"2026-11-05"},{"label":"Alexandra Seceleanu official appointment","url":"https://math.unl.edu/person/alexandra-seceleanu/","checked":"2026-11-05"},{"label":"Jack Jeffries official appointment","url":"https://math.unl.edu/person/jack-jeffries/","checked":"2026-11-05"},{"label":"Eloísa Grifo official appointment","url":"https://math.unl.edu/person/eloisa-grifo-0/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":884,"facultyNames":["Mark E. Walker","Alexandra Seceleanu","Eloísa Grifo","Jack Jeffries"]},"university-of-new-mexico":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and mathematical physics at University of New Mexico. The faculty examples below describe research in those areas.","Janet Vassilev’s listed work concerns commutative algebra, singularities, closure operations and differential operators on semigroup rings.","The degree route recorded here is Mathematics PhD (Pure Mathematics concentration). Research fit depends on the people and seminars in your specific area; the selected faculty list is not a measure of department size or a promise of available supervision."],"sources":[{"label":"Janet Vassilev homepage","url":"https://math.unm.edu/~jvassil/","checked":"2026-11-05"},{"label":"Janet Vassilev publications","url":"https://math.unm.edu/~jvassil/publications.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":890,"facultyNames":["Janet Vassilev"]},"university-of-north-carolina-at-chapel-hill":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and mathematical physics at University of North Carolina at Chapel Hill. The faculty examples below describe research in those areas.","Olivia Dumitrescu’s listed work concerns birational geometry of blow-ups, divisor/curve cones, Hitchin systems, topological recursion and quantization. Prakash Belkale’s listed work concerns moduli and conformal blocks, eigenvalue problems and Schubert calculus, KZ connections, p-curvature and links with quantum-group representation theory.","Jiuzu Hong’s listed work concerns geometric representation theory, twisted affine Grassmannians/Schubert varieties, conformal blocks and parahoric bundles. David E. V. Rose’s listed work concerns categorification, quantum-group webs, Soergel bimodules, link homology and higher TQFT. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Faculty directory","url":"https://math.unc.edu/people/faculty/","checked":"2026-11-05"},{"label":"Dumitrescu publications","url":"https://sites.google.com/site/oliviamireladumitrescu/publications","checked":"2026-11-05"},{"label":"Hong research","url":"https://hong.web.unc.edu/research/","checked":"2026-11-05"},{"label":"Rose research","url":"https://davidev.web.unc.edu/research/","checked":"2026-11-05"},{"label":"Belkale official faculty profile","url":"https://math.unc.edu/faculty-member/belkale-prakash/","checked":"2026-11-05"},{"label":"Rose current appointment and sabbatical","url":"https://davidev.web.unc.edu/","checked":"2026-11-05"},{"label":"UNC graduate catalog faculty","url":"https://unc-public.courseleaf.com/graduate/schools-departments/mathematics/","checked":"2026-11-05"},{"label":"Belkale 2025 original preprint","url":"https://arxiv.org/abs/2508.20270","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":896,"facultyNames":["Olivia Dumitrescu","Prakash Belkale","Jiuzu Hong","David E. V. Rose"]},"university-of-notre-dame":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and mathematical physics at University of Notre Dame. The faculty examples below describe research in those areas.","Ritvik Ramkumar’s listed work concerns moduli and Hilbert schemes, with commutative-algebra/combinatorics connections. Jeffrey Diller’s listed work concerns several-variable complex dynamics, birational maps, entropy and pluripotential methods.","Michael Gekhtman’s listed work concerns cluster algebras, integrable systems and Poisson geometry. Matthew Dyer’s listed work concerns Coxeter groups, Iwahori-Hecke algebras, Bruhat orders and links with algebraic groups, semisimple and Kac-Moody Lie algebras and quantum groups. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra and algebraic geometry roster","url":"https://math.nd.edu/research/algebra-and-algebraic-geometry/","checked":"2026-11-05"},{"label":"Ramkumar official profile","url":"https://math.nd.edu/people/faculty/ritvik-ramkumar/","checked":"2026-11-05"},{"label":"Diller research","url":"https://academicweb.nd.edu/~jdiller/research.html","checked":"2026-11-05"},{"label":"Gekhtman publication","url":"https://londmathsoc.onlinelibrary.wiley.com/doi/10.1112/blms.13212","checked":"2026-11-05"},{"label":"Dyer research","url":"https://academicweb.nd.edu/~dyer/papers/index.html","checked":"2026-11-05"},{"label":"Dyer Notre Dame profile","url":"https://math.nd.edu/people/faculty/matthew-dyer/","checked":"2026-11-05"},{"label":"Dyer 2024 official coauthor publication record","url":"https://asu.elsevierpure.com/en/publications/shi-arrangements-and-low-elements-in-coxeter-groups/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":905,"facultyNames":["Ritvik Ramkumar","Jeffrey Diller","Michael Gekhtman","Matthew Dyer"]},"university-of-oklahoma-norman":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and combinatorics at University of Oklahoma-Norman. The faculty examples below describe research in those areas.","Greg Muller’s listed work concerns cluster algebras and their geometric and combinatorial structure; cluster theta functions. Travis Mandel’s listed work concerns mirror symmetry, tropical and logarithmic Gromov-Witten theory, cluster algebras and quiver Donaldson-Thomas theory.","András Cristian Lőrincz’s listed work concerns D-modules, singularities, semi-invariants and geometric representation theory. Ameya Pitale’s listed work concerns automorphic representations, Siegel modular forms, L-functions and special values. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Greg Muller official research/profile","url":"https://math.ou.edu/~tmandel/","checked":"2026-11-05"},{"label":"András Cristian Lőrincz official research/profile","url":"https://math.ou.edu/~alorincz/","checked":"2026-11-05"},{"label":"Ameya Pitale official research/profile","url":"https://math.ou.edu/~apitale/Ameya-Research.htm","checked":"2026-11-05"},{"label":"Ameya Pitale official appointment","url":"https://math.ou.edu/people/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":914,"facultyNames":["Greg Muller","Travis Mandel","András Cristian Lőrincz","Ameya Pitale"]},"university-of-oregon":{"paragraphs":["Oregon is worth looking at closely if your interests sit between representation theory, combinatorics, and geometry. The research page connects Brundan and Kleshchev with Lie and algebraic-group representations, Elias with categorification, Ostrik with tensor categories, and Proudfoot with geometry and combinatorics. That is a more useful picture of this part of the department than the single label “algebra.”","There are several different ways into geometry: Addington and Polishchuk work with derived categories, Hanlon studies homological mirror symmetry, Fredrickson studies gauge-theoretic moduli spaces, and Lipshitz and Zemke use symplectic tools in low-dimensional topology. These descriptions suggest overlapping mathematical conversations, although they do not establish shared advising or a particular student culture.","The department also covers harmonic analysis, geometric PDE, probability, and number theory. Eischen’s automorphic and p-adic work, Levin’s Markov-chain research, and Collins-Woodfin’s random-matrix and spin-glass work are examples outside the representation/geometry cluster. Read the individual research descriptions to distinguish those options."],"sources":[{"label":"Oregon — faculty research descriptions","url":"https://naturalsciences.uoregon.edu/mathematics/research"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":922,"facultyNames":["Nicholas Proudfoot","Laura Fredrickson","Alexander Polishchuk","Jonathan Brundan"]},"university-of-pennsylvania":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and combinatorics at University of Pennsylvania. The faculty examples below describe research in those areas.","Ron Donagi’s listed work concerns algebraic geometry, Hitchin systems, Higgs bundles, mirror symmetry and mathematical physics. Sarah Brauner’s listed work concerns algebraic combinatorics, Hecke algebras, crystal combinatorics and representation theory.","Jonathan Block’s listed work concerns complex/noncommutative geometry, dg-categories, Fourier-Mukai transformations, K-theory and index theory. Mona Merling’s listed work concerns adjacent algebraic K-theory/motivic interface; equivariant homotopy and K-theory of varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Standing faculty directory","url":"https://www.math.upenn.edu/people/standing-faculty","checked":"2026-11-05"},{"label":"Ron Donagi recent paper / official publication list","url":"https://arxiv.org/abs/2411.16912","checked":"2026-11-05"},{"label":"Jonathan Block recent paper / official publication list","url":"https://www2.math.upenn.edu/~blockj/papers/HHA-2017-0019-0002-a017.pdf","checked":"2026-11-05"},{"label":"Sarah Brauner recent paper / official publication list","url":"https://www.sarahbrauner.com/research","checked":"2026-11-05"},{"label":"Mona Merling recent paper / official publication list","url":"https://www2.math.upenn.edu/~mmerling/research.html","checked":"2026-11-05"},{"label":"Donagi official profile","url":"https://web.sas.upenn.edu/donagi/","checked":"2026-11-05"},{"label":"Donagi-Fernandez Herrero paper official coauthor listing","url":"https://web.sas.upenn.edu/andresfh/research/","checked":"2026-11-05"},{"label":"Penn State coauthor institutional research record","url":"https://pure.psu.edu/en/publications/on-perrots-index-cocycles/","checked":"2026-11-05"},{"label":"Author-submitted preprint","url":"https://arxiv.org/abs/2207.13411","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":929,"facultyNames":["Ron Donagi","Sarah Brauner","Jonathan Block","Mona Merling"]},"university-of-pittsburgh":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, and geometry at University of Pittsburgh. The faculty examples below describe research in those areas.","Kiumars Kaveh’s listed work concerns Newton-Okounkov bodies, toric/spherical geometry, valuations and tropical geometry; connections with representation theory. Carl Wang-Erickson’s listed work concerns Galois deformation theory, modular forms, Eisenstein congruences and p-adic Langlands.","Roman Fedorov’s listed work concerns principal bundles and reductive groups, Grothendieck-Serre questions, Higgs bundles and motivic methods. Bogdan Ion’s listed work concerns double affine Hecke algebras, Macdonald theory, Lie-theoretic and affine flag/Grassmannian methods. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current mathematics faculty roster","url":"https://www.mathematics.pitt.edu/people/faculty","checked":"2026-11-05"},{"label":"Kiumars Kaveh profile","url":"https://www.mathematics.pitt.edu/people/kiumars-kaveh","checked":"2026-11-05"},{"label":"Kaveh faculty homepage","url":"https://sites.pitt.edu/~kaveh/","checked":"2026-11-05"},{"label":"Toric vector bundles paper: official coauthor university record","url":"https://scholars.uky.edu/en/publications/toric-vector-bundles-valuations-and-tropical-geometry/","checked":"2026-11-05"},{"label":"Roman Fedorov profile","url":"https://www.mathematics.pitt.edu/people/roman-fedorov","checked":"2026-11-05"},{"label":"Fedorov research page","url":"https://sites.pitt.edu/~fedorov/general.html","checked":"2026-11-05"},{"label":"Fedorov recent paper: official publisher","url":"https://ems.press/journals/jems/articles/14299230","checked":"2026-11-05"},{"label":"Bogdan Ion profile","url":"https://www.mathematics.pitt.edu/people/bogdan-ion","checked":"2026-11-05"},{"label":"Ion recent paper: official publisher","url":"https://academic.oup.com/qjmath/article-abstract/76/3/945/8244435","checked":"2026-11-05"},{"label":"Carl Wang-Erickson current profile","url":"https://www.mathematics.pitt.edu/people/carl-wang-erickson","checked":"2026-11-05"},{"label":"Wang-Erickson official publication list","url":"https://sites.pitt.edu/~caw203/pubs.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":940,"facultyNames":["Kiumars Kaveh","Carl Wang-Erickson","Roman Fedorov","Bogdan Ion"]},"university-of-rochester":{"paragraphs":["Rochester's own research overview gives number theory a wide range: algebraic and analytic methods, p-adic arithmetic and cohomology, function fields, modular forms, L-functions, Diophantine geometry and arithmetic dynamics. It is worth looking beyond the broad number-theory label to see which of these directions matches you.","Algebraic topology, particularly homotopy theory, is another explicit concentration in the department's description. The wider research map includes analysis, combinatorics, geometry, probability, ergodic theory and mathematical physics.","The combination of arithmetic and homotopy-theoretic interests is a useful distinguishing detail when building a shortlist. As with any research overview, current faculty profiles and recent seminars are the next check for an actual advising group."],"sources":[{"label":"Rochester mathematical research overview","url":"https://www.sas.rochester.edu/mth/research/index.html"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":947,"facultyNames":["Jonathan Pakianathan","Thomas Tucker","Juan Rivera-Letelier","Saul Lubkin"]},"university-of-south-carolina":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and logic at University of South Carolina. The faculty examples below describe research in those areas.","Matthew Ballard’s listed work concerns derived categories, mirror symmetry, birational geometry and invariant theory. Adela Vraciu’s listed work concerns positive-characteristic commutative algebra, tight closure, Hilbert-Kunz functions and homological properties of rings and modules.","Frank Thorne’s listed work concerns distribution of number fields and class-group torsion, analytic number theory, Shintani zeta functions and arithmetic statistics. Alexander Duncan’s listed work concerns birational geometry, Galois cohomology, algebraic groups, rational surfaces and toric varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Research groups","url":"https://sc.edu/study/colleges_schools/artsandsciences/mathematics/research/index.php","checked":"2026-11-05"},{"label":"Faculty affiliation and research","url":"https://www.sc.edu/study/colleges_schools/artsandsciences/mathematics/our_people/directory/vraciu_adela.php","checked":"2026-11-05"},{"label":"Current faculty affiliation and research","url":"https://thornef.github.io/","checked":"2026-11-05"},{"label":"Official faculty research repository","url":"https://scholarcommons.sc.edu/math_facpub/","checked":"2026-11-05"},{"label":"Duncan author-submitted paper","url":"https://arxiv.org/abs/2507.04474","checked":"2026-11-05"},{"label":"Frank Thorne research / publication evidence","url":"https://arxiv.org/abs/2512.21920","checked":"2026-11-05"},{"label":"Adela Vraciu paper evidence","url":"https://people.math.sc.edu/kustin/research.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":956,"facultyNames":["Matthew Ballard","Adela Vraciu","Frank Thorne","Alexander Duncan"]},"university-of-southern-california":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, topology, and combinatorics at University of Southern California. The faculty examples below describe research in those areas.","Peter Haine’s listed work concerns derived moduli, constructible/perverse sheaves, étale homotopy. Sheel Ganatra’s listed work concerns Fukaya categories, homological mirror symmetry and Hodge structures.","Harold Williams’s listed work concerns cluster varieties, Coulomb branches and geometric representation theory. Greta Panova’s listed work concerns representation-theoretic multiplicities, Schubert combinatorics and computational complexity. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Geometry faculty","url":"https://dornsife.usc.edu/mathematics/geometry-and-topology/","checked":"2026-11-05"},{"label":"Algebra faculty","url":"https://dornsife.usc.edu/mathematics/research-algebra/","checked":"2026-11-05"},{"label":"Haine papers","url":"https://peterjhaine.github.io/research.html","checked":"2026-11-05"},{"label":"Williams homepage","url":"https://www.hwilliams.net/","checked":"2026-11-05"},{"label":"Ganatra papers","url":"https://sheelganatra.com/","checked":"2026-11-05"},{"label":"Panova 2026 paper","url":"https://arxiv.org/abs/2603.20104","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":963,"facultyNames":["Peter Haine","Sheel Ganatra","Harold Williams","Greta Panova"]},"university-of-tennessee-knoxville":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and combinatorics at University of Tennessee, Knoxville. The faculty examples below describe research in those areas.","Dustin Cartwright’s listed work concerns tropical geometry, algebraic matroids, combinatorial algebraic geometry. Shashikant Mulay’s listed work concerns affine algebraic geometry, embeddings of hypersurfaces, commutative algebra and number theory.","Marie Jameson’s listed work concerns modular forms, partition congruences and q-series. Luis Finotti’s listed work concerns p-adic arithmetic, elliptic curve liftings and computation. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty affiliation and research","url":"https://math.utk.edu/research/faculty-in-research-areas/","checked":"2026-11-05"},{"label":"Cartwright papers","url":"https://web.math.utk.edu/~dcartwr1/papers.html","checked":"2026-11-05"},{"label":"Finotti official author research page","url":"https://luisfinotti.org/math/","checked":"2026-11-05"},{"label":"Marie Jameson research / publication evidence","url":"https://arxiv.org/abs/2609.19440","checked":"2026-11-05"},{"label":"Shashikant Mulay research / publication evidence","url":"https://www.sciencedirect.com/science/article/pii/S0021869326003522","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":973,"facultyNames":["Dustin Cartwright","Shashikant Mulay","Marie Jameson","Luis Finotti"]},"university-of-texas-at-arlington":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, logic, and mathematical physics at University of Texas at Arlington. The faculty examples below describe research in those areas.","Michaela Vancliff’s listed work concerns quadratic algebras, quantum projective spaces, point schemes and Ore extensions. Dimitar Grantcharov’s listed work concerns Lie-algebra and Lie-superalgebra representations; recent work studies simple sl(2) modules free of finite rank over a Cartan enveloping algebra.","David A. Jorgensen’s listed work concerns commutative algebra, cohomology, complete intersections and triangulated categories. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics research groups","url":"https://www.uta.edu/academics/schools-colleges/science/departments/mathematics/research","checked":"2026-11-05"},{"label":"Current faculty roster","url":"https://www.uta.edu/academics/schools-colleges/science/departments/mathematics/people","checked":"2026-11-05"},{"label":"Vancliff 2026 paper","url":"https://link.springer.com/article/10.1007/s13366-026-00867-5","checked":"2026-11-05"},{"label":"Grantcharov author-submitted preprint","url":"https://arxiv.org/abs/2601.21197","checked":"2026-11-05"},{"label":"Jorgensen 2026 paper","url":"https://www.sciencedirect.com/science/article/pii/S0022404926000137","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":979,"facultyNames":["Michaela Vancliff","Dimitar Grantcharov","David A. Jorgensen"]},"university-of-texas-at-austin":{"paragraphs":["UT Austin's research spans algebra and number theory, analysis, geometry and topology, dynamics, probability, mathematical physics and computational mathematics. Its research pages also point to the Oden Institute and other cross-campus connections for work involving computation or applications.","Groups and dynamics form a particularly useful intersection to investigate: the department describes connections among geometric structures, low-dimensional topology, ergodic theory, amenability, operator algebras and tilings. The research-training page records past grants and activities; those dates should not be read as a promise of current funding.","The application separates broad research interests and finer topic choices to help route files to readers. It explicitly says that this selection does not commit you to a specialization. That is a reason to state your interests clearly without pretending you already have a fixed dissertation problem."],"sources":[{"label":"Current research areas and initiatives","url":"https://math.utexas.edu/research"},{"label":"Research-training groups and dated activities","url":"https://math.utexas.edu/research/research-training-groups"},{"label":"Use of research interests in admissions","url":"https://math.utexas.edu/academics/graduate-admissions-how-apply"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":985,"facultyNames":["David Ben-Zvi","Bernd Siebert","Sean Keel","Timothy Perutz"]},"university-of-texas-at-dallas":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and number theory at University of Texas at Dallas. The faculty examples below describe research in those areas.","Ronan Conlon’s listed work concerns Calabi-Yau metrics, Kähler-Ricci solitons, special holonomy and geometric analysis. Rizwanur Khan’s listed work concerns analytic number theory, automorphic forms and L-functions.","Nathan Williams’s listed work concerns reflection/braid groups, dynamical algebraic combinatorics and combinatorial representation theory. Carlos Arreche’s listed work concerns differential algebraic geometry, differential/difference Galois theory and symbolic computation. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Conlon research","url":"https://personal.utdallas.edu/~ronan.conlon/","checked":"2026-11-05"},{"label":"Khan research","url":"https://profiles.utdallas.edu/rizwanur.khan","checked":"2026-11-05"},{"label":"Williams research","url":"https://profiles.utdallas.edu/index.php/nathan.williams1","checked":"2026-11-05"},{"label":"Arreche research","url":"https://profiles.utdallas.edu/arreche","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":996,"facultyNames":["Ronan Conlon","Rizwanur Khan","Nathan Williams","Carlos Arreche"]},"university-of-utah":{"paragraphs":["Utah has a clearly identifiable connection between algebraic geometry and commutative algebra. Hacon’s research concerns higher-dimensional birational geometry; Schwede studies singularities and vanishing questions across positive, zero, and mixed characteristic. For a student interested in the minimal model program, singularities, or the algebra behind geometry, those are concrete subjects to investigate here.","There is also a substantial applied side that can disappear from a faculty list centered on algebraic geometry. Utah’s mathematical-biology program organizes its work around areas including biofluids, stochastic models, neuroscience, physiology, ecology, and epidemiology. The wider department lists numerical analysis, probability, optimization, dynamics, and data science alongside its pure-math subjects.","The practical distinction is between these research communities and the particular degree you choose. Utah offers mathematics master’s and doctoral routes and a statistics master’s; the department catalog describes different support arrangements for master’s and PhD students. Compare the route-specific funding information rather than assuming every mathematics offer works the same way."],"sources":[{"label":"Christopher Hacon — research interests","url":"https://www.math.utah.edu/directory/people-info/hacon.php"},{"label":"Karl Schwede — research","url":"https://kschwede.github.io/"},{"label":"Utah mathematical biology — research groups","url":"https://www.math.utah.edu/research/mathbio/groups/"},{"label":"Utah department catalog — degrees and research areas","url":"https://catalog.utah.edu/pages/department-MATH"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1002,"facultyNames":["Gordan Savin","Sean Howe","Christopher Hacon","Karl Schwede"]},"university-of-virginia":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, geometry, mathematical physics, and number theory at University of Virginia. The faculty examples below describe research in those areas.","You Qi’s listed work concerns higher representation theory, small quantum groups and categorification, with algebraic-geometry and low-dimensional topology links. Ken Ono’s listed work concerns number theory, modular-form/partition phenomena and combinatorics, with current AI/data-science interests.","Sara Maloni’s listed work concerns higher Teichmüller theory, character varieties of surface groups, Anosov representations and hyperbolic/complex-projective geometry; adjacent to the requested representation/complex-geometry interests. Peter Abramenko’s listed work concerns buildings and algebraic groups, including reductive groups over polynomial rings and torsors over the affine line. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"You Qi official research/profile","url":"https://you-qi2121.github.io/mypage/research.html","checked":"2026-11-05"},{"label":"Ken Ono official research/profile","url":"https://uva.theopenscholar.com/ken-ono/publications/partition-functions-repel-perfect-powers","checked":"2026-11-05"},{"label":"Sara Maloni official research/profile","url":"https://sites.google.com/view/sara-maloni/research","checked":"2026-11-05"},{"label":"Peter Abramenko official research/profile","url":"https://uva.theopenscholar.com/files/andrei-rapinchuk/files/j_algebra_reprint.pdf","checked":"2026-11-05"},{"label":"Peter Abramenko official appointment","url":"https://math.virginia.edu/people/pa8e/","checked":"2026-11-05"},{"label":"Ken Ono official appointment","url":"https://uva.theopenscholar.com/ken-ono","checked":"2026-11-05"},{"label":"You Qi official appointment","url":"https://you-qi2121.github.io/mypage/","checked":"2026-11-05"},{"label":"Sara Maloni official appointment","url":"https://sites.google.com/view/sara-maloni/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1011,"facultyNames":["You Qi","Ken Ono","Sara Maloni","Peter Abramenko"]},"university-of-washington-seattle":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and logic at University of Washington, Seattle. The faculty examples below describe research in those areas.","Bianca Viray’s listed work concerns arithmetic geometry; rational and algebraic points on varieties, residue fields of closed points on curves, Brauer-Manin obstructions. Julia Pevtsova’s listed work concerns finite group schemes/Hopf algebras, cohomological support and tensor triangular geometry.","Max Lieblich’s listed work concerns moduli, sheaves and arithmetic algebraic geometry; official site mentions recent book, not a current paper list. Sándor Kovács’s listed work concerns singularities, stable varieties and birational/moduli geometry; official publication page is old. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Faculty directory","url":"https://math.washington.edu/people/faculty","checked":"2026-11-05"},{"label":"Sándor Kovács papers","url":"https://sites.math.washington.edu/~kovacs/current/papers.html","checked":"2026-11-05"},{"label":"Max Lieblich official linked homepage","url":"https://max.lieblich.us/","checked":"2026-11-05"},{"label":"Author home linked from UW old home redirect","url":"https://b-viray.github.io/","checked":"2026-11-05"},{"label":"Julia Pevtsova publications","url":"https://sites.math.washington.edu/~julia/Preprints/index.html","checked":"2026-11-05"},{"label":"UW profile","url":"https://math.washington.edu/people/bianca-viray","checked":"2026-11-05"},{"label":"Author arXiv bibliography","url":"https://arxiv.org/a/viray_b_1.html","checked":"2026-11-05"},{"label":"2026 paper","url":"https://arxiv.org/abs/2610.17262","checked":"2026-11-05"},{"label":"2025 paper","url":"https://arxiv.org/abs/2503.07846","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1020,"facultyNames":["Bianca Viray","Julia Pevtsova","Max Lieblich","Sándor Kovács"]},"university-of-wisconsin-madison":{"paragraphs":["Wisconsin's research map gives logic a distinct place alongside algebra and number theory, analysis and PDE, applied mathematics, dynamics, geometry and topology, and probability. That is useful if you want a department where logic is visible as a graduate research direction.","The published qualifying-exam guide makes the logic preparation more concrete: it covers foundations, computability theory and model theory. The same guide has substantial numerical and applied mathematics material, reflecting the department's wider range.","Wisconsin's application guidance explicitly allows broad interests and says that selecting an area is not a commitment. For someone still comparing fields, that is a practical detail about how to describe an honest, developing mathematical direction."],"sources":[{"label":"Research areas","url":"https://www.math.wisc.edu/research/"},{"label":"Qualifying-exam subject guides","url":"https://www.math.wisc.edu/graduate/current-phd/qualifying-exams/topics/"},{"label":"How research interests are used in applications","url":"https://www.math.wisc.edu/graduate/prospective-phd/additional-application-information/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1028,"facultyNames":["Dima Arinkin","Andrei Căldăraru","José Israel Rodriguez","Rajula Srivastava"]},"vanderbilt-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and topology at Vanderbilt University. The faculty examples below describe research in those areas.","Madeline Brandt’s listed work concerns combinatorial and tropical algebraic geometry, moduli of curves/abelian varieties, and their cohomology. Ioana Suvaina’s listed work concerns Kähler and non-Kähler complex geometry, balanced and SKT metrics, four-manifolds, Einstein metrics and Seiberg-Witten theory.","Larry Rolen’s listed work concerns modular, harmonic Maass and quantum modular forms, partitions, L-values, and arithmetic sequences. Rares Rasdeaconu’s listed work concerns real/complex algebraic geometry, real enumerative geometry, Kähler/Hermitian geometry; recent work on Hilbert squares of real surfaces. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Madeline Brandt official research/profile","url":"https://sites.google.com/view/madelinebrandt/research","checked":"2026-11-05"},{"label":"Suvaina coauthor current research list","url":"https://math.vanderbilt.edu/rasdear/","checked":"2026-11-05"},{"label":"Larry Rolen official research/profile","url":"https://math.vanderbilt.edu/rolenl/pubs.html","checked":"2026-11-05"},{"label":"Madeline Brandt official appointment","url":"https://as.vanderbilt.edu/math/bio/madeline-brandt/","checked":"2026-11-05"},{"label":"Author-deposited 2026 paper date","url":"https://arxiv.org/abs/2609.14895v1","checked":"2026-11-05"},{"label":"Suvaina current Vanderbilt bio","url":"https://as.vanderbilt.edu/math/bio/ioana-suvaina/","checked":"2026-11-05"},{"label":"Larry Rolen official appointment","url":"https://math.vanderbilt.edu/rolenl/","checked":"2026-11-05"},{"label":"Suvaina original SKT preprint","url":"https://arxiv.org/abs/1608.08721","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1042,"facultyNames":["Madeline Brandt","Ioana Suvaina","Larry Rolen","Rares Rasdeaconu"]},"virginia-tech":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, algebraic geometry, and number theory at Virginia Tech. The faculty examples below describe research in those areas.","Sarah Arpin’s listed work concerns supersingular elliptic curves, isogeny graphs, characteristic-p arithmetic geometry and post-quantum cryptography. Wenbo Sun’s listed work concerns adjacent analytic/ergodic number theory: multiplicative functions over number fields, nilsequences and combinatorial recurrence.","Daniel Douglas’s listed work concerns quantum topology and its interactions with representation theory: webs, skein algebras, quantum groups and character varieties. Mark Shimozono’s listed work concerns algebraic combinatorics and geometric representation theory, including wreath Macdonald functions and quantum toroidal structures. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra geometry number theory research advisers","url":"https://math.vt.edu/research/algebra-research.html","checked":"2026-11-05"},{"label":"Orr publications including Mihalcea and Shimozono","url":"https://personal.math.vt.edu/dorr/research/","checked":"2026-11-05"},{"label":"Arpin publications","url":"https://sites.google.com/view/saraharpin/research","checked":"2026-11-05"},{"label":"Douglas research","url":"https://sites.google.com/view/daniel-douglas/research","checked":"2026-11-05"},{"label":"Wenbo Sun CV","url":"https://math.vt.edu/content/dam/math_vt_edu/cv-folder/sun-wenbo.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1050,"facultyNames":["Sarah Arpin","Wenbo Sun","Daniel Douglas","Mark Shimozono"]},"washington-state-university":{"paragraphs":["The supplied dossier emphasizes combinatorics and number theory at Washington State University. The faculty examples below describe research in those areas.","Sheng-Chi Liu’s listed work concerns analytic number theory, Siegel modular forms and moments of spinor L-functions.","Matthew Hudelson’s listed work concerns combinatorics and number theory; the recent official CV emphasizes graph enumeration, tree expressions and adjacency matrices. A recent dated research paper was not established. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty roster","url":"https://math.wsu.edu/faculty/","checked":"2026-11-05"},{"label":"Liu: spinor L-functions","url":"https://link.springer.com/article/10.1007/s00229-025-01653-8","checked":"2026-11-05"},{"label":"Hudelson CV","url":"https://facsen.wsu.edu/documents/2026/02/m-hudelson-cv.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1059,"facultyNames":["Sheng-Chi Liu","Matthew Hudelson"]},"washington-university-in-st-louis":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and analysis & PDE at Washington University in St. Louis. The faculty examples below describe research in those areas.","John Shareshian’s listed work concerns algebraic and topological combinatorics with connections to Lie geometry and Hessenberg varieties. Martha Precup’s listed work concerns Lie theory in algebraic geometry, Hessenberg varieties and related combinatorics.","Brett D. Wick’s listed work concerns several complex variables and complex/harmonic analysis; Cauchy-Szegő and Bergman projections, Corona problems and operator theory. John E. McCarthy’s listed work concerns complex function theory and operator theory; inner functions, holomorphic dynamics and composition operators. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"John Shareshian official research/profile","url":"https://www.math.wustl.edu/~precup/","checked":"2026-11-05"},{"label":"Brett D. Wick official research/profile","url":"https://www.math.wustl.edu/~wick/cv.pdf","checked":"2026-11-05"},{"label":"John E. McCarthy official research/profile","url":"https://profiles.wustl.edu/en/publications/a-note-on-composition-operators-on-model-spaces/","checked":"2026-11-05"},{"label":"2026-27 official faculty roster","url":"https://bulletin.wustl.edu/undergrad/artsci/mathematics/","checked":"2026-11-05"},{"label":"John E. McCarthy official appointment","url":"https://math.washu.edu/people/john-e-mccarthy","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1065,"facultyNames":["John Shareshian","Martha Precup","Brett D. Wick","John E. McCarthy"]},"wayne-state-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, topology, and algebraic geometry at Wayne State University. The faculty examples below describe research in those areas.","Ualbai Umirbaev’s listed work concerns automorphisms and derivations of polynomial, free and Lie algebras; connections to affine algebraic geometry. Daniel C. Isaksen’s listed work concerns motivic and classical stable homotopy computations; adjacent to algebraic geometry.","Andrew Salch’s listed work concerns formal groups and chromatic homotopy; recent paper studies spin-c cobordism. This is adjacent to arithmetic geometry rather than a conventional arithmetic-geometry group. Leonid Makar-Limanov’s listed work concerns polynomial automorphisms, Jacobian conjecture and affine algebraic structures. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current mathematics faculty catalog","url":"https://bulletins.wayne.edu/graduate/college-liberal-arts-sciences/mathematics/","checked":"2026-11-05"},{"label":"Makar-Limanov 2025 paper, official journal","url":"https://serdica.math.bas.bg/index.php/serdica/article/view/300","checked":"2026-11-05"},{"label":"Umirbaev 2026 paper, official journal","url":"https://www.sciencedirect.com/science/article/abs/pii/S0021869326001675","checked":"2026-11-05"},{"label":"Salch 2025 paper, official journal","url":"https://doi.org/10.1093/imrn/rnaf291","checked":"2026-11-05"},{"label":"Isaksen 2025/26 paper, official journal","url":"https://www.sciopen.com/article/10.1007/s42543-025-00098-y","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1073,"facultyNames":["Ualbai Umirbaev","Daniel C. Isaksen","Andrew Salch","Leonid Makar-Limanov"]},"wesleyan-university":{"paragraphs":["The supplied dossier emphasizes number theory, dynamical systems, algebra & representation theory, and algebraic geometry at Wesleyan University. The faculty examples below describe research in those areas.","Christopher Rasmussen’s listed work concerns arithmetic algebraic geometry and computational number theory; elliptic/abelian varieties, constrained torsion and Galois representations. David Pollack’s listed work concerns arithmetic cohomology of higher-rank groups, p-adic variation and automorphic forms. The official publication page is old; a recent dated paper was not established.","Han Li’s listed work concerns homogeneous dynamics, arithmetic lattices and effective results for quadratic forms; the reviewed personal research page lists 2022 as its newest paper. Felipe A. Ramírez’s listed work concerns metric Diophantine approximation, ergodic theory, dynamical systems and fractal geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics current faculty and graduate program","url":"https://catalog.wesleyan.edu/departments/math/","checked":"2026-11-05"},{"label":"David Pollack publications and profile","url":"https://dpollack.web.wesleyan.edu/","checked":"2026-11-05"},{"label":"Rasmussen research profile","url":"https://crasmussen.faculty.wesleyan.edu/about/","checked":"2026-11-05"},{"label":"Rasmussen: heavenly elliptic curves","url":"https://link.springer.com/article/10.1007/s40993-026-00757-8","checked":"2026-11-05"},{"label":"Han Li research and publications","url":"https://li-han.weebly.com/research.html","checked":"2026-11-05"},{"label":"Ramírez research and publications","url":"https://felipe-a-ramirez.github.io/research.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1081,"facultyNames":["Christopher Rasmussen","David Pollack","Han Li","Felipe A. Ramírez"]},"worcester-polytechnic-institute":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and mathematical physics at Worcester Polytechnic Institute. The faculty examples below describe research in those areas.","William J. Martin’s listed work concerns association schemes, Bose-Mesner algebras, finite geometry, coding and quantum information; adjacent rather than core arithmetic/complex algebraic geometry.","Jane Ivy Coons’s listed work concerns toric and polyhedral geometry, algebraic statistics, phylogenetic and graphical models. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematical Sciences faculty","url":"https://www.wpi.edu/academics/departments/mathematical-sciences/faculty-staff","checked":"2026-11-05"},{"label":"Jane Ivy Coons official profile","url":"https://www.wpi.edu/people/faculty/jcoons","checked":"2026-11-05"},{"label":"Coons research page linked by official WPI profile","url":"https://sites.google.com/view/jane-ivy-coons/research","checked":"2026-11-05"},{"label":"William J. Martin official profile and papers","url":"https://www.wpi.edu/people/faculty/martin","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1087,"facultyNames":["William J. Martin","Jane Ivy Coons"]},"yale-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, mathematical physics, and algebraic geometry at Yale University. The faculty examples below describe research in those areas.","Alexander Petrov’s listed work concerns arithmetic geometry, p-adic Hodge theory, de Rham complexes and homological methods. Igor Frenkel’s listed work concerns infinite-dimensional Lie algebras, vertex algebras and quaternionic analysis/representation theory.","Alexander Goncharov’s listed work concerns motives, polylogarithms, cluster varieties, moduli of local systems and representation theory. Hee Oh’s listed work concerns homogeneous dynamics and discrete Lie groups with arithmetic/counting applications; adjacent rather than algebraic-number-theory focus. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Petrov research page","url":"https://sasha-pt.github.io/","checked":"2026-11-05"},{"label":"Frenkel official publications","url":"https://campuspress.yale.edu/frenkel/publications/","checked":"2026-11-05"},{"label":"Goncharov official linked research page","url":"https://sasha-goncharov.github.io/","checked":"2026-11-05"},{"label":"Hee Oh official research page","url":"https://campuspress.yale.edu/heeoh/","checked":"2026-11-05"},{"label":"Current ladder faculty","url":"https://math.yale.edu/people/faculty","checked":"2026-11-05"},{"label":"Frenkel recent journal article","url":"https://www.sciencedirect.com/science/article/pii/S0022123626000637","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1093,"facultyNames":["Alexander Petrov","Igor Frenkel","Alexander Goncharov","Hee Oh"]},"mcgill-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, and algebraic geometry at McGill University. The faculty examples below describe research in those areas.","Brent Pym’s listed work concerns Poisson and noncommutative algebraic geometry, deformation quantization, moduli and complex Kähler geometry. Patrick Allen’s listed work concerns Galois representations, automorphy/modularity lifting, deformation rings and Fontaine-Mazur/Langlands questions.","Eyal Z. Goren’s listed work concerns Shimura varieties, abelian varieties in positive characteristic, modular forms, quaternion orders and isogenies. Joel Kamnitzer’s listed work concerns geometric Satake, symplectic duality, Coulomb branches, shifted Yangians and categorification. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current Mathematics faculty","url":"https://www.mcgill.ca/mathstat/people","checked":"2026-11-05"},{"label":"Patrick Allen official profile","url":"https://www.mcgill.ca/mathstat/patrick-allen","checked":"2026-11-05"},{"label":"Patrick Allen institutional-linked papers","url":"https://patrick-allen.github.io/research/","checked":"2026-11-05"},{"label":"Eyal Goren publications","url":"https://www.math.mcgill.ca/goren/publications.html","checked":"2026-11-05"},{"label":"Joel Kamnitzer official homepage and papers","url":"https://www.math.mcgill.ca/jkamni/","checked":"2026-11-05"},{"label":"Brent Pym official homepage","url":"https://www.math.mcgill.ca/bpym/","checked":"2026-11-05"},{"label":"Pym official-linked author paper list","url":"https://arxiv.org/search/?abstracts=show&order=-announced_date_first&query=brent+pym&searchtype=author&size=50","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1103,"facultyNames":["Brent Pym","Patrick Allen","Eyal Z. Goren","Joel Kamnitzer"]},"mcmaster-university":{"paragraphs":["McMaster has a distinctive overlap between combinatorics, commutative algebra, and geometry. The algebra group highlights syzygies, Schubert and Hessenberg varieties, toric geometry, and equivariant or symplectic geometry. Harada, Rajchgot, and Van Tuyl are grouped under combinatorial algebraic geometry, while Franc provides a number-theory direction involving modular forms and L-functions.","Geometry and topology extend beyond that cluster. The department describes work in gauge theory, knots and low-dimensional manifolds, curvature, and general relativity. Boden’s character-variety and knot-invariant work and Kunduri’s geometric questions about Einstein equations illustrate two quite different sides of this activity.","There is also mathematical biology, applied PDE, statistics, and financial mathematics in the same department. For applications centered on the algebra/geometry cluster, check the individual faculty pages as well as the research-group page: the current directory explicitly marks some people as on leave, and group membership by itself does not establish immediate advising availability."],"sources":[{"label":"McMaster — algebra, algebraic geometry, and number theory","url":"https://math.mcmaster.ca/research/algebra-algebraic-geometry-and-number-theory/"},{"label":"McMaster — geometry and topology","url":"https://math.mcmaster.ca/research/geometry-topology/"},{"label":"McMaster — research overview","url":"https://math.mcmaster.ca/research/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1112,"facultyNames":["Adam Van Tuyl","Megumi Harada","Cameron Franc","Jenna Rajchgot"]},"queens-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and probability at Queen’s University. The faculty examples below describe research in those areas.","Gregory G. Smith’s listed work concerns algebraic geometry, commutative algebra and computation; Quot/Hilbert schemes, toric geometry and positivity. Francesco Cellarosi’s listed work concerns number-theoretic stochastic processes, theta/Weyl sums, homogeneous dynamics and ergodic methods.","Noriko Yui’s listed work concerns arithmetic of K3 and Calabi-Yau varieties, modularity of Galois representations and mirror symmetry. Brad Rodgers’s listed work concerns analytic number theory and random matrices; zeta zeros, prime-factor statistics and arithmetic sequences. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Gregory G. Smith official research/profile","url":"https://ggsmith.ca/","checked":"2026-11-05"},{"label":"Francesco Cellarosi official research/profile","url":"https://arxiv.org/abs/2406.05523","checked":"2026-11-05"},{"label":"Noriko Yui official research/profile","url":"https://www.queensu.ca/mathstat/sites/mastwww/files/uploaded_files/yuicv26.pdf","checked":"2026-11-05"},{"label":"Brad Rodgers official research/profile","url":"https://brad-rodgers.github.io/research.html","checked":"2026-11-05"},{"label":"Gregory G. Smith official appointment","url":"https://www.queensu.ca/mathstat/people/faculty/profiles/smith","checked":"2026-11-05"},{"label":"Noriko Yui official appointment","url":"https://www.queensu.ca/mathstat/people/faculty/profiles/yui","checked":"2026-11-05"},{"label":"Brad Rodgers official appointment","url":"https://www.queensu.ca/mathstat/people/faculty/profiles/rodgers","checked":"2026-11-05"},{"label":"Francesco Cellarosi official appointment","url":"https://www.queensu.ca/mathstat/people/faculty/profiles/cellarosi","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1120,"facultyNames":["Gregory G. Smith","Francesco Cellarosi","Noriko Yui","Brad Rodgers"]},"simon-fraser-university":{"paragraphs":["Simon Fraser has a recognizable computational and experimental-mathematics community. Its Centre for Experimental and Constructive Mathematics links computer algebra, discrete mathematics, arithmetic geometry, and number theory. The computer-algebra group develops algorithms and software for Maple and Magma; current projects include polynomial factorization, greatest common divisors, and rational-function reconstruction.","Number theory includes Bruin and Chen in arithmetic geometry and Choi in analytic number theory. The department describes its number-theory community together with nearby UBC and advertises an NTAG seminar. That wider local network is relevant when looking at seminar activity, although it should not be read as automatic cross-institutional supervision.","SFU also lists industrial mathematics, operations research, infection and evolution modeling, and scientific computing. If you want mathematics with an explicit computational component, there are several different versions of it here: symbolic algebra, discrete optimization, arithmetic computations, and numerical or applied work. Compare those separately."],"sources":[{"label":"SFU — Centre for Experimental and Constructive Mathematics","url":"https://www.cecm.sfu.ca/"},{"label":"SFU — computer algebra group","url":"https://www.cecm.sfu.ca/CAG/"},{"label":"SFU — number theory group","url":"https://www.sfu.ca/math/research/number-theory.html"},{"label":"SFU — research areas","url":"https://www.sfu.ca/math/research/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1129,"facultyNames":["Katrina Honigs","Marni Mishna","Nathan Ilten","Stephen Choi"]},"university-of-alberta":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, number theory, and algebraic geometry at University of Alberta. The faculty examples below describe research in those areas.","Charles Doran’s listed work concerns Hodge theory, K3 and Calabi-Yau geometry, mirror symmetry and Landau-Ginzburg models. Vincent Bouchard’s listed work concerns topological recursion, quantum curves, enumerative geometry and W-algebras.","Adam Topaz’s listed work concerns Galois/anabelian geometry and formalized mathematics; current work includes condensed mathematics. Jochen Kuttler’s listed work concerns algebraic transformation groups and descent for Lie algebras. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty roster","url":"https://www.ualberta.ca/en/mathematical-and-statistical-sciences/people/academic-staff.html","checked":"2026-11-05"},{"label":"Doran papers","url":"https://www.charlesdoran.net/papers-923618.html","checked":"2026-11-05"},{"label":"Topaz research and papers","url":"https://adamtopaz.com/","checked":"2026-11-05"},{"label":"Bouchard official-linked publication list","url":"https://arxiv.org/a/bouchard_v_1.html","checked":"2026-11-05"},{"label":"Kuttler derivations paper publisher","url":"https://link.springer.com/article/10.1007/s00229-023-01483-6","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1138,"facultyNames":["Charles Doran","Vincent Bouchard","Adam Topaz","Jochen Kuttler"]},"university-of-british-columbia":{"paragraphs":["UBC's Vancouver mathematics department covers a wide span of pure and applied subjects. Its graduate research directory includes geometry, topology and number theory alongside probability, PDE, mathematical biology, fluid mechanics, numerical analysis and optimization. The algebraic-geometry-oriented selection in this app captures only part of that department.","There is also a regional graduate-course network through PIMS. Network courses can widen the subjects available beyond one term's local offerings, although credit and registration arrangements must be checked. If your interests cross pure mathematics and applications, distinguish the standard mathematics route from programs involving UBC's Institute of Applied Mathematics; their academic requirements are not identical."],"sources":[{"label":"UBC Vancouver mathematics graduate research directory","url":"https://www.grad.ubc.ca/unit/department-mathematics"},{"label":"UBC mathematics degree requirements and IAM distinction","url":"https://webdrupal.math.ubc.ca/graduate/current-students/degree-requirements"},{"label":"PIMS network graduate courses","url":"https://courses.pims.math.ca/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1147,"facultyNames":["Kalle Karu","Rachel Ollivier","Dragos Ghioca","Julia Gordon"]},"university-of-calgary":{"paragraphs":["Calgary is a particularly relevant department to investigate for computational number theory and cryptography. Renate Scheidler’s research concerns algorithms in number fields and function fields, with links to arithmetic geometry and cryptography; her appointment spans mathematics and computer science. That is a concrete example of the kind of connection between the two subjects available here.","The number-theory picture is broader than cryptography. The department groups algebraic geometry, number theory, and cryptography together, links an automorphic-representations group, and describes Nguyen’s work on arithmetic dynamics and Diophantine equations. The same research grouping includes algebra and topology, so the group label contains several different mathematical directions.","If your interests are algorithmic, compare the actual computational problems and methods in faculty papers. If they are more geometric or representation-theoretic, follow the corresponding research group and seminar links. Calgary’s published descriptions support both routes; the broad department label alone does not tell you which one would fit your intended thesis."],"sources":[{"label":"Renate Scheidler — current research and appointments","url":"https://cspages.ucalgary.ca/~rscheidl/"},{"label":"Calgary — algebraic geometry, number theory, and cryptography","url":"https://science.ucalgary.ca/mathematics-statistics/research/areas/algebraic-geometry-number-theory-cryptography"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1156,"facultyNames":["Khoa Nguyen","Renate Scheidler","Alexander Brudnyi","Mayada Shahada"]},"university-of-ottawa":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, number theory, and algebraic geometry at University of Ottawa. The faculty examples below describe research in those areas.","Antonio Lei’s listed work concerns arithmetic geometry and Iwasawa theory of modular forms, Selmer groups and p-adic L-functions. Alistair Savage’s listed work concerns categorical and geometric representation theory, quantum groups and diagrammatic categorification.","Hadi Salmasian’s listed work concerns Lie and quantum groups, Lie superalgebras, diagrammatic categories and representation-theoretic invariant theory. Kirill Zaynullin / Zainoulline’s listed work concerns algebraic groups, motives and oriented cohomology; 2025 paper treats Rost nilpotence and twisted projective varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Antonio Lei profile","url":"https://www.uottawa.ca/faculty-science/professors/antonio-lei","checked":"2026-11-05"},{"label":"Alistair Savage official profile","url":"https://www.uottawa.ca/faculty-science/professors/alistair-savage","checked":"2026-11-05"},{"label":"Hadi Salmasian official profile","url":"https://www.uottawa.ca/faculty-science/professors/hadi-salmasian","checked":"2026-11-05"},{"label":"Kirill Zaynullin official profile","url":"https://www.uottawa.ca/faculty-science/professors/kirill-zaynullin","checked":"2026-11-05"},{"label":"Antonio Lei papers","url":"https://antoniolei.com/publications-eng/","checked":"2026-11-05"},{"label":"Hadi Salmasian personal research page and student openings","url":"https://hsalmasian.github.io/index.html","checked":"2026-11-05"},{"label":"Hadi Salmasian publication list","url":"https://hsalmasian.github.io/pub.htm","checked":"2026-11-05"},{"label":"Alistair Savage papers","url":"https://alistairsavage.ca/publications/","checked":"2026-11-05"},{"label":"Author-deposited 2025 Zainoulline paper","url":"https://arxiv.org/abs/2510.07095","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1166,"facultyNames":["Antonio Lei","Alistair Savage","Hadi Salmasian","Kirill Zaynullin / Zainoulline"]},"university-of-toronto":{"paragraphs":["The supplied dossier emphasizes number theory, algebraic geometry, algebra & representation theory, and analysis & PDE at University of Toronto. The faculty examples below describe research in those areas.","Elden Elmanto’s listed work concerns derived/classical algebraic geometry, motivic cohomology, algebraic K-theory, cycles, birational invariants and motivic homotopy theory. V. Kumar Murty’s listed work concerns algebraic and analytic number theory, motives, periods, motivic Galois groups and arithmetic geometry; also works in mathematical modelling.","Tristan Collins’s listed work concerns complex geometric analysis, Kähler geometry and nonlinear PDE, deformed Hermitian-Yang-Mills equations, algebraic/Bridgeland stability and mirror-symmetry interfaces. Niki Myrto Mavraki’s listed work concerns arithmetic dynamics, heights, unlikely intersections. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Elmanto official profile","url":"https://www.utsc.utoronto.ca/cms/elden-elmanto","checked":"2026-11-05"},{"label":"Kumar Murty current Toronto institutional profile","url":"https://pandemics.utoronto.ca/people/vijayakumar-murty/","checked":"2026-11-05"},{"label":"Collins official profile","url":"https://www.mathematics.utoronto.ca/people/directories/all-faculty/tristan-collins","checked":"2026-11-05"},{"label":"Mavraki research","url":"https://www.math.toronto.edu/myrtomav/Research.html","checked":"2026-11-05"},{"label":"Elmanto advising and research","url":"https://eldenelmanto.com/","checked":"2026-11-05"},{"label":"Faculty publication follow-up: Elden Elmanto","url":"https://doi.org/10.4171/jems/1837","checked":"2026-11-05"},{"label":"Faculty publication follow-up: Tristan Collins","url":"https://arxiv.org/abs/2607.17459","checked":"2026-11-05"},{"label":"Eskandari and Murty research article","url":"https://msp.org/ant/2023/17-1/ant-v17-n1-p06-p.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-09","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1176,"facultyNames":["Elden Elmanto","V. Kumar Murty","Tristan Collins","Niki Myrto Mavraki"]},"university-of-victoria":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and dynamical systems at University of Victoria. The faculty examples below describe research in those areas.","Marcelo Laca’s listed work concerns operator-algebraic and noncommutative-geometric connections to number theory, Bost-Connes systems and equilibrium states; adjacent to arithmetic geometry rather than a conventional arithmetic-geometry group. Benjamin Anderson-Sackaney’s listed work concerns quantum groups, their representations and operator algebras; noncommutative dynamics and boundary actions.","Stephen Scully’s listed work concerns quadratic and hermitian forms, projective homogeneous varieties, algebraic cycles, Chow motives and Milnor K-theory. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Marcelo Laca official research/profile","url":"https://link.springer.com/article/10.1007/s00220-024-05212-2","checked":"2026-11-05"},{"label":"Benjamin Anderson-Sackaney official research/profile","url":"https://sites.google.com/view/benjamin-anderson-sackaney/home","checked":"2026-11-05"},{"label":"Stephen Scully official research/profile","url":"https://web.uvic.ca/~scully/Papers.html","checked":"2026-11-05"},{"label":"Stephen Scully official appointment","url":"https://www.uvic.ca/science/math-statistics/people/home/faculty/scully_stephen.php","checked":"2026-11-05"},{"label":"Marcelo Laca official appointment","url":"https://www.uvic.ca/science/math-statistics/people/home/faculty/laca_marcelo.php","checked":"2026-11-05"},{"label":"Benjamin Anderson-Sackaney official appointment","url":"https://www.uvic.ca/science/math-statistics/people/home/faculty/anderson-sackaney_benjamin.php","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1189,"facultyNames":["Marcelo Laca","Benjamin Anderson-Sackaney","Stephen Scully"]},"university-of-waterloo":{"paragraphs":["At Waterloo, the department name is an important part of choosing a program. Pure Mathematics and Combinatorics and Optimization are separate departments within the Faculty of Mathematics. A broad search for 'math at Waterloo' can hide that distinction, especially if your interests are in algebraic combinatorics, cryptography or quantum computing.","Pure Mathematics lists algebra, analysis, geometry and topology, logic, number theory and quantum information. C&O has its own concentration in algebraic combinatorics, graph theory, discrete and continuous optimization, cryptography and quantum computing. Those are overlapping but different academic homes; identify the relevant department before comparing supervisors or requirements.","For someone whose interests sit between abstract algebra and discrete mathematics, this structure is a reason to examine more than one Waterloo group. The Pure Mathematics faculty included in this app are a useful sample, but they do not cover the whole Faculty of Mathematics."],"sources":[{"label":"Waterloo Pure Mathematics research","url":"https://uwaterloo.ca/pure-mathematics/research"},{"label":"Waterloo Combinatorics and Optimization","url":"https://uwaterloo.ca/combinatorics-and-optimization"},{"label":"C&O doctoral program","url":"https://uwaterloo.ca/future-graduate-students/programs/by-faculty/math/combinatorics-and-optimization-doctor-philosophy-phd"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1196,"facultyNames":["Matthew Satriano","Ruxandra Moraru","Rahim Moosa","Jason Bell"]},"universite-de-montreal":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at Université de Montréal. The faculty examples below describe research in those areas.","Dimitris Koukoulopoulos’s listed work concerns analytic/probabilistic number theory, multiplicative functions, sieves and Diophantine approximation. Jake Levinson’s listed work concerns moduli of stable curves, Schubert calculus, toric geometry, equivariant resolutions and algebraic combinatorics.","Leonid Rybnikov’s listed work concerns Gaudin/Bethe algebras, Yangians, integrable systems and moduli/toric compactifications. Maxime Fortier Bourque’s listed work concerns conformal/Riemann surfaces, Teichmüller geometry and extremal invariants on moduli spaces. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty roster","url":"https://dms.umontreal.ca/fr/repertoire-departement/professeurs","checked":"2026-11-05"},{"label":"Jake Levinson research and papers","url":"https://dms.umontreal.ca/~levinsonj/","checked":"2026-11-05"},{"label":"Koukoulopoulos research, student recruitment and papers","url":"https://dms.umontreal.ca/~koukoulo/","checked":"2026-11-05"},{"label":"Fortier Bourque research and publications","url":"https://dms.umontreal.ca/~fortierboum/","checked":"2026-11-05"},{"label":"Rybnikov 2025 paper","url":"https://arxiv.org/abs/2512.23478","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1205,"facultyNames":["Dimitris Koukoulopoulos","Jake Levinson","Leonid Rybnikov","Maxime Fortier Bourque"]},"york-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, combinatorics, and algebraic geometry at York University. The faculty examples below describe research in those areas.","Nantel Bergeron’s listed work concerns Schubert calculus, quantum cohomology of flag varieties, algebraic combinatorics. Patrick Ingram’s listed work concerns Diophantine geometry, arithmetic dynamics, canonical heights, elliptic curves and surfaces.","Jihyeon Jessie Yang’s listed work concerns tropical geometry and Newton-Okounkov bodies, Bott-Samelson varieties, polytopes and canonical bases for Lie-group representations; current emphasis also on teaching and learning. Norman Purzitsky’s listed work concerns marked Riemann surfaces and Fuchsian groups; geometric fundamental domains and the Nielsen convex region. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Yang current York department roster","url":"https://www.yorku.ca/science/mathstats/faculty-and-instructors/","checked":"2026-11-05"},{"label":"Nantel Bergeron research and publication evidence","url":"https://yorkspace.library.yorku.ca/items/3e780927-37e6-44d7-9497-d423911db72f/full","checked":"2026-11-05"},{"label":"Nantel Bergeron official profile","url":"https://bergeron.mathstats.yorku.ca/","checked":"2026-11-05"},{"label":"Yang official research page","url":"https://www.yorku.ca/professor/jyang/research/","checked":"2026-11-05"},{"label":"Yang current institutional homepage","url":"https://www.yorku.ca/professor/jyang/","checked":"2026-11-05"},{"label":"Norman Purzitsky research and publication evidence","url":"https://purzit.info.yorku.ca/","checked":"2026-11-05"},{"label":"Patrick Ingram research and publication evidence","url":"https://www.yorku.ca/science/research/publications/","checked":"2026-11-05"},{"label":"Patrick Ingram official profile","url":"https://www.yorku.ca/professor/pingram/","checked":"2026-11-05"},{"label":"Purzitsky current York profile","url":"https://www.yorku.ca/science/profiles/faculty/norm-purzitsky/","checked":"2026-11-05"},{"label":"Purzitsky1980 original publisher","url":"https://link.springer.com/article/10.1007/BF01215087","checked":"2026-11-05"},{"label":"Purzitsky1979 original publisher","url":"https://link.springer.com/article/10.1007/BF02392095","checked":"2026-11-05"},{"label":"Purzitsky1980 digitized journal","url":"https://geodesic.mathdoc.fr/volume/MZ_1980__172/","checked":"2026-11-05"},{"label":"Yang original preprint","url":"https://arxiv.org/abs/2106.15695","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1214,"facultyNames":["Nantel Bergeron","Patrick Ingram","Jihyeon Jessie Yang","Norman Purzitsky"]},"aarhus-university":{"paragraphs":["Aarhus has several concrete research clusters that are easy to miss in a short faculty list: homological algebra and representation theory, geometry, automorphic forms, operator algebras and free probability, and analytic directions including inverse problems and stochastic analysis. These groups give the department more variety than an algebraic-geometry-only snapshot suggests.","The Diophantine-approximation group provides another distinctive example, working on irrationality, transcendence and metric approximation. If you are considering Aarhus for number theory, compare that direction with the separate automorphic and representation-theoretic activity rather than treating them as interchangeable. Research-group pages and their seminars are a useful way to make that comparison."],"sources":[{"label":"Aarhus mathematics research groups","url":"https://math.au.dk/en/research/mathematics/"},{"label":"Aarhus Diophantine Approximation","url":"https://projects.au.dk/ada"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1229,"facultyNames":["Simon Kristensen","Gergely Bérczi","Cristiano Spotti","Corina-Gabriela Ciobotaru"]},"algant-consortium":{"paragraphs":["ALGANT is an international master's network focused on algebra, geometry and number theory. It is not one department in a place called 'Europe and Canada': the current consortium lists universities in France, Germany, Italy, the Netherlands and Canada. Students normally spend the two years at two universities in different countries.","The practical comparison is between possible study paths through those departments. A year of coursework in one group and later study in another can expose you to different seminars and mathematical styles; it also means moving institutions. Choose the partner combination for the subjects and eventual project you want, not only for the consortium name."],"sources":[{"label":"ALGANT consortium, partner universities and structure","url":"https://www.algant.eu/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1241,"facultyNames":[]},"eth-zurich":{"paragraphs":["ETH's mathematical environment includes more than its permanent department. The FIM visitor program brings mathematicians to Zurich for research and teaching; the Institute for Theoretical Studies hosts longer visits across mathematics, theoretical physics and theoretical computer science. These visitors and seminars are worth checking when you investigate a particular research group.","The graduate mathematics network also connects ETH with the University of Zurich. Its advertised scope runs from algebra, geometry and number theory through analysis and probability to numerical and applied mathematics. SwissMAP supplies another connection to theoretical physics. The useful comparison is therefore the particular group and training route, not a simple 'pure versus applied' label for ETH as a whole.","The master's and doctoral routes are separate decisions. A master's can provide coursework and thesis experience in this environment; doctoral supervision and recruitment have their own arrangements. Do not infer a future PhD place from the existence of a relevant master's course or visitor."],"sources":[{"label":"ETH mathematical research and visiting institutes","url":"https://math.ethz.ch/research.html"},{"label":"Zurich Graduate School in Mathematics overview","url":"https://zgsm.math.uzh.ch/uploads/media/flyer_colour_03.pdf"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1246,"facultyNames":["Emmanuel Kowalski","Rahul Pandharipande","Sarah Zerbes"]},"heidelberg-university":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, topology, and algebraic geometry at Heidelberg University. The faculty examples below describe research in those areas.","Johannes Walcher’s listed work concerns mirror symmetry, enumerative and motivic invariants, and algebraic geometry in mathematical physics. Alberto Merici’s listed work concerns motives, logarithmic/prismatic cohomology, algebraic K-theory and p-adic geometry.","Alexander Schmidt’s listed work concerns arithmetic homotopy, anabelian geometry, tame cohomology and class field theory. Markus Banagl’s listed work concerns singular spaces, intersection homology, characteristic classes and topology of algebraic varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Invariants and duality roster and recent papers","url":"https://www.math.uni-heidelberg.de/en/sections/id","checked":"2026-11-05"},{"label":"Merici papers","url":"https://merici.eu/research.html","checked":"2026-11-05"},{"label":"Schmidt official publications","url":"https://www.mathi.uni-heidelberg.de/~schmidt/publ_en.html","checked":"2026-11-05"},{"label":"Algebra and arithmetic geometry roster","url":"https://www.math.uni-heidelberg.de/en/abteilungen/aag","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1255,"facultyNames":["Johannes Walcher","Alberto Merici","Alexander Schmidt","Markus Banagl"]},"imperial-college-london":{"paragraphs":["Imperial's pure-mathematics section includes algebra, geometry, number theory, analysis, probability and PDE. Stochastic analysis is a particularly clear example of the links between abstract theory and applications: the group works on stochastic differential equations, rough paths and related analytic questions, with connections to physics, engineering and finance.","That does not make the whole department an applied-mathematics program. Its algebraic and arithmetic groups are separate reasons to investigate Imperial, while London also offers shared graduate-training activities. For geometry and number theory, compare the individual Imperial route with LSGNT's multi-institution training structure; they should not be assumed to have identical applications or first-year arrangements."],"sources":[{"label":"Imperial pure mathematics research","url":"https://www.imperial.ac.uk/pure-mathematics/research/"},{"label":"Imperial stochastic analysis research","url":"https://www.imperial.ac.uk/stochastic-analysis-group/research/"},{"label":"LSGNT shared graduate-training structure","url":"https://www.lsgnt-cdt.ac.uk/programme/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1264,"facultyNames":["Olivier de Gaay Fortman","Yanki Lekili","Simon Donaldson","Ana Caraiani"]},"institute-of-science-and-technology-austria-ista":{"paragraphs":["ISTA's graduate structure is a major part of the fit question. Mathematics belongs to one interdisciplinary PhD program, with students initially doing rotations in different groups rather than arriving permanently attached to one supervisor. The published program describes three rotations of roughly two months each.","That structure can be attractive if you want to explore a couple of mathematical directions or connections to physics, computer science or scientific computing before settling on a thesis group. It also means that comparing ISTA only by a conventional mathematics-department roster misses part of how the program works. Check which groups could plausibly host your rotations and eventual research.","The first phase combines coursework and exploration; a later phase concentrates on the thesis. The inference for an applicant is practical: interest in more than one relevant group is especially useful here. The existence of rotations does not establish that every pair of fields or supervisors is available to every student."],"sources":[{"label":"ISTA interdisciplinary learning and research rotations","url":"https://phd.ista.ac.at/interdisciplinary-learning-and-research/"},{"label":"ISTA PhD program overview","url":"https://phd.ista.ac.at/phd-program-overview/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1275,"facultyNames":["Tamás Hausel","Tim Browning","Vivian Kuperberg"]},"ku-leuven":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, mathematical physics, and number theory at KU Leuven. The faculty examples below describe research in those areas.","Wim Veys’s listed work concerns singularities, monodromy, Igusa/motivic/topological zeta functions and exponential sums. Nero Budur’s listed work concerns singularities, D-modules, mixed Hodge structures, Bernstein-Sato ideals and birational geometry.","Marco Zambon’s listed work concerns Poisson/symplectic geometry, Dirac structures, deformation theory, singular foliations and shifted Kähler structures. Stefaan Vaes’s listed work concerns operator algebras, rigidity and discrete quantum groups; an analytic rather than classical algebraic representation-theory match. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra current faculty roster","url":"https://wis.kuleuven.be/algebra/members","checked":"2026-11-05"},{"label":"Algebra research descriptions","url":"https://wis.kuleuven.be/algebra/research","checked":"2026-11-05"},{"label":"Geometry current faculty roster","url":"https://wis.kuleuven.be/meetkunde/Members","checked":"2026-11-05"},{"label":"Nero Budur current official research/publications","url":"https://www.kuleuven.be/wieiswie/EN/person/00089821","checked":"2026-11-05"},{"label":"Wim Veys current official research/publications","url":"https://wis.kuleuven.be/department-of-mathematics-staff-pages/wim-veys/publications","checked":"2026-11-05"},{"label":"Marco Zambon current official research/publications","url":"https://www.kuleuven.be/wieiswie/en/person/00096206","checked":"2026-11-05"},{"label":"Stefaan Vaes current official research/publications","url":"https://www.kuleuven.be/wieiswie/en/person/00018768","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1282,"facultyNames":["Wim Veys","Nero Budur","Marco Zambon","Stefaan Vaes"]},"leiden-university":{"paragraphs":["Leiden is a particularly relevant place to investigate if you like number theory with an explicit or computational side. Its algebra, geometry and number theory group connects arithmetic geometry and motives with algorithms and cryptology. This is a concrete research profile, rather than a claim that every number-theory topic is equally represented.","The group also sits inside a wider Dutch mathematical network: Mastermath courses, the Intercity Number Theory Seminar and DIAMANT are part of the picture. Leiden coordinates ALGANT, so there are several ways to encounter the group through a master's program. When comparing it with a US department, look at the course network and intended thesis group together."],"sources":[{"label":"Leiden algebra, geometry and number theory group","url":"https://www.universiteitleiden.nl/en/science/mathematics/algebra-geometry-and-number-theory"},{"label":"Leiden mathematics master's overview","url":"https://www.universiteitleiden.nl/en/education/study-programmes/master/mathematics/pdf"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1293,"facultyNames":["Emre Sertöz","Peter Stevenhagen","Peter Bruin","Bart de Smit"]},"london-school-of-geometry-and-number-theory":{"paragraphs":["LSGNT is a shared doctoral training program, rather than a fourth London mathematics department. Its four-year design puts a substantial training year before the main research project. Published program material describes work across UCL, Imperial and King's, with first-year activities based at UCL and spread across the participating institutions.","The first-year structure includes advanced courses, programming and projects; the published handbook describes mini-projects with different supervisors. This is a useful distinction for someone who knows they like geometry or number theory but wants more exposure before committing to a specific thesis direction. Check the current handbook because the exact course plan is revised between cohorts."],"sources":[{"label":"LSGNT program structure","url":"https://www.lsgnt-cdt.ac.uk/programme/"},{"label":"LSGNT first-year training handbook","url":"https://www.lsgnt-cdt.ac.uk/assets/7dqaucm4p73ildjolvd5xh55ycvt0dgx.pdf"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1305,"facultyNames":[]},"scuola-normale-superiore-di-pisa":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and number theory at Scuola Normale Superiore di Pisa. The faculty examples below describe research in those areas.","Angelo Vistoli’s listed work concerns algebraic stacks, moduli, intersection theory and invariants; current paper treats twisted conics and genus-two stable-curve moduli.","Umberto Zannier’s listed work concerns Diophantine geometry, rational/integral points, heights and unlikely intersections; recent work connects rational-distance questions to arithmetic of K3 and general-type surfaces. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"SNS mathematics PhD and current teaching board","url":"https://www.sns.it/en/mathematics","checked":"2026-11-05"},{"label":"Angelo Vistoli official appointment","url":"https://www.sns.it/it/persona/angelo-vistoli","checked":"2026-11-05"},{"label":"Umberto Zannier official appointment","url":"https://www.sns.it/en/persona/umberto-zannier","checked":"2026-11-05"},{"label":"Vistoli 2026 publication in SNS IRIS","url":"https://ricerca.sns.it/handle/11384/173443","checked":"2026-11-05"},{"label":"Zannier 2025 publication in SNS IRIS","url":"https://ricerca.sns.it/handle/11384/158683","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1310,"facultyNames":["Angelo Vistoli","Umberto Zannier"]},"sissa-international-school-for-advanced-studies-trieste":{"paragraphs":["SISSA's mathematics training is organized around focused doctoral programs. Geometry and Mathematical Physics is one major route; Mathematical Analysis, Modelling and Applications is another. Choosing between those research environments is more informative than treating SISSA as a single general mathematics PhD.","The geometry-and-physics material includes moduli spaces, deformation theory, integrable systems, symplectic geometry, quantum groups and mathematical questions coming from field theory. The analysis-and-modelling side connects PDE, numerical analysis and scientific computing with applications. That division makes SISSA especially worth examining when your interests already have a reasonably clear mathematical direction."],"sources":[{"label":"SISSA mathematics research and PhD programs","url":"https://mathematics.sissa.it/en"},{"label":"Geometry and Mathematical Physics research lines (2024 program document)","url":"https://www.sissa.it/sites/default/files/2024-03/Schede%20Info%202024_25.pdf"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1319,"facultyNames":["Antonio Lerario","Giulio Bonelli","Nicolò Sibilla","Alessandro Tanzini"]},"sorbonne-universite":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and mathematical physics at Sorbonne Université. The faculty examples below describe research in those areas.","Gregorio Baldi’s listed work concerns arithmetic geometry, Hodge loci, Shimura varieties, Zilber-Pink and dynamics. Penka Georgieva’s listed work concerns real and open Gromov-Witten theory, symplectic and real enumerative geometry, moduli of real maps and algebraic structures/reconstruction in all genera.","Ilia Itenberg’s listed work concerns real and tropical algebraic geometry, enumerative invariants and refined counts of real curves, with connections to toric surfaces. Benoît Stroh’s listed work concerns Shimura varieties, Galois representations, automorphic forms and arithmetic geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Gregorio Baldi official faculty/publication evidence","url":"https://www.ihes.fr/~baldi/","checked":"2026-11-05"},{"label":"Penka Georgieva official faculty/publication evidence","url":"https://webusers.imj-prg.fr/~penka.georgieva/","checked":"2026-11-05"},{"label":"Ilia Itenberg official faculty/publication evidence","url":"https://webusers.imj-prg.fr/~ilia.itenberg/recent.html","checked":"2026-11-05"},{"label":"Benoît Stroh official faculty/publication evidence","url":"https://webusers.imj-prg.fr/~benoit.stroh/","checked":"2026-11-05"},{"label":"IMJ-PRG current faculty directory and institutional affiliations","url":"https://www.imj-prg.fr/enseignants-chercheur/","checked":"2026-11-05"},{"label":"Itenberg-Shustin primary real-enumerative preprint","url":"https://arxiv.org/abs/2401.06718","checked":"2026-11-05"},{"label":"IMJ-PRG official institute leadership","url":"https://www.imj-prg.fr/linstitut/","checked":"2026-11-05"},{"label":"AIP publisher Georgieva-Zinger final article","url":"https://pubs.aip.org/aip/jmp/article-abstract/66/1/012302/3331952/Algebraic-properties-of-real-Gromov-Witten?redirectedFrom=PDF","checked":"2026-11-05"},{"label":"Stony Brook institutional coauthor record Georgieva-Zinger","url":"https://researchconnect.stonybrook.edu/en/publications/algebraic-properties-of-real-gromov-witten-invariants/","checked":"2026-11-05"},{"label":"Georgieva-Zinger author-submitted preprint","url":"https://arxiv.org/abs/2311.11999","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1328,"facultyNames":["Gregorio Baldi","Penka Georgieva","Ilia Itenberg","Benoît Stroh"]},"technical-university-of-munich-tum":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, mathematical physics, and logic at Technical University of Munich (TUM). The faculty examples below describe research in those areas.","Murad Alim’s listed work concerns mirror symmetry, quantum geometry, topological strings, BPS structures and resurgence. Claudia Scheimbauer’s listed work concerns higher categories, higher Morita theory, derived algebraic geometry and topological field theories.","Deniz Kus’s listed work concerns affine Lie algebras, quantum groups, finite-dimensional representations and links to algebraic geometry. Gregor Kemper’s listed work concerns invariant theory, algebraic group actions and computational commutative algebra. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Algebra group current roster","url":"https://www.math.cit.tum.de/en/algebra/home/","checked":"2026-11-05"},{"label":"Gregor Kemper publications","url":"https://www.math.cit.tum.de/algebra/kemper/publications/","checked":"2026-11-05"},{"label":"Deniz Kus professorship and selected publications","url":"https://www.professoren.tum.de/en/kus-deniz","checked":"2026-11-05"},{"label":"Kus 2026 paper","url":"https://arxiv.org/abs/2605.22571","checked":"2026-11-05"},{"label":"Murad Alim professorship","url":"https://www.professoren.tum.de/en/alim-murad","checked":"2026-11-05"},{"label":"Alim university-linked publications page","url":"https://muradalim.org/publications/","checked":"2026-11-05"},{"label":"Alim 2025 institutional publication record","url":"https://researchportal.hw.ac.uk/en/publications/intrinsic-non-perturbative-topological-strings/","checked":"2026-11-05"},{"label":"Claudia Scheimbauer current appointment","url":"https://www.math.cit.tum.de/en/algebra/scheimbauer/","checked":"2026-11-05"},{"label":"Scheimbauer institutional publication records","url":"https://portal.fis.tum.de/en/organisations/assistant-professorship-of-topology/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1343,"facultyNames":["Murad Alim","Claudia Scheimbauer","Deniz Kus","Gregor Kemper"]},"university-college-london-ucl":{"paragraphs":["The supplied dossier emphasizes number theory, algebraic geometry, algebra & representation theory, and mathematical physics at University College London (UCL). The faculty examples below describe research in those areas.","Luis García’s listed work concerns arithmetic geometry and automorphic forms; theta series, orthogonal Shimura varieties, special cycles and Hodge theory. Recent work treats degenerations and boundary corrections for Kudla-Millson theta series. Aleksander Doan’s listed work concerns gauge theory,symplectic topology,pseudoholomorphic curves and enumerative geometry.","Ed Segal’s listed work concerns derived categories, coherent sheaves, flops, matrix factorizations and mirror symmetry. Dario Beraldo’s listed work concerns geometric Langlands, derived/noncommutative algebraic geometry and categorical arithmetic vanishing cycles. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current academic roster","url":"https://www.ucl.ac.uk/mathematical-physical-sciences/maths/people/academic-and-lecturing-staff","checked":"2026-11-05"},{"label":"Ed Segal official publication evidence","url":"https://www.homepages.ucl.ac.uk/~ucaheps/","checked":"2026-11-05"},{"label":"Dario Beraldo official publication evidence","url":"https://discovery.ucl.ac.uk/id/eprint/10204101/","checked":"2026-11-05"},{"label":"UCL official Luis García homepage","url":"https://www.homepages.ucl.ac.uk/~ucahljg/index.htm","checked":"2026-11-05"},{"label":"Aleksander Doan official publication evidence","url":"https://www.homepages.ucl.ac.uk/~ucahoan/","checked":"2026-11-05"},{"label":"Beraldo promotion confirmation","url":"https://www.ucl.ac.uk/human-resources/hr-policies-procedures-and-advice/academic-careers-framework-and-promotions-processes/promotions","checked":"2026-11-05"},{"label":"Algebraic Geometry publisher final García article","url":"https://api.algebraicgeometry.nl/Article/21568/2026-3-011.pdf","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1353,"facultyNames":["Luis García","Aleksander Doan","Ed Segal","Dario Beraldo"]},"university-of-amsterdam-uva":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, number theory, and algebraic geometry at University of Amsterdam (UvA). The faculty examples below describe research in those areas.","Lenny Taelman’s listed work concerns arithmetic and algebraic geometry, with verified recent publication on derived equivalences of hyper-Kähler varieties and their Hodge and Mukai structures; retain broader number-theoretic interests in the dossier. Raf Bocklandt’s listed work concerns quivers, noncommutative geometry, A-infinity algebras and homological mirror symmetry.","Eric Opdam’s listed work concerns reductive groups, affine Hecke algebras, harmonic analysis and local Langlands. Sergey Shadrin’s listed work concerns moduli of curves, intersection numbers, cohomological field theories and integrable hierarchies. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current algebra, geometry and mathematical physics staff","url":"https://kdvi.uva.nl/research/agmp/algebra-geometry-mathematical-physics.html","checked":"2026-11-05"},{"label":"Lenny Taelman official publications","url":"https://staff.fnwi.uva.nl/l.d.j.taelman/publications.html","checked":"2026-11-05"},{"label":"Raf Bocklandt official publications","url":"https://www.uva.nl/en/profile/b/o/r.r.j.bocklandt/r.r.j.bocklandt.html","checked":"2026-11-05"},{"label":"Eric Opdam official publications","url":"https://www.uva.nl/profiel/o/p/e.m.opdam/e.m.opdam.html","checked":"2026-11-05"},{"label":"Sergey Shadrin official publications","url":"https://staff.fnwi.uva.nl/s.shadrin/publisha.pdf","checked":"2026-11-05"},{"label":"Taelman primary preprint and final journal reference","url":"https://arxiv.org/abs/1906.08081","checked":"2026-11-05"},{"label":"Geometry & Topology publisher author index","url":"https://msp.org/index/ail.php?jpath=gt&l=T","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1363,"facultyNames":["Lenny Taelman","Raf Bocklandt","Eric Opdam","Sergey Shadrin"]},"university-of-bonn-bigs-mathematics-mpim":{"paragraphs":["Bonn is worth thinking of as several overlapping mathematical communities. The university departments, Hausdorff Center, Hausdorff Research Institute and Max Planck Institute supply different pieces of the environment. The visiting programs matter: a prospective student should look at the seminars and longer thematic programs as well as the permanent faculty list.","There is substantial activity around arithmetic, geometry and representation theory, including the Langlands program and newer categorical methods. But Bonn also has research in probability, numerical analysis, inverse problems, mathematical economics and combinatorial optimization. If your interests cross pure mathematics and computation, the Research Institute for Discrete Mathematics is another part of the local picture.","The MSc, BIGS doctorate and MPIM-related arrangements are different routes into that environment. A researcher appearing on a Bonn institute page does not by itself establish which degree they can supervise. It is useful to identify both the mathematical group and the actual graduate program."],"sources":[{"label":"Bonn mathematical research and institutes","url":"https://www.mathematics.uni-bonn.de/en/research/research"},{"label":"Hausdorff Center research program","url":"https://www.exzellenzstrategie.de/en/clusters-of-excellence/hcm/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1374,"facultyNames":["Daniel Huybrechts","Catharina Stroppel","Dennis Gaitsgory","Yeuk Hay Joshua Lam"]},"university-of-cambridge":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and dynamical systems at University of Cambridge. The faculty examples below describe research in those areas.","Ian Grojnowski’s listed work concerns representation theory of reductive/algebraic groups and its geometric connections; the verified paper constructs del Pezzo surfaces through exceptional groups and bundles on elliptic curves. Mark Gross’s listed work concerns logarithmic geometry, enumerative geometry and mirror symmetry.","Holly Krieger’s listed work concerns arithmetic and complex dynamics. Rong Zhou’s listed work concerns Shimura varieties, integral models and arithmetic geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"2027 supervisor availability","url":"https://www.maths.cam.ac.uk/postgrad/finding-dpmms-supervisor","checked":"2026-11-05"},{"label":"Mark Gross official profile and papers","url":"https://www.maths.cam.ac.uk/person/mg475","checked":"2026-11-05"},{"label":"Rong Zhou official profile and papers","url":"https://www.maths.cam.ac.uk/person/rz240","checked":"2026-11-05"},{"label":"Holly Krieger official profile and papers","url":"https://www.maths.cam.ac.uk/person/hk439","checked":"2026-11-05"},{"label":"Cambridge current Ian Grojnowski profile","url":"https://www.maths.cam.ac.uk/person/ig211","checked":"2026-11-05"},{"label":"King's College London coauthor record: Del Pezzo surfaces","url":"https://kclpure.kcl.ac.uk/portal/en/publications/del-pezzo-surfaces-as-springer-fibres-for-exceptional-groups/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-09","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1385,"facultyNames":["Ian Grojnowski","Mark Gross","Holly Krieger","Rong Zhou"]},"university-of-copenhagen":{"paragraphs":["Copenhagen has several recognizable mathematical neighborhoods. Algebra and geometry includes arithmetic geometry, representation theory, topology and geometric analysis. The Centre for Geometry and Topology is one way into that community; its focus is on questions that connect geometric structures with topological methods.","Another substantial part of the department connects analysis with quantum mathematics: operator algebras, mathematical physics, PDE and quantum information appear together in its research structure. Statistics and probability, and insurance and economics, have their own sections. If you are comparing Copenhagen with a department known mainly for pure mathematics, keep these different groups in view."],"sources":[{"label":"Copenhagen research sections and centres","url":"https://www.math.ku.dk/english/research/"},{"label":"Centre for Geometry and Topology research","url":"https://geotop.math.ku.dk/research/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1395,"facultyNames":["Lars Hesselholt","Robert Burklund","Fabien Pazuki","Joachim Kock"]},"university-of-edinburgh-and-agq-cdt-with-glasgow-and-heriot-watt":{"paragraphs":["The algebra, geometry and mathematical-physics route here reaches beyond one Edinburgh department. The AGQ doctoral training centre brings together Edinburgh, Glasgow and Heriot-Watt, with a cohort and training program across those institutions. It is useful to distinguish that route from applying to an individual university's ordinary research-degree program.","The mathematical connections are substantive: representation theory, noncommutative algebra, algebraic and symplectic geometry, topology and quantum field theory are part of the advertised remit. The training includes coursework and activities that cross those subject boundaries, alongside thesis research.","If you like the interface between geometry and physics, look at both the possible supervisor and the shared training calendar. The three-university structure expands the pool of activities, but the degree registration, day-to-day research location and funding route still need to be identified for the specific place you apply to."],"sources":[{"label":"AGQ doctoral training centre","url":"https://www.agq-cdt.org/"},{"label":"Edinburgh algebra, geometry and topology doctorate","url":"https://study.ed.ac.uk/programmes/postgraduate-research/1132-algebra-geometry-and-topology"},{"label":"AGQ training handbook","url":"https://www.agq-cdt.org/wp-content/uploads/2025/09/AGQ-Programme-Handbook-2025-26.pdf"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1408,"facultyNames":["Tudor Dimofte","Iain Gordon","Michael Wemyss","Sue Sierra"]},"university-of-freiburg":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, and number theory at University of Freiburg. The faculty examples below describe research in those areas.","Annette Huber-Klawitter’s listed work concerns motives, periods, arithmetic geometry and special values of L-functions. Wolfgang Soergel’s listed work concerns modular and geometric representation theory, category O, perverse sheaves and D-modules, algebraic groups in positive characteristic; equivariant motives and Hecke-algebra categorification.","Stefan Kebekus’s listed work concerns singular complex algebraic varieties, differential forms, hyperbolicity and special varieties. Abhishek Oswal’s listed work concerns complex and non-archimedean geometry, functional transcendence, unlikely intersections and abelian-variety moduli. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty roster","url":"https://uni-freiburg.de/math-en/faculty-members/","checked":"2026-11-05"},{"label":"Arithmetic geometry research and papers","url":"https://home.mathematik.uni-freiburg.de/arithgeom/forschung.html","checked":"2026-11-05"},{"label":"Complex geometry research and papers","url":"https://cplx.vm.uni-freiburg.de/research/","checked":"2026-11-05"},{"label":"Abhishek Oswal, university-linked faculty homepage","url":"https://sites.google.com/view/abhishekoswal/","checked":"2026-11-05"},{"label":"Freiburg official Soergel publications","url":"https://home.mathematik.uni-freiburg.de/soergel/","checked":"2026-11-05"},{"label":"Soergel-Virk-Wendt primary motives preprint","url":"https://arxiv.org/abs/1809.05480","checked":"2026-11-05"},{"label":"Freiburg current Wolfgang Soergel chair profile","url":"https://uni-freiburg.de/reinemathematik/prof-dr-wolfgang-soergel/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1421,"facultyNames":["Annette Huber-Klawitter","Wolfgang Soergel","Stefan Kebekus","Abhishek Oswal"]},"university-of-munster":{"paragraphs":["Münster has several active research lines that meet around geometry and structure: arithmetic geometry, topology, operator algebras, representation theory and logic are all part of the published research program. The current cluster organizes some of its work around K-theory and cohomology, moduli spaces, groups and actions, and models and universes.","There is also a substantial analytic and probabilistic side, including geometric analysis, PDE, stochastic processes, numerical methods and data-related mathematics. The department's cross-subject program makes it useful to look for several nearby groups rather than reducing Münster to one famous name or one field tag. These are research connections described by the program, not a guarantee of joint supervision."],"sources":[{"label":"Mathematics Münster research areas","url":"https://www.uni-muenster.de/MathematicsMuenster/research/index.shtml"},{"label":"Mathematics Münster research program","url":"https://www.uni-muenster.de/MathematicsMuenster/research/programme/index.shtml"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1429,"facultyNames":["Peter Schneider","Christopher Deninger","Yifei Zhao","Lutz Hille"]},"university-of-oxford":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and mathematical physics at University of Oxford. The faculty examples below describe research in those areas.","Jonathan Pila’s listed work concerns number theory and model theory, especially o-minimality, Diophantine problems and unlikely intersections; the new paper connects Schanuel and multiplicative Zilber-Pink conjectures. Kevin McGerty’s listed work concerns geometric representation theory, quantum groups, symplectic singularities and Springer theory.","Hülya Argüz’s listed work concerns logarithmic and tropical geometry, mirror symmetry, Calabi-Yau and stable-pair moduli. Pierrick Bousseau’s listed work concerns enumerative geometry, mirror symmetry, Gromov-Witten/Donaldson-Thomas theory and log Calabi-Yau surfaces. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jonathan Pila official research page","url":"https://people.maths.ox.ac.uk/pila/ResearchPage.html","checked":"2026-11-05"},{"label":"Kevin McGerty official profile/publications","url":"https://www.maths.ox.ac.uk/people/kevin.mcgerty","checked":"2026-11-05"},{"label":"Hülya Argüz official profile/publications","url":"https://www.maths.ox.ac.uk/people/hulya.arguz","checked":"2026-11-05"},{"label":"Pierrick Bousseau official profile/publications","url":"https://www.maths.ox.ac.uk/people/pierrick.bousseau","checked":"2026-11-05"},{"label":"Geometry members","url":"https://www.maths.ox.ac.uk/groups/geometry/members","checked":"2026-11-05"},{"label":"Number theory members","url":"https://www.maths.ox.ac.uk/groups/number-theory/members","checked":"2026-11-05"},{"label":"Algebra members","url":"https://www.maths.ox.ac.uk/groups/algebra/algebra-members","checked":"2026-11-05"},{"label":"EMS publisher: Combining the conjectures of Schanuel and Zilber-Pink","url":"https://ems.press/journals/rlm/articles/14299588","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-09","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1438,"facultyNames":["Jonathan Pila","Kevin McGerty","Hülya Argüz","Pierrick Bousseau"]},"university-of-pisa":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, combinatorics, and number theory at University of Pisa. The faculty examples below describe research in those areas.","Giulio Bresciani’s listed work concerns anabelian geometry, fundamental groups of varieties and stacks, fields of moduli, arithmetic of rational points. Filippo Gianluca Callegaro’s listed work concerns cohomology of toric/hyperplane arrangements, braid and reflection groups, and combinatorial/topological structures linked to representation theory.","Francesco Sala’s listed work concerns cohomological, K-theoretic and categorified Hall algebras; quantum groups/Yangians; moduli of sheaves and geometric representation theory. Giovanni Gaiffi’s listed work concerns hyperplane and toric arrangements, wonderful compactifications, their cohomology and associated algebraic/Lie-theoretic combinatorics. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Giulio Bresciani: official profile/research/publication page","url":"https://www.unipi.it/en/about-us/organisation/people/giulio-bresciani-124575-en/","checked":"2026-11-05"},{"label":"Filippo Gianluca Callegaro: official profile/research/publication page","url":"https://www.unipi.it/en/about-us/organisation/people/filippo-gianluca-callegaro-96440-en/","checked":"2026-11-05"},{"label":"Francesco Sala: official profile/research/publication page","url":"https://web.dm.unipi.it/sala/","checked":"2026-11-05"},{"label":"Giovanni Gaiffi: official profile/research/publication page","url":"https://www.unipi.it/en/about-us/organisation/people/giovanni-gaiffi-4670-en/","checked":"2026-11-05"},{"label":"Current algebra research areas and roster","url":"https://www.dm.unipi.it/research/areas/algebra/","checked":"2026-11-05"},{"label":"Current geometry research areas and roster","url":"https://www.dm.unipi.it/research/areas/geometry/","checked":"2026-11-05"},{"label":"Francesco Sala: official publications","url":"https://web.dm.unipi.it/sala/publications/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1450,"facultyNames":["Giulio Bresciani","Filippo Gianluca Callegaro","Francesco Sala","Giovanni Gaiffi"]},"university-of-vienna-vienna-school-of-mathematics":{"paragraphs":["Vienna has several distinct mathematical communities inside the same faculty. Logic has a visible home in the Kurt Gödel Research Center; other research areas bring together geometry and mathematical physics, arithmetic and discrete mathematics, PDE, probability, dynamics and computational mathematics. It is worth identifying the relevant group rather than treating 'Vienna mathematics' as a single style of research.","The Erwin Schrödinger and Wolfgang Pauli institutes are part of the local research infrastructure. Within arithmetic, algebra and discrete mathematics, the faculty describes links among geometric group theory, algebraic geometry, Langlands-related number theory and combinatorics. For an applicant, that suggests useful neighboring seminars to investigate alongside the intended supervisor."],"sources":[{"label":"Vienna mathematics research areas and institutes","url":"https://mathematik.univie.ac.at/en/research/"},{"label":"Vienna arithmetic, algebra and discrete mathematics","url":"https://mathematik.univie.ac.at/forschung/arithmetik-algebra-und-diskrete-mathematik"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1466,"facultyNames":["Balázs Szendrői","Anton Mellit","Harald Grobner","Leonhard Summerer"]},"university-of-warwick":{"paragraphs":["Warwick has a particularly varied algebraic-geometry group: birational classification, derived categories, moduli, tropical geometry, K-stability and explicit computational approaches all appear on its research page. That makes it useful to distinguish the kind of algebraic geometry you want to do, rather than treating the department as a single adviser match.","Number theory is similarly spread across Diophantine equations, rational points, modular methods, analytic and probabilistic number theory, and arithmetic combinatorics. The group advertises a research seminar, an informal meeting and a junior seminar, so its seminar pages give a better sense of graduate mathematical life than a ranking does.","There is more to Warwick than those two areas. Its broader research directory includes dynamics, probability, PDE, topology, numerical analysis and applied mathematics. The algebra-and-geometry-heavy faculty selection in this app should not be read as the boundary of the department."],"sources":[{"label":"Warwick algebraic geometry","url":"https://warwick.ac.uk/fac/sci/maths/research/interests/algebraic_geometry/"},{"label":"Warwick number theory and seminars","url":"https://warwick.ac.uk/fac/sci/maths/research/interests/number_theory/"},{"label":"Warwick research areas","url":"https://warwick.ac.uk/fac/sci/maths/intranet/dor/areas/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1476,"facultyNames":["Alexander Kasprzyk","Dmitriy Rumynin","Harry Schmidt","Sam Chow"]},"universite-de-strasbourg":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and combinatorics at Université de Strasbourg. The faculty examples below describe research in those areas.","Emiliano Ambrosi’s listed work concerns arithmetic geometry, monodromy and abelian varieties; real algebraic stacks and topological groupoids. Léa Bittmann’s listed work concerns quantum affine algebras, cluster algebras, friezes and representation-theoretic combinatorics.","Nathalie Wach’s listed work concerns p-adic Hodge theory, crystalline/Galois representations, filtered phi-modules and (phi,Gamma)-modules; additional mathematics-education work. The 2023 article studies crystalline interpretation of the Deligne-Illusie isomorphism. Bora Yalkinoglu’s listed work concerns explicit class field theory, complex/real multiplication, Bost-Connes systems and periodic Witt vectors; arithmetic aspects of integrable systems. Recent preprints develop concrete geometric/arithmetic constructions. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"IRMA current arithmetic/algebraic geometry permanent roster","url":"https://irma.math.unistra.fr/teams/aga.html","checked":"2026-11-05"},{"label":"Current representation/topology roster","url":"https://irma.math.unistra.fr/teams/art.html","checked":"2026-11-05"},{"label":"Emiliano Ambrosi official research evidence","url":"https://research-portal.uu.nl/en/publications/topological-groupoids-with-involution-and-real-algebraic-stacks/","checked":"2026-11-05"},{"label":"Léa Bittmann official research evidence","url":"https://leabittm.github.io/unistra/","checked":"2026-11-05"},{"label":"Bora Yalkinoglu official institutional home page","url":"https://www.math.unistra.fr/~yalkinog/","checked":"2026-11-05"},{"label":"IRMA 10 September 2026 AGA opening-day programme","url":"https://www.math.unistra.fr/conferences/journee-de-rentree-de-l-equipe-aga-1978.html","checked":"2026-11-05"},{"label":"Author preprint: Fermat curves and explicit class field theory for real quadratic number fields","url":"https://arxiv.org/abs/2611.01201","checked":"2026-11-05"},{"label":"Author preprint: Bost-Connes systems and periodic Witt vectors","url":"https://arxiv.org/abs/2507.23759","checked":"2026-11-05"},{"label":"Publisher: Interprétation cristalline de l'isomorphisme de Deligne-Illusie","url":"https://aif.centre-mersenne.org/articles/10.5802/aif.3545/","checked":"2026-11-05"},{"label":"University of Strasbourg IREM journal responsibilities","url":"https://mathinfo.unistra.fr/irem/en/publications/annales-de-didactique-et-de-sciences-cognitives/annales-de-didactique-et-de-sciences-cognitives-english/","checked":"2026-11-05"},{"label":"Publisher: Nathalie Wach, Optimisation","url":"https://www.deboecksuperieur.com/numerique/9782807366732-optimisation","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1488,"facultyNames":["Emiliano Ambrosi","Léa Bittmann","Nathalie Wach","Bora Yalkinoglu"]},"universite-paris-saclay-orsay-hadamard":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and dynamical systems at Université Paris-Saclay (Orsay / Hadamard). The faculty examples below describe research in those areas.","Joël Riou’s listed work concerns motivic homotopy, algebraic K-theory, étale cohomology and derived categories. David Harari’s listed work concerns arithmetic geometry, rational points and approximation, Brauer-Manin obstructions, torsors and homogeneous spaces.","Olivier Schiffmann’s listed work concerns Hall algebras, quantum groups/Yangians and moduli of sheaves/Higgs bundles. Thomas Gauthier’s listed work concerns holomorphic dynamics, pluripotential theory, equidistribution and arithmetic heights. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Joël Riou research","url":"https://www.imo.universite-paris-saclay.fr/~joel.riou/","checked":"2026-11-05"},{"label":"Paris-Saclay official David Harari publication list","url":"https://www.imo.universite-paris-saclay.fr/~david.harari/recherche/","checked":"2026-11-05"},{"label":"Olivier Schiffmann research","url":"https://sites.google.com/site/olivierschiffmann/home/recherche","checked":"2026-11-05"},{"label":"Thomas Gauthier research","url":"https://perso.pages.math.cnrs.fr/users/thomas.gauthier/Recherche.html","checked":"2026-11-05"},{"label":"Schiffmann university profile","url":"https://www.universite-paris-saclay.fr/en/news/olivier-schiffmann-mathematical-hidden-side-physical-theories","checked":"2026-11-05"},{"label":"Thomas Gauthier current appointment","url":"https://perso.pages.math.cnrs.fr/users/thomas.gauthier/index.html","checked":"2026-11-05"},{"label":"Harari-Linh-Lucchini Arteche primary 2026 preprint","url":"https://arxiv.org/abs/2605.03168","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1504,"facultyNames":["Joël Riou","David Harari","Olivier Schiffmann","Thomas Gauthier"]},"utrecht-university":{"paragraphs":["Utrecht's Mathematical Institute is organized around two connected groups: fundamental mathematics and mathematical modelling. The Utrecht Geometry Centre is the main point of reference for the first, with algebraic and differential geometry, topology, logic and number theory in its research range.","The modelling side includes dynamical systems, stochastic analysis, PDE, numerical analysis and other directions. This creates several possible meanings of a 'geometry' or 'analysis' interest at Utrecht. A useful comparison is the specific master's thesis or PhD group and the neighboring research activities, rather than the university name alone."],"sources":[{"label":"Utrecht Mathematical Institute research structure","url":"https://www.uu.nl/organisatie/mathematisch-instituut/onderzoek"},{"label":"Utrecht Geometry Centre","url":"https://utrecht-universiteit.nl/en/research/utrecht-geometry-centre"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1517,"facultyNames":["Johan Commelin","Lennart Meier","Gunther Cornelissen","Peter Koymans"]},"ecole-normale-superieure-psl-paris":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and mathematical physics at École normale supérieure-PSL (Paris). The faculty examples below describe research in those areas.","François Charles’s listed work concerns K3/hyperkähler varieties, Hodge theory, cycles and arithmetic geometry. Julien Marché’s listed work concerns character varieties and surface-group representations, TQFT, geometric quantization and quantum topology.","Gaëtan Chenevier’s listed work concerns automorphic forms, Langlands functoriality and arithmetic of lattices. Giada Grossi’s listed work concerns Iwasawa theory, Euler systems, p-adic L-functions and Shimura-variety cohomology. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"DMA algebra and geometry current personnel","url":"https://www.math.ens.psl.eu/la-recherche/algebre-geometrie/","checked":"2026-11-05"},{"label":"François Charles research","url":"https://www.math.ens.psl.eu/~charles/","checked":"2026-11-05"},{"label":"Gaëtan Chenevier publications","url":"https://gaetan.chenevier.perso.math.cnrs.fr/pub.html","checked":"2026-11-05"},{"label":"Giada Grossi current ENS page","url":"https://www.math.ens.psl.eu/~ggrossi/","checked":"2026-11-05"},{"label":"Julien Marché preprints","url":"https://webusers.imj-prg.fr/~julien.marche/travaux_prepu.html","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1528,"facultyNames":["François Charles","Julien Marché","Gaëtan Chenevier","Giada Grossi"]},"ecole-polytechnique-federale-de-lausanne-epfl":{"paragraphs":["The supplied dossier emphasizes number theory, algebra & representation theory, algebraic geometry, and applied mathematics at École polytechnique fédérale de Lausanne (EPFL). The faculty examples below describe research in those areas.","Florian K. Richter’s listed work concerns ergodic, additive and multiplicative number theory, recurrence and sumsets. Andrei Neguţ’s listed work concerns quantum groups, Hall/shuffle algebras, K-theory and geometric representation theory.","Maryna Viazovska’s listed work concerns number theory and modular forms, sphere packing, interpolation and optimization; current collaborative work also formalizes the dimension-eight packing proof. Dimitri Wyss’s listed work concerns p-adic/motivic integration, Higgs moduli, arithmetic methods for complex geometry and Langlands. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current algebra and number theory groups","url":"https://www.epfl.ch/schools/sb/research/math/research/algebra/","checked":"2026-11-05"},{"label":"Dimitri Wyss official research record","url":"https://infoscience.epfl.ch/entities/publication/40f46448-d656-417a-8c6d-8855578e108d","checked":"2026-11-05"},{"label":"Andrei Neguţ official research record","url":"https://www.epfl.ch/labs/crt/publications/","checked":"2026-11-05"},{"label":"Maryna Viazovska official research record","url":"https://www.epfl.ch/labs/tn/number-theory-tn/publications/","checked":"2026-11-05"},{"label":"Florian K. Richter official research record","url":"https://people.epfl.ch/347153/?lang=en","checked":"2026-11-05"},{"label":"Wyss current appointment","url":"https://people.epfl.ch/dimitri.wyss","checked":"2026-11-05"},{"label":"EPFL current Maryna Viazovska profile","url":"https://people.epfl.ch/maryna.viazovska?lang=en","checked":"2026-11-05"},{"label":"Viazovska and collaborators sphere-packing formalization primary preprint","url":"https://arxiv.org/abs/2604.23468","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1537,"facultyNames":["Florian K. Richter","Andrei Neguţ","Maryna Viazovska","Dimitri Wyss"]},"chinese-university-of-hong-kong":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, mathematical physics, algebraic geometry, and number theory at Chinese University of Hong Kong. The faculty examples below describe research in those areas.","Omar Ahmed Kidwai’s listed work concerns algebraic geometry and mathematical physics: refined BPS structures, topological recursion, quantum curves and Donaldson-Thomas theory. Yi Jen Lee’s listed work concerns adjacent symplectic/gauge topology, Floer and Seiberg-Witten theory; relevance is geometric rather than a claim of core algebraic or arithmetic geometry.","Man Chun Lee’s listed work concerns complex differential geometry and geometric PDE, including deformed Hermitian-Yang-Mills equations and Kähler geometry. Ziquan Yang’s listed work concerns arithmetic geometry, deformation of line bundles, Hodge-theoretic and arithmetic questions for algebraic varieties. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current CUHK Mathematics professor roster","url":"https://www.math.cuhk.edu.hk/people/academic-staff/professors","checked":"2026-11-05"},{"label":"Ziquan Yang official research profile","url":"https://research.cuhk.edu.hk/en/persons/ziquan-yang/","checked":"2026-11-05"},{"label":"Omar Ahmed Kidwai official research profile","url":"https://research.cuhk.edu.hk/en/persons/omar-ahmed-kidwai/","checked":"2026-11-05"},{"label":"Man Chun Lee official research profile","url":"https://research.cuhk.edu.hk/en/persons/man-chun-lee/","checked":"2026-11-05"},{"label":"Yi Jen Lee departmental profile","url":"https://www.math.cuhk.edu.hk/people/academic-staff/yjlee","checked":"2026-11-05"},{"label":"Yi Jen Lee official recent research record","url":"https://research.cuhk.edu.hk/en/publications/morse-theory-and-seiberg-witten-moduli-spaces-of-3-dimensional-co/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1549,"facultyNames":["Omar Ahmed Kidwai","Yi Jen Lee","Man Chun Lee","Ziquan Yang"]},"hong-kong-university-of-science-and-technology":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and combinatorics at Hong Kong University of Science and Technology. The faculty examples below describe research in those areas.","Yu Min’s listed work concerns arithmetic geometry and p-adic Hodge theory, prismatic crystals, p-adic Simpson correspondence and Galois-representation moduli. Eric Marberg’s listed work concerns algebraic combinatorics, crystal bases, Schubert/Grothendieck theory and symmetric orbit closures.","Ivan Chi-Ho Ip’s listed work concerns quantum groups and positive representations, cluster algebras and integrable systems. Chi Hoi Kyle Yip’s listed work concerns analytic number theory, arithmetic combinatorics, Diophantine equations and finite geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current faculty and emeritus roster","url":"https://www.math.hkust.edu.hk/people/","checked":"2026-11-05"},{"label":"Yu Min profile and publications","url":"https://www.math.hkust.edu.hk/people/faculty/profile/maymin/","checked":"2026-11-05"},{"label":"Ivan Chi-Ho Ip profile and publications","url":"https://www.math.hkust.edu.hk/people/faculty/profile/ivanip/","checked":"2026-11-05"},{"label":"Eric Marberg profile and publications","url":"https://www.math.hkust.edu.hk/people/faculty/profile/emarberg/","checked":"2026-11-05"},{"label":"Chi Hoi Kyle Yip profile and publications","url":"https://www.math.hkust.edu.hk/people/faculty/profile/machyip/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1561,"facultyNames":["Yu Min","Eric Marberg","Ivan Chi-Ho Ip","Chi Hoi Kyle Yip"]},"kyoto-university":{"paragraphs":["Kyoto's graduate mathematics sits in two related settings: the Department of Mathematics and the Research Institute for Mathematical Sciences, RIMS. The university describes separate mathematics and mathematical-sciences courses within the same graduate division. Identify which side contains the people you want to work with rather than assuming one undifferentiated program.","The department's research list is broad, including algebraic geometry and number theory, topology, representation theory, analysis, probability and mathematical physics. RIMS adds a substantial workshop and visiting-research environment across pure and applied mathematics and neighboring subjects. For a prospective student, the relevant seminar and supervision arrangement are the concrete things to investigate within that larger network."],"sources":[{"label":"Kyoto Division of Mathematics and Mathematical Sciences","url":"https://www.sci.kyoto-u.ac.jp/en/divisions/math"},{"label":"Kyoto Research Institute for Mathematical Sciences","url":"https://www.kyoto-u.ac.jp/en/research/fields/research-institutes/research-institute-for-mathematical-sciences-rims"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1573,"facultyNames":["Tatsuki Kuwagaki","Katsuhiko Kikuchi","Tatsuyuki Hikita","Eiji Inoue"]},"nanyang-technological-university":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, combinatorics, number theory, and mathematical physics at Nanyang Technological University. The faculty examples below describe research in those areas.","Gary Greaves’s listed work concerns algebraic graph theory and combinatorics; a recent paper uses vertex operators, infinite-wedge representations and symmetric functions in probabilistic models. Bernhard Schmidt’s listed work concerns character sums and cyclotomic methods in finite groups, difference sets and finite geometry; adjacent to number theory, not a verified arithmetic-geometry supervision focus.","Kay Jin Lim’s listed work concerns modular representation theory, finite-dimensional algebras and algebraic combinatorics, including nilCoxeter algebras. Song Heng Chan’s listed work concerns theta functions, q-series, special functions and identities connected with classical number theory. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Mathematics faculty roster","url":"https://www.ntu.edu.sg/spms/about-us/mathematics/people/faculty","checked":"2026-11-05"},{"label":"Kay Jin Lim homepage","url":"https://sites.google.com/view/kay-jin-lim/home","checked":"2026-11-05"},{"label":"Song Heng Chan: 2026 paper","url":"https://www.sciencedirect.com/science/article/pii/S0001870826001891","checked":"2026-11-05"},{"label":"Gary Greaves homepage","url":"https://grwgrvs.github.io/","checked":"2026-11-05"},{"label":"Greaves-Jing-Zhu paper","url":"https://arxiv.org/abs/2602.14190","checked":"2026-11-05"},{"label":"Bernhard Schmidt publication list","url":"https://personal.ntu.edu.sg/bernhard/Publications/publications.html","checked":"2026-11-05"},{"label":"Schmidt: 2025 publisher record","url":"https://link.springer.com/article/10.1007/s10623-025-01701-0","checked":"2026-11-05"},{"label":"Haoran Zhu author/student homepage","url":"https://haoran-horace-zhu.github.io/","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1594,"facultyNames":["Gary Greaves","Bernhard Schmidt","Kay Jin Lim","Song Heng Chan"]},"national-university-of-singapore":{"paragraphs":["NUS has a broad pure-mathematics program rather than just one obvious specialty. Its group descriptions include arithmetic and automorphic forms, representation theory, geometry and topology, dynamics, logic, PDE and probability. For example, the probability listing reaches from random media and interacting particles to random matrices and stochastic differential equations.","The useful distinctions are inside those broad labels. The geometry list includes both algebraic and differential directions, while representation theory connects to automorphic forms and harmonic analysis. NUS also has an applied-and-computational research side. Look at the actual group pages and recent seminars to find the mathematical neighborhood that matches your preparation."],"sources":[{"label":"NUS pure mathematics research groups","url":"https://www.math.nus.edu.sg/research/research-overview/research-in-pure-mathematics/"},{"label":"NUS mathematics research overview","url":"https://www.math.nus.edu.sg/research/research-overview/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1604,"facultyNames":["Yusuf Barış Kartal","De-Qi Zhang","Tien-Cuong Dinh","Ian Gleason"]},"peking-university-school-of-mathematical-sciences-bicmr":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, analysis & PDE, and mathematical physics at Peking University (School of Mathematical Sciences / BICMR). The faculty examples below describe research in those areas.","Emanuel Scheidegger’s listed work concerns mirror symmetry and mathematical physics at the interface with Calabi-Yau geometry, periods, modular forms and quantum K-theory. Zhiqiang Li’s listed work concerns complex dynamics and fractal geometry, expanding Thurston maps, thermodynamic formalism and ergodic optimization; adjacent to complex geometry rather than primarily algebraic geometry.","Bin Zhou’s listed work concerns geometric analysis, nonlinear PDE, canonical Kähler metrics and complex Monge-Ampère equations. Yibo Gao’s listed work concerns algebraic combinatorics closely connected to algebraic geometry and representation theory: Schubert calculus, flag varieties and Bruhat orders. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"BICMR current full-time faculty L-S","url":"https://bicmr.pku.edu.cn/content/lists/11_catid74_3.html","checked":"2026-11-05"},{"label":"BICMR current full-time faculty G-L","url":"https://bicmr.pku.edu.cn/content/lists/11_catid74_2.html","checked":"2026-11-05"},{"label":"School current Z faculty: Zhu, Zhao and Zhou appointments","url":"https://math-en.pku.edu.cn/Faculty/Facuity/Z/index.htm","checked":"2026-11-05"},{"label":"Yibo Gao official research and papers","url":"https://faculty.bicmr.pku.edu.cn/~gaoyibo/research.html","checked":"2026-11-05"},{"label":"Emanuel Scheidegger et al. 2024 paper, Springer","url":"https://link.springer.com/article/10.1007/s00220-024-05006-6","checked":"2026-11-05"},{"label":"Zhiqiang Li official homepage and current papers","url":"https://math.pku.edu.cn/teachers/lizq/","checked":"2026-11-05"},{"label":"Zhiqiang Li et al. 2025 journal paper, Wiley","url":"https://londmathsoc.onlinelibrary.wiley.com/doi/abs/10.1112/plms.70019","checked":"2026-11-05"},{"label":"Bin Zhou current author homepage; updated August 25, 2026","url":"https://bzhou1982.github.io/","checked":"2026-11-05"},{"label":"Bin Zhou and Yuxuan Hu 2026 paper, Wiley","url":"https://londmathsoc.onlinelibrary.wiley.com/doi/abs/10.1112/blms.70323","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1617,"facultyNames":["Emanuel Scheidegger","Zhiqiang Li","Bin Zhou","Yibo Gao"]},"tsinghua-university-mathematics-department-and-qiuzhen-college":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, algebraic geometry, mathematical physics, and number theory at Tsinghua University  -  Mathematics Department and Qiuzhen College. The faculty examples below describe research in those areas.","Jian Zhou’s listed work concerns Gromov-Witten theory, mirror symmetry, elliptic genera, topological recursion, integrable hierarchies and enumerative geometry. Jing Yang’s listed work concerns algebraic number theory and coding-theory applications; recent listed work emphasizes teaching and a 2023 algebraic-number-theory textbook.","Jiayan Yao (Jia-Yan Yao)’s listed work concerns transcendence in positive characteristic, function-field and p-adic number theory, automatic sequences and arithmetic dynamics. Jian Xiao’s listed work concerns positivity of nef classes, Hodge index and hard Lefschetz phenomena, intersection theory, Kähler and projective geometry. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Jian Zhou research evidence","url":"https://sigma-journal.com/2025/068/","checked":"2026-11-05"},{"label":"Jing Yang research evidence","url":"https://cse.hkust.edu.hk/faculty/cding/JOURNALS/it132.pdf","checked":"2026-11-05"},{"label":"Jiayan Yao (Jia-Yan Yao) research evidence","url":"https://arxiv.org/abs/2504.17564","checked":"2026-11-05"},{"label":"Jian Xiao research evidence","url":"https://link.springer.com/article/10.1007/s00208-026-03499-1","checked":"2026-11-05"},{"label":"Jian Zhou official faculty profile","url":"https://math.tsinghua.edu.cn/mathen/info/1312/3539.htm","checked":"2026-11-05"},{"label":"Jian Xiao official faculty profile","url":"https://www.math.tsinghua.edu.cn/info/1125/1604.htm","checked":"2026-11-05"},{"label":"Jiayan Yao (Jia-Yan Yao) official faculty profile","url":"https://math.tsinghua.edu.cn/mathen/info/1312/3490.htm","checked":"2026-11-05"},{"label":"Jing Yang official faculty profile","url":"https://www.tcm.tsinghua.edu.cn/en/info/1003/1050.htm","checked":"2026-11-05"},{"label":"Jiayan Yao 2025 institutional repository","url":"https://orbi.uliege.be/handle/2268/332179","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1642,"facultyNames":["Jian Zhou","Jing Yang","Jiayan Yao (Jia-Yan Yao)","Jian Xiao"]},"university-of-hong-kong":{"paragraphs":["The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and dynamical systems at University of Hong Kong. The faculty examples below describe research in those areas.","Chun-Yin Hui’s listed work concerns Galois representations, arithmetic geometry and algebraic monodromy; recent work relates Lie-algebra representations to independence of Galois monodromy groups. Tuen Wai Ng’s listed work concerns geometric function theory, one/several complex variables and meromorphic dynamics; recent work connects holomorphic maps with dessins and theta functions.","Kei Yuen Chan’s listed work concerns representations of reductive p-adic groups, Hecke algebras, homological methods and branching laws. Ngô Bảo Châu’s listed work concerns geometric Langlands, character sheaves, automorphic representation theory; the recent joint paper studies polar partitions of loop Lie algebras. These topic descriptions do not establish that someone is accepting new students."],"sources":[{"label":"Current mathematics teaching staff","url":"https://www.scifac.hku.hk/people/a-z/department-of-mathematics","checked":"2026-11-05"},{"label":"Ngô at HKU, September 2026","url":"https://lead.hku.hk/en/news/2026/09/ngo-quest-understand/","checked":"2026-11-05"},{"label":"Zhiwei Yun official research list: joint paper with Ngô","url":"https://math.mit.edu/~zyun/research.html","checked":"2026-11-05"},{"label":"Ngô and Yun manuscript metadata","url":"https://arxiv.org/abs/2506.14584","checked":"2026-11-05"},{"label":"Chun-Yin Hui current profile","url":"https://www.scifac.hku.hk/people/hui-chun-yin","checked":"2026-11-05"},{"label":"Hui and Lee paper, official publisher","url":"https://academic.oup.com/imrn/article-abstract/2026/8/rnag071/8660134","checked":"2026-11-05"},{"label":"Tuen Wai Ng current research profile","url":"https://www.scifac.hku.hk/people/ng-tuen-wai","checked":"2026-11-05"},{"label":"Ng and Chiu paper in HKU repository","url":"https://hub.hku.hk/handle/10722/381715","checked":"2026-11-05"},{"label":"Kei Yuen Chan first-party research page linked from HKU","url":"https://sites.google.com/site/keichanmath/research","checked":"2026-11-05"},{"label":"Chan and Huang paper in HKU repository","url":"https://hub.hku.hk/handle/10722/380194","checked":"2026-11-05"}],"basis":"dossier synthesis","checked":"2026-11-05","scope":"A synthesis of the supplied dossier’s selected faculty research. The source report emphasizes algebraic and arithmetic geometry; it is not a complete department review.","dossierPage":1673,"facultyNames":["Chun-Yin Hui","Tuen Wai Ng","Kei Yuen Chan","Ngô Bảo Châu"]},"university-of-tokyo":{"paragraphs":["Tokyo’s Graduate School of Mathematical Sciences is based at Komaba and covers a broad range of mathematics. In algebra and geometry, the current directory includes arithmetic and p-adic geometry, representation theory, singularities, mirror symmetry, and derived geometry. For example, Takagi works on singularities and Frobenius methods, while Tsuji lists p-adic Hodge theory and logarithmic algebraic geometry.","An important organizational detail is the relationship with Kavli IPMU. Some mathematicians on the graduate-school faculty list have IPMU affiliations, including Nakajima, Toda, Kapranov, and Abe. IPMU accepts mathematics graduate students through the Graduate School of Mathematical Sciences; it is not a separate mathematics degree application. Check the intended supervisor’s affiliation and where their activities take place.","The same faculty directory also includes probability, PDE, numerical analysis, statistics, logic, and mathematical physics. Tokyo therefore offers several distinct mathematical communities rather than a single geometry program. For an international applicant, the supervisor, admissions route, and language arrangements need to be considered together with research fit."],"sources":[{"label":"University of Tokyo — graduate-school overview","url":"https://www.u-tokyo.ac.jp/en/academics/grad_mathematical.html"},{"label":"Tokyo — current faculty research directory","url":"https://www.ms.u-tokyo.ac.jp/teacher_e/ichiran_gojyuon_e.html"},{"label":"Kavli IPMU — graduate education routes (Japanese)","url":"https://www.ipmu.jp/ja/students/phd-program"},{"label":"Shunsuke Takagi — research profile","url":"https://www.s.u-tokyo.ac.jp/en/people/takagi_shunsuke/"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked research-group and program sources. Interpretations about fit are inferences from those sources; student atmosphere and adviser availability have not been established.","dossierPage":1686,"facultyNames":["Kazushi Ueda","Tomoyuki Abe","Keiji Oguiso","Shane Kelly"]},"cambridge-mast-part-iii":{"paragraphs":["Part III is an intensive nine-month taught mathematics year. Cambridge students receive the MMath; students arriving from other universities take the MASt route. The main work is advanced lecture courses, with assessment through written examinations and an extended essay.","That structure is the key comparison with a master's built around a long research thesis. Part III is especially a way to acquire more advanced mathematical background and explore possible research directions. The essay gives sustained experience of reading and explaining mathematics, but the course is still organized primarily around taught material.","Use the current course guide and essay topics to decide whether the year's actual offerings suit you. Cambridge also lists study groups, preparatory workshops, a student seminar series and other academic support. Those are concrete parts of the course to examine; the university's research reputation alone does not tell you which classes you would take."],"sources":[{"label":"Cambridge Part III structure and academic support","url":"https://www.maths.cam.ac.uk/postgrad/part-iii/current"},{"label":"Part III essay and examination information","url":"https://www.maths.cam.ac.uk/postgrad/part-iii/current/examinations-and-essays"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked course and assessment guidance; not a claim about individual student experience.","facultyNames":[]},"oxford-omms":{"paragraphs":["OMMS is Oxford's broad nine-month taught master's in mathematical sciences. Much of its teaching is shared with fourth-year mathematics undergraduates, and the choice of courses reaches from pure mathematics to applied mathematics, probability and statistics. It is the more general mathematical-sciences option among the separate Oxford master's cards here.","The program combines advanced courses with a supervised dissertation. Oxford says the dissertation need not produce original results, so it should not be mistaken for a shortened research doctorate. It is a chance to read a subject closely and demonstrate mathematical exposition alongside the taught work.","Compare the actual options and dissertation possibilities with Part III or a longer research-oriented master's. OMMS and MFoCS have different subject emphases and structures; a student interested specifically in logic and theoretical computer science should examine MFoCS as well."],"sources":[{"label":"Oxford OMMS course structure and dissertation","url":"https://www.maths.ox.ac.uk/study-here/postgraduate-study/msc-courses/msc-mathematical-sciences-omms"},{"label":"Oxford MFoCS scope","url":"https://www.maths.ox.ac.uk/members/students/postgraduate-courses/msc-mfocs"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked course guidance; comparisons concern program structure, not rankings.","facultyNames":[]},"oxford-mfocs":{"paragraphs":["MFoCS sits at the interface of pure mathematics and theoretical computer science. It is a useful Oxford route to investigate if your interests involve logic, algebraic or categorical ideas in computation, or the mathematical foundations of computer science. It is not simply a general computer-science conversion course.","The course uses advanced options assessed by mini-projects or examinations, followed by a dissertation extending through the summer. That gives it a different rhythm from the nine-month OMMS course. Compare the available mathematics and computer-science options and possible dissertation topics rather than treating the two master's degrees as interchangeable.","Oxford describes the course as preparation for research in pure mathematics, logic or theoretical computer science, as well as relevant industry work. The choice of topic and supervisor matters: an initial academic adviser need not be the person who supervises the dissertation."],"sources":[{"label":"Oxford MFoCS research scope and assessment","url":"https://www.maths.ox.ac.uk/members/students/postgraduate-courses/msc-mfocs"},{"label":"Oxford MFoCS degree and dissertation structure","url":"https://www.ox.ac.uk/admissions/graduate/courses/msc-mathematics-and-foundations-of-computer-science"}],"basis":"research synthesis","checked":"2026-11-09","scope":"An editorial synthesis of the linked course guidance; comparisons concern program structure, not rankings.","facultyNames":[]},"paris-saclay-m2-aag":{"paragraphs":["M2 Analysis, Arithmetic and Geometry at Université Paris-Saclay is a second-year master's with research thesis lasting 1 academic year (the M2 year). September preparation courses, advanced courses and a supervised thesis. Focuses on preparation for doctoral research in fundamental mathematics; also participates in ALGANT.","The supplied dossier emphasizes algebra & representation theory, algebraic geometry, number theory, and dynamical systems at Université Paris-Saclay (Orsay / Hadamard). The faculty examples below describe research in those areas.","The award is M2. Treat the course list, project or dissertation, and the chance to work with a supervisor as the main things to compare with other master’s programs. Admission to this program does not by itself promise a later doctoral place."],"sources":[{"label":"M2 entry requirements and published cycle","url":"https://www.universite-paris-saclay.fr/en/education/masters-degree/mathematics-and-applications/m2-analysis-arithmetic-and-geometry"},{"label":"Department curriculum and teaching language","url":"https://www.imo.universite-paris-saclay.fr/en/students/masters-programs/mathematics-and-applications/m2/arithmetique-analyse-geometrie/"},{"label":"International scholarship conditions","url":"https://www.universite-paris-saclay.fr/en/admission/bourses-et-aides-financieres/international-masters-scholarships-program"},{"label":"Joël Riou research","url":"https://www.imo.universite-paris-saclay.fr/~joel.riou/","checked":"2026-11-05"},{"label":"Paris-Saclay official David Harari publication list","url":"https://www.imo.universite-paris-saclay.fr/~david.harari/recherche/","checked":"2026-11-05"},{"label":"Olivier Schiffmann research","url":"https://sites.google.com/site/olivierschiffmann/home/recherche","checked":"2026-11-05"},{"label":"Thomas Gauthier research","url":"https://perso.pages.math.cnrs.fr/users/thomas.gauthier/Recherche.html","checked":"2026-11-05"},{"label":"Schiffmann university profile","url":"https://www.universite-paris-saclay.fr/en/news/olivier-schiffmann-mathematical-hidden-side-physical-theories","checked":"2026-11-05"},{"label":"Thomas Gauthier current appointment","url":"https://perso.pages.math.cnrs.fr/users/thomas.gauthier/index.html","checked":"2026-11-05"},{"label":"Harari-Linh-Lucchini Arteche primary 2026 preprint","url":"https://arxiv.org/abs/2605.03168","checked":"2026-11-05"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]},"bonn-msc-mathematics":{"paragraphs":["MSc Mathematics at University of Bonn is a research-oriented master's lasting 2 years / 4 semesters. English-taught research-oriented mathematics, with winter and summer entry.","Bonn is worth thinking of as several overlapping mathematical communities. The university departments, Hausdorff Center, Hausdorff Research Institute and Max Planck Institute supply different pieces of the environment. The visiting programs matter: a prospective student should look at the seminars and longer thematic programs as well as the permanent faculty list.","The award is MSc. Treat the course list, project or dissertation, and the chance to work with a supervisor as the main things to compare with other master’s programs. Admission to this program does not by itself promise a later doctoral place."],"sources":[{"label":"Department admissions, dates and funding","url":"https://www.mathematics.uni-bonn.de/studium/en/prospective-students/entry-into-the-master-study-program-mathematics"},{"label":"Degree requirements","url":"https://www.uni-bonn.de/en/studying/degree-programs/degree-programs-a-z/mathematics-msc?set_language=en"},{"label":"Bonn mathematical research and institutes","url":"https://www.mathematics.uni-bonn.de/en/research/research"},{"label":"Hausdorff Center research program","url":"https://www.exzellenzstrategie.de/en/clusters-of-excellence/hcm/"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]},"eth-msc-mathematics":{"paragraphs":["MSc Mathematics / Applied Mathematics at ETH Zurich is a coursework and thesis master's lasting 1.5 years / 90 ECTS. Mathematics and Applied Mathematics share admissions; admitted students may switch between the two programs.","ETH's mathematical environment includes more than its permanent department. The FIM visitor program brings mathematicians to Zurich for research and teaching; the Institute for Theoretical Studies hosts longer visits across mathematics, theoretical physics and theoretical computer science. These visitors and seminars are worth checking when you investigate a particular research group.","The award is MSc. Treat the course list, project or dissertation, and the chance to work with a supervisor as the main things to compare with other master’s programs. Admission to this program does not by itself promise a later doctoral place."],"sources":[{"label":"MSc degree structure","url":"https://ethz.ch/en/studies/master/degree-programmes/natural-sciences-and-mathematics/mathematics-applied-mathematics.html"},{"label":"2027 application dates","url":"https://ethz.ch/en/studium/master/bewerbung/termine.html"},{"label":"Mathematics application documents","url":"https://ethz.ch/en/studies/master/application/master-mathematik.html"},{"label":"Program admissions and switching","url":"https://math.ethz.ch/studies/master-programmes/mathematics/studieninteressierte.html"},{"label":"ESOP funding","url":"https://ethz.ch/students/en/studies/financial/scholarships/excellencescholarship.html"},{"label":"ETH mathematical research and visiting institutes","url":"https://math.ethz.ch/research.html"},{"label":"Zurich Graduate School in Mathematics overview","url":"https://zgsm.math.uzh.ch/uploads/media/flyer_colour_03.pdf"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]},"algant-master":{"paragraphs":["ALGANT — Algebra, Geometry and Number Theory at ALGANT consortium is an international consortium master's lasting 2 years, normally in two countries. Study at two partner universities in different countries. Partners include Leiden, Paris-Saclay, Bordeaux, Concordia, Duisburg-Essen, Milan, Padua and Regensburg.","ALGANT is an international master's network focused on algebra, geometry and number theory. It is not one department in a place called 'Europe and Canada': the current consortium lists universities in France, Germany, Italy, the Netherlands and Canada. Students normally spend the two years at two universities in different countries.","The award is Master's. Treat the course list, project or dissertation, and the chance to work with a supervisor as the main things to compare with other master’s programs. Admission to this program does not by itself promise a later doctoral place."],"sources":[{"label":"ALGANT consortium, partner universities and structure","url":"https://www.algant.eu/"},{"label":"Admissions, mobility, fees and references","url":"https://algant.eu/pages/apply/"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]},"anu-mathematical-sciences-advanced":{"paragraphs":["Master of Mathematical Sciences (Advanced) at Australian National University is a coursework master's with substantial research lasting 2 years / 96 ANU units; eligible prior study may reduce duration. Coursework plus a year-long supervised project. Progression to research requires a 70% average in the first 48 units and supervisor approval; otherwise students transfer to another qualification.","Bachelor's or equivalent with GPA at least 5.5/7 overall and in eight cognate courses. Admission is competitive. English requirements and overseas student health cover apply. A cognate honours qualification can receive up to 48 units of credit.","The award is MMathScAdv. Treat the course list, project or dissertation, and the chance to work with a supervisor as the main things to compare with other master’s programs. Admission to this program does not by itself promise a later doctoral place."],"sources":[{"label":"2027 Advanced award requirements and fees","url":"https://programsandcourses.anu.edu.au/2027/program/vmasc"},{"label":"Research component","url":"https://science.anu.edu.au/study/masters/master-mathematical-sciences"},{"label":"International application dates","url":"https://study.anu.edu.au/apply/international-applications"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]},"aims-ghana-structured-master":{"paragraphs":["Structured Master's in Mathematical Sciences at African Institute for Mathematical Sciences Ghana is a residential structured master's with research project lasting 1 year, over three semesters. Intensive skills courses, elective review courses and a supervised research project. Residential study includes scientific computing and interdisciplinary mathematics.","A four-year mathematics/science/engineering degree, or a three-year degree plus honours, with substantial mathematics. Other published pathways have cohort-specific conditions; verify those directly. The program serves a Pan-African cohort. Confirm nationality eligibility with the current call; the public pages reviewed do not establish unrestricted global eligibility.","The award is Master's. Treat the course list, project or dissertation, and the chance to work with a supervisor as the main things to compare with other master’s programs. Admission to this program does not by itself promise a later doctoral place."],"sources":[{"label":"Ghana course and partner universities","url":"https://aims.edu.gh/master-of-mathematical-sciences/"},{"label":"Structured-master's requirements and funding","url":"https://aims.edu.gh/application/masters-in-mathematical-sciences-application/"},{"label":"Latest dated network call","url":"https://aims.edu.gh/apply-for-the-aims-masters-in-mathematical-sciences-and-co-op-masters-programmes/"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]},"oxford-dphil-mathematics":{"paragraphs":["DPhil Mathematics at University of Oxford is a research doctorate lasting 3–4 years, full-time. Original supervised research, a thesis and oral examination, with progress assessments and mathematical study beyond the thesis area.","The supplied dossier emphasizes algebra & representation theory, number theory, algebraic geometry, and mathematical physics at University of Oxford. The faculty examples below describe research in those areas.","This card describes the doctoral route: the central work is an original thesis with a supervisor. The separate master’s cards at the same university describe different courses, applications, and funding arrangements."],"sources":[{"label":"DPhil Mathematics 2027–28 admissions","url":"https://www.ox.ac.uk/admissions/graduate/courses/dphil-mathematics"},{"label":"Jonathan Pila official research page","url":"https://people.maths.ox.ac.uk/pila/ResearchPage.html","checked":"2026-11-05"},{"label":"Kevin McGerty official profile/publications","url":"https://www.maths.ox.ac.uk/people/kevin.mcgerty","checked":"2026-11-05"},{"label":"Hülya Argüz official profile/publications","url":"https://www.maths.ox.ac.uk/people/hulya.arguz","checked":"2026-11-05"},{"label":"Pierrick Bousseau official profile/publications","url":"https://www.maths.ox.ac.uk/people/pierrick.bousseau","checked":"2026-11-05"},{"label":"Geometry members","url":"https://www.maths.ox.ac.uk/groups/geometry/members","checked":"2026-11-05"},{"label":"Number theory members","url":"https://www.maths.ox.ac.uk/groups/number-theory/members","checked":"2026-11-05"},{"label":"Algebra members","url":"https://www.maths.ox.ac.uk/groups/algebra/algebra-members","checked":"2026-11-05"},{"label":"EMS publisher: Combining the conjectures of Schanuel and Zilber-Pink","url":"https://ems.press/journals/rlm/articles/14299588","checked":"2026-11-05"}],"basis":"program synthesis","checked":"2026-11-09","scope":"Program structure from the linked course research, with department context where available. No claims about student atmosphere or adviser availability are inferred.","facultyNames":[]}};
